Ceviri.ekle("hy","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["Հադրամաուտը դարձավ օսմանյան սանջակ. ներքին կառավարումը մնաց Քասիրի առաջնորդներին", "d80f8d20"], "d": ["Հադըմ Սուլեյման փաշայի հնդկական արշավանքի ժամանակ օսմանյան կառավարման անցած Հադրամաուտը կազմավորվեց որպես Եմենին ենթակա սանջակ։ Սակայն Հադրամաուտի ներսում կառավարումը փաստացի իրենց ձեռքում պահեցին Քասիրի ցեղախմբի առաջնորդները. օսմանյան տիրապետությունը սահմանափակ մնաց ափով և հարկային կապով։", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["Զեյդի իմամ ալ-Մութավաքքիլ ալալլահը ներխուժեց Հադրամաուտ. Քասիրիների սուլթանությունը կապվեց Եմենի իմամությանը", "21ad9c85"], "d": ["1635 թ. Եմենից օսմանցիների հեռանալուց հետո հզորացած Զեյդի իմամությունը իմամ ալ-Մութավաքքիլ ալալլահի օրոք բանակ ուղարկեց և ներխուժեց Հադրամաուտ։ Այսպիսով Քասիրիների իշխանությունը ներքին Հադրամաուտում մոտ կես դար մնաց Եմենի իմամությանը ենթակա. 18-րդ դարի առաջին կեսին, երբ թուլացավ իմամների և Քասիրիների ազդեցությունը, կառավարումը կրկին անցավ տեղական ցեղախմբերին։", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["Աբդուլլահ իբն Ռաշիդը Հայիլի ամիրայությունը վերցրեց Իբն Ալի ընտանիքից. հիմնվեց Շամմարի (Ռաշիդյան) ամիրայությունը", "357cc1a0"], "d": ["Շամմար ցեղախմբի ամենամեծ ճյուղ Աբդեին պատկանող Աբդուլլահ իբն Ռաշիդը, իր եղբայր Ուբեյդի հետ Հայիլը կառավարող Իբն Ալի ընտանիքի դեմ սկսած պայքարը 1835 թ. հաղթելով, տիրեց ամիրայությանը։ Հայիլը, Միջագետք-Հիջազ առևտրի և հաջի ճանապարհի վրա իր դիրքով, դարձավ Ռաշիդյանների՝ մինչև 1921 թ. տևելիք Ջաբալ Շամմարի տիրապետության կենտրոնը։", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["Օսմանյան բեյլիքի հիմնադրումը", "9f0b7c0a"], "d": ["Կայը ցեղից Օսման Ղազիի՝ Սոյութ-Դոմանիչի շրջակայքում ինքնուրույն գործել սկսելն ընդունվում է որպես Օսմանյան պետության հիմնադրման ավանդական դարձած սկզբնակետ. որոշ պատմաբաններ իրական շրջադարձային կետ են համարում 1302 թվականի Բաֆեոսի հաղթանակը։ Բյուզանդական սահմանամերձ շրջանում իր դիրքի շնորհիվ բեյլիքը ղազաթի (սրբազան պատերազմի) արշավանքներով արագ ուժ հավաքեց։ Սելջուկյան ժառանգության քայքայման այս պայմաններում Օսման Ղազին իր շուրջը համախմբեց ախիներին, ղազիներին և քոչվոր թուրքմեններին. Շեյխ Էդեբալիի հետ նրա հաստատած կապը համարվում է բեյլիքի հոգևոր լեգիտիմության հիմքը։ Նույն ամսաթվին միացած այլ վայրեր՝ Ինեգյոլ, Յարհիսար։", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Բուրսայի նվաճումը", "98c727fa"], "d": ["Տարիներ շարունակ շրջափակման մեջ պահված Բուրսան հանձնվեց Օրհան Ղազիին, որը ղեկավարում էր պաշարման վերջին փուլը. քաղաքը դարձավ բեյլիքի առաջին մեծ մայրաքաղաքը։ Ավանդվում է, որ նվաճման լուրը հասցվել է մահվան մահճում գտնվող Օսման Ղազիին. Օսման Ղազին իր կտակի համաձայն թաղվեց Բուրսայում։ Կարճ ժամանակում քաղաքը հարստացավ մզկիթներով, իմարեթներով և մեդրեսեներով և դարձավ վաղ օսմանյան քաղաքաշինության օրինակը։", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Իզնիկի նվաճումը", "a846a811"], "d": ["Անատոլիայում Բյուզանդիայի կարևորագույն կենտրոններից մեկը՝ Իզնիկը (Նիկիա), 1329 թվականի Պելեկանոնի հաղթանակից հետո կորցնելով դիմադրելու հույսը՝ հանձնվեց Օրհան Ղազիին։ Առաջին օսմանյան մեդրեսեն հիմնվեց այստեղ, և Դավուդ Կայսերիի նման գիտնականները սկսեցին դասավանդել. քաղաքը դարձավ վաղ շրջանի գիտական կենտրոնը։ Այա Սոֆիա եկեղեցին վերածվեց մզկիթի՝ դրսևորելով նվաճման ավանդույթի վաղ օրինակներից մեկը։", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Իզմիթի նվաճումը", "06a35035"], "d": ["Իզմիթի (Նիկոմեդիա) անկմամբ Անատոլիական ափին Բյուզանդիայի վերջին կարևոր ամրոցը ևս անցավ օսմանյան տիրապետության տակ. Ստամբուլի դիմացի ափը ներառյալ՝ ամբողջ Քոջաելի թերակղզին դարձավ օսմանյան հող։ Այսպիսով բեյլիքը, տիրելով Մարմարա ծովի հարավային և արևելյան ողջ ափին, նախապատրաստեց Ռումելի անցնելու հիմքը։", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Չիմփե ամրոցը — անցումը Ռումելի", "c2f0a07d"], "d": ["Օրհան Ղազիի որդի Սուլեյման փաշան 1352 թվականին որպես հենակետ ձեռք էր բերել Բյուզանդիայի քաղաքացիական պատերազմի ընթացքում տրված Չիմփե ամրոցը. 1354 թվականի մարտին Գելիբոլուն ավերած մեծ երկրաշարժից հետո լքված ամրոցներն արագորեն ամրացվեցին, և թերակղզին վերածվեց մշտական օսմանյան պլացդարմի։ Անատոլիայից բերված թուրքմեն բնակչության բնակեցմամբ ամրապնդված այս քայլը Եվրոպա մայրցամաքում օսմանցիների՝ ավելի քան 550 տարի տևած ներկայության սկիզբն է։", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Էդիրնեի նվաճումը", "2f54ebb0"], "d": ["Թրակիայի առանցքային քաղաք Էդիրնեի (Ադրիանապոլիս) գրավումը որոշեց բալկանյան նվաճումների գլխավոր հենակետն ու ուղղությունը. աղբյուրներում նվաճման ամսաթիվը վիճելի է՝ 1361-ից 1369 թվականների միջև։ Կարճ ժամանակ անց քաղաքը դարձավ մայրաքաղաք՝ ազդարարելով, որ պետության ծանրության կենտրոնը տեղափոխվել է Ռումելի. մինչև Կոստանդնուպոլսի նվաճումը այն շուրջ 90 տարի մնաց գահանիստ քաղաք։", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Մուրադ I-ը գահ բարձրացավ", "f8d48a26"], "d": ["Օրհան Ղազիի մահից հետո գահ բարձրացած Մուրադ I-ը (Հյուդավենդիգյար) իր 27-ամյա գահակալության ընթացքում պետությունը սահմանամերձ բեյլիքից հասցրեց կայսրության կմախքի։ Փենջիք համակարգով դրվեց ենիչերիական զորաբանակի (օջախի) հիմքը, տարածվեց թիմարային կարգը, հիմնվեց Ռումելիի բեյլերբեյությունը և ուժեղացվեց վեզիրության հաստատությունը։ Նրա օրոք բալկանյան նվաճումները դարձան համակարգված պետական քաղաքականություն։", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Կոսովոյի առաջին ճակատամարտը — Մուրադ I-ի նահատակությունը", "10b8ddc9"], "d": ["Կնյազ Լազարի գլխավորած բալկանյան դաշինքը վճռական պարտություն կրեց Կոսովոյի դաշտում. Սերբիան անցավ օսմանյան գերիշխանության տակ։ Մարտադաշտը շրջելիս Մուրադ I-ը սերբ ազնվական Միլոշ Օբիլիչի դաշույնի հարվածից նահատակվեց. նա մարտադաշտում մահացած միակ օսմանյան սուլթանն է։ Ռազմակայանում նրա փոխարեն գահ բարձրացվեց Յըլդըրըմ Բայազիդը. նրա եղբայր Յաքուբ Չելեբին խեղդամահ արվեց, և սա եղբայրասպանության գործելակերպի առաջին հայտնի օրինակներից էր։", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Նիկոպոլիսի հաղթանակը", "75716e96"], "d": ["Հունգարիայի թագավոր Սիգիզմունդի կոչով հավաքված խաչակրաց մեծ բանակը, որին միացել էին նաև ֆրանսիական և բուրգունդական ասպետները, Դանուբի ափին գտնվող Նիկոպոլիսի (Նիղբոլու) մոտ ծանր ջախջախում կրեց Յըլդըրըմ Բայազիդից։ Հաղթանակը վերջնականապես ամրապնդեց օսմանյան տիրապետությունը Բուլղարիայում. Եվրոպայում մեկ սերնդի ընթացքում խաչակրաց մեծ արշավանք չհաջողվեց կազմակերպել։", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Անկարայի ճակատամարտը — սկսվեց միջգահակալությունը (Ֆեթրեթի դարաշրջան)", "b4a99d96"], "d": ["Լենկ Թեմուրի բանակի դեմ Չուբուքի դաշտում կրած ծանր պարտության ժամանակ Յըլդըրըմ Բայազիդը գերի ընկավ և մի քանի ամիս անց մահացավ գերության մեջ։ Թեմուրը վերակենդանացրեց Անատոլիայի բեյլիքները. օսմանյան հողերը բաժան-բաժան եղան Բայազիդի որդիների միջև, և սկսվեց 11 տարի տևելիք գահակալական պայքարը (Ֆեթրեթի դարաշրջան)։ Պետության հիմնադրումից ի վեր ապրած ամենածանր ճգնաժամը եղած այս շրջանը օսմանյան հիշողության մեջ դրոշմեց կենտրոնացված կառույցի կարևորությունը։ Նույն ամսաթվին կորցրած այլ բնակավայրեր՝ Դաթչա, Մարմարիս, Ֆեթհիյե (Մակրի), Սյոքե, Քյոթահիա, Աֆյոն, Իսպարթա, Մանիսա, Այդըն, Դենիզլի, Մուղլա, Անթալիա, Կոնիա, Կարաման, Կեսարիա, Կաստամոնու, Բարթըն, Սաֆրանբոլու, Սամսուն, Սեբաստիա, Մալաթիա, Բեյշեհիր, Սիվրիհիսար, Քըրշեհիր, Չորում, Չանքըրը, Ենիշեհիր (Բուրսա), Ինեգյոլ, Այդոս ամրոց, Գեյվե, Քյոփրյուհիսար (Ենիշեհիր), Մարմարաջըք, Աքհիսար (Փամուքովա), Մեքեջե, Քեսթել, Ուլուբաթ, Հարմանքայա, Աքյազը, Իմրալը կղզի, Քանդըրա, Մուդանիա, Յալովա, Քարամյուրսել, Արմութլու, Գեմլիք (Կիոս), Սոյութ, Բիլեջիք, Էսքիշեհիր, Բուրսա, Իզնիկ, Իզմիթ, Բալըքեսիր, Չանաքքալե, Բերգամա, Ամասիա, Թոքաթ, Չորլու, Լյուլեբուրգազ, Մալքարա, Քեշան, Իփսալա, Քիլիթբահիր, Չիրմեն, Էսքի Զաղրա (Ստարա Զագորա), Թաթարփազարջըղը, Իհթիման, Քյոսթենդիլ, Պետրիչ, Նևրոկոփ (Գոցե Դելչև), Դրամա, Գելիբոլու, Չիմփե, Էդիրնե, Դիդիմոտիխո, Քըրքլարելի, Թեքիրդաղ, Ֆիլիպե, Սոֆիա, Նիշ, Վիդին, Տառնովո, Վառնա, Շումեն, Սիլիստրա, Նիկոպոլիս, Ռուսչուկ, Սալոնիկ, Սերեզ, Կավալա, Սկոպյե, Մանաստիր, Օհրիդ, Ենիշեհիր (Լարիսա), Տիրհալա, Իզդին (Լամիա), Պլևնա, Գյումյուլջինե, Բիղա, Դոմանիչ, Քուլաջահիսար, Քարաջահիսար, Յարհիսար, Դիմբոս, Քիթե (Քեթե), Լեֆքե (Օսմանելի), Լեբլեբիջիհիսար, Քարաչեփյուշ, Քարաթիգին, Աբսու (Հիփսու), Ադրանոս (Օրհանելի), Պելեկանոն (Էսքիհիսար), Գեբզե, Հերեքե, Սամանդըրա, Քիրմաստի (Մ. Քեմալփաշա), Միհալիչ (Քարաջաբեյ), Քյոսթենջե, Գյոլյազը (Ապոլոնիա)։", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Չելեբի Մեհմեդը վերականգնեց միասնությունը", "03413dfd"], "d": ["Եղբայրների միջև վերջին հաշվեհարդարում Չամուրլուի մոտ Մուսա Չելեբիին հաղթած Մեհմեդ I-ը երկրի հողերը միավորեց մեկ իշխանության ներքո. այդ պատճառով նա համարվում է «պետության երկրորդ հիմնադիրը»։ Նրա գահակալության ընթացքում վերականգնվեց մաշված պետական կառույցը, հավասարակշռվեցին հարաբերությունները Անատոլիայի բեյլիքների հետ, իսկ Ռումելիում վարվեց զգուշավոր խաղաղության քաղաքականություն։ Նույն ամսաթվին քարտեզում Ֆեթրեթի միջանկյալ շրջանից օսմանյան կառավարման վերադարձած այլ բնակավայրեր՝ Աբսու (Հիփսու), Ադրանոս (Օրհանելի), Աքհիսար (Փամուքովա)։", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Շեյխ Բեդրեդդինի ապստամբությունը", "e0a072ca"], "d": ["Ֆեթրեթի դարաշրջանում ղազասքերի պաշտոն վարած մեծ իրավագետ և սուֆի Շեյխ Բեդրեդդինի շուրջ ձևավորված կրոնասոցիալական շարժումը բռնկվեց Քարաբուրունում Բյորքլյուջե Մուստաֆայի և Մանիսայում Թորլաք Քեմալի ապստամբությունների հետ միաժամանակ։ Ապստամբությունները ճնշվեցին արյունալի կերպով. Բեդրեդդինը ձերբակալվեց Դելիորմանում և մահապատժի ենթարկվեց Սերեզում։ Այս իրադարձությունը, որպես օսմանյան պատմության ամենավաղ խոշոր սոցիալ-մահդիական ապստամբությունը, խոր հետք թողեց գրականության և պատմագրության մեջ։", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Վառնայի հաղթանակը", "f739eedc"], "d": ["Սեգեդի պայմանագիրը խախտելով հարավ իջած հունգարա-լեհական խաչակիր բանակը Վառնայում ոչնչացրեց Մուրադ II-ը, որը, գահից հրաժարված լինելով, վերադարձել էր բանակի ղեկը. երիտասարդ թագավոր Վլադիսլավ III-ը զոհվեց մարտադաշտում։ Հաղթանակը վերացրեց Բալկաններում օսմանյան ներկայությունը վերացնելուն ուղղված արտաքին խոշոր միջամտության վերջին հնարավորությունը և ապահովեց Կոստանդնուպոլսի նվաճման տանող ճանապարհը։", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Կոսովոյի երկրորդ ճակատամարտը", "ebe0b662"], "d": ["Վառնայի վրեժը լուծել ցանկացող Յանոշ Հունյադիի բանակը երեք օր տևած համառ մարտում վճռական պարտություն կրեց Մուրադ II-ից։ Սա Բալկաններում օսմանցիների դեմ խաչակիրների ձեռնարկած վերջին մեծ դաշտային ճակատամարտն է. հաղթանակով Դանուբից հարավ օսմանյան տիրապետությունն այլևս հաստատվեց անշրջելիորեն։", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Կոստանդնուպոլսի նվաճումը", "583d5e3e"], "d": ["Հիսունչորս օր (1453 թ. ապրիլի 6 – մայիսի 29) տևած պաշարումից հետո մայիսի 29-ի առավոտյան պարիսպները հաղթահարած օսմանյան բանակը մտավ քաղաք. վերջին կայսր Կոստանդին XI-ը զոհվեց մարտերում, և 1100-ամյա Արևելյան Հռոմեական կայսրությունն անցավ պատմության գիրկը։ Երիտասարդ սուլթանն ստացավ «Ֆաթիհ» (Նվաճող) տիտղոսը, քաղաքը դարձրեց մայրաքաղաք և Այա Սոֆիան վերածեց մզկիթի. քաղաքը կարճ ժամանակում վերակենդանացվեց բնակեցմամբ և շինարարությամբ։ Ըստ TDV-ի՝ Սիլիվրին և Վիզեն վերջնականապես նվաճվել են միայն 1453 թվականին. ըստ TDV-ի «Լեմնոս» հոդվածի՝ կղզին նվաճումից անմիջապես հետո անցել է օսմանյան կառավարման տակ և խարաջ վճարելու պայմանով թողնվել Գատիլուզիո ընտանիքին։ Ատլասում Սիլիվրին, Վիզեն և Լեմնոսը այս օրվանից նշված են որպես Բյուզանդիայից Օսմանյան կայսրությանն անցած (Լեմնոսը՝ խարաջատու)։ Հսկա թնդանոթների ձուլումը, նավերի տեղափոխումը ցամաքով և պարիսպների առջև պաշարման դասավորությունը համարվում են այդ դարաշրջանի ռազմական ինժեներիայի գագաթնակետը։ Նվաճումը եվրոպական պատմագրության մեջ համարվում է միջնադարի ավարտը խորհրդանշող ամսաթվերից մեկը։", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Տրապիզոնի նվաճումը", "15f52403"], "d": ["Ֆաթիհի՝ բանակով և նավատորմով միաժամանակ վարած դժվարին սևծովյան արշավանքի արդյունքում Տրապիզոնի հունական կայսրությունը հանձնվեց. բյուզանդական աշխարհի՝ Անատոլիայում մնացած այս վերջին մնացորդի վերացմամբ Սև ծովի հարավային ափն ամբողջությամբ անցավ օսմանյան տիրապետության տակ։ Կոմնենոսների հարստությանը վերջ տալը ամրապնդեց Ֆաթիհի՝ «երկու ծովերի և երկու ցամաքների տիրակալ» լինելու հավակնությունը։ Նույն ամսաթվին միացած այլ վայրեր՝ Կիրասոն, Ռիզե։", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Սելևկիայի (Սիլիֆքե) վերջնական նվաճումը — Կարամանյանների վերջին դիմադրության կոտրումը", "d988bee4"], "d": ["Սիլիֆքեի ամրոցը 1472 թվականին մեկ անգամ հանձնվել էր Գեդիք Ահմեդ փաշային, սակայն նույն տարում Կարամանօղլու Կասըմ բեյը Միջերկրական ծովի խաչակիր նավատորմի օգնությամբ հետ էր վերցրել ամրոցը։ Օթլուքբելիի հաղթանակից հետո Ֆաթիհը իր որդուն և Գեդիք Ահմեդ փաշային հանձնարարեց վերջնականապես գրավել շրջանը. նախկին օսմանյան թնդանոթաձիգների օգնությամբ վառոդի պահեստը հրկիզվեց, և ամրոցն արագորեն ընկավ։ Այսպիսով կոտրվեց Կարամանյանների վերջին դիմադրությունը Թաշելի-Իչելի լեռներում. բեյլիքի վերացումն ավարտվելու էր 1474 թվականին։", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Օթլուքբելիի ճակատամարտը", "42c7194e"], "d": ["Արևելքում մեծ ուժ դարձած և Վենետիկի հետ դաշինք կնքած Ակ Կոյունլուների տիրակալ Ուզուն Հասանը Օթլուքբելիում ծանր պարտություն կրեց Ֆաթիհի՝ հրազենով զինված բանակից։ Հաղթանակը վերջնականապես ամրապնդեց օսմանյան գերակայությունը Անատոլիայում. այն նաև դասական բանակի դեմ թնդանոթ և հրացան կիրառող կենտրոնացված բանակի գերազանցության վաղ ապացույց դարձավ։ Ըստ TDV-ի «Գյումուշխանե» հոդվածի՝ քաղաքը 1467 թվականից ի վեր գտնվում էր Ակ Կոյունլուների տիրապետության տակ. այդ տիրապետությունն ավարտվեց Օթլուքբելիի պարտությամբ, և Գյումուշխանեն վերջնականապես անցավ օսմանյան տիրապետության տակ։", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Ղրիմի անցումը օսմանյան հովանավորության տակ", "44e3f7c8"], "d": ["Գեդիք Ահմեդ փաշայի հրամանատարությամբ նավատորմը նվաճեց Ղրիմի հարավային ափի քաղաքները, առաջին հերթին՝ ջենովացիներին պատկանող Կաֆան. այդ ափերը ուղղակիորեն դարձան օսմանյան սանջակ։ Իսկ Ղրիմի խանությունը Մենգլի Գիրեյի հետ դարձավ օսմանյան գերիշխանությունը ճանաչող արտոնյալ ենթակա պետություն և երեք դար շարունակ հյուսիսային քաղաքականության հիմնաքարը եղավ. Սև ծովն այլևս փաստացի վերածվեց օսմանյան ներքին ծովի։ Նույն ամսաթվին միացած այլ վայրեր՝ Բախչիսարայ, Կերչ, Ազով։", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Ֆաթիհի մահը — Ջեմ սուլթանի գործը", "190ecf01"], "d": ["Արշավանքի ճանապարհին Ֆաթիհի հանկարծակի մահից հետո գահ բարձրացավ Բայազիդ II-ը. նրա եղբայր Ջեմ սուլթանը, գահին հավակնելով, Բուրսայում իր անունով խուտբա կարդացնել տվեց և դրամ հատեց։ Պարտվելով՝ նա ապաստան գտավ նախ մամլուքների, ապա Ռոդոսի ասպետների մոտ. ասպետների և պապականության ձեռքում եվրոպական դիվանագիտության սակարկության խաղաքարտ դարձած Ջեմը 1495 թվականին մահացավ Նեապոլում։ Այս իրադարձությունը տասնհինգ տարի ստիպեց օսմանյան արտաքին քաղաքականությանը զգուշորեն գործել։", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Չալդրանի հաղթանակը", "fea64ebb"], "d": ["Անատոլիայում սեֆյան քարոզչության ստեղծած սպառնալիքն արմատախիլ անել ցանկացող Սուլթան Սելիմ Յավուզը Չալդրանի դաշտում թնդանոթների և հրացանների գերազանցությամբ ծանր պարտության մատնեց Շահ Իսմայիլի բանակը։ Նա մտավ Թավրիզ. Արևելյան և Հարավարևելյան Անատոլիան, ինչպես նաև Մոսուլ-Դիարբեքիր գիծը միացան օսմանյան տիրապետությանը։ Իդրիս Բիթլիսիի ջանքերով քուրդ բեյերի միանալը օսմանցիներին հիմնեց արևելյան սահմանի՝ դարեր տևելիք շրջանակը։", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Մարջ Դաբիքի հաղթանակը", "07d254d3"], "d": ["Մամլուքների բանակը Հալեպից հյուսիս գտնվող Մարջ Դաբիքում մի քանի ժամում ցրվեց. ծեր սուլթան Կանսուհ ալ-Ղաուրին մահացավ ճակատամարտի ընթացքում։ Հալեպի և Դամասկոսի դարպասները լայն բացած այս հաղթանակով Սիրիան, Լիբանանը և Պաղեստինը անցան օսմանյան կառավարման տակ. բացվեց Մամլուքների պետությանը վերջ տալիք եգիպտական արշավանքի ճանապարհը։", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ռիդանիե — Եգիպտոսի նվաճումը և խալիֆայությունը", "caf378d6"], "d": ["Սինայի անապատն արագ անցած օսմանյան բանակը Ռիդանիեում ճեղքեց Թումանբայի պաշտպանական գիծը և մտավ Կահիրե. դիմադրությունը շարունակող Թումանբայը ձերբակալվեց և մահապատժի ենթարկվեց, իսկ Մամլուքների պետությունն անցավ պատմության գիրկը։ Եգիպտոսը, Հիջազը և սրբազան քաղաքներն անցան օսմանյան կառավարման տակ. Աբբասյան խալիֆը և սրբազան մասունքները տեղափոխվեցին Ստամբուլ։ Խալիֆայության՝ օսմանյան հարստությանն անցնելով՝ սուլթանները ստանձնեցին իսլամական աշխարհի առաջնորդության հավակնությունը. Համեմունքների ճանապարհի վերահսկողությունը ևս մեծ եկամուտ ապահովեց կայսրությանը։ Նույն ամսաթվին միացած այլ վայրեր՝ Աքքա, Մաան, Սիդոն, Քերաք։", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Սուլթան Սուլեյման Կանունին գահ բարձրացավ", "f6512269"], "d": ["Յավուզի մահից հետո որպես միակ արու զավակ գահ բարձրացած Սուլեյման I-ի 46-ամյա գահակալությունը համարվում է կայսրության քաղաքական, ռազմական, իրավական և մշակութային գագաթնակետը։ Սովորութային իրավունքը համակարգած նրա կանունամեները նրան բերեցին «Կանունի» (Օրենսդիր) տիտղոսը. Արևմուտքում նրան կոչում էին «Հոյակապ» (Magnificent)։ Ճարտարապետ Սինանի կառույցները, դիվանական գրականության ոսկեդարը և նավատորմի գերակայությունը Միջերկրական ծովում այս դարաշրջանի խորհրդանիշներն են։", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Բելգրադի նվաճումը", "59ef5cec"], "d": ["Բելգրադը, որը Ֆաթիհը 1456 թվականին չէր կարողացել գրավել և որը համարվում էր «Կենտրոնական Եվրոպայի բանալին», Կանունիի առաջին արշավանքի ժամանակ ընկավ Դանուբի և Սավայի միախառնման վայրում տեղի ունեցած պաշարմամբ։ Այսպիսով փլուզվեց Հունգարիայի հարավային պաշտպանական գիծը. այս նվաճմամբ բացվեց Կենտրոնական Եվրոպայի գործողությունների դուռը, որը ձգվում էր մինչև հինգ տարի անց Մոհաչը և քսան տարի անց Բուդայի բռնակցումը։", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Ռոդոսի նվաճումը", "807bbb1e"], "d": ["Արևելյան Միջերկրածովի ծովային ուղիներին և ուխտագնացության երթուղուն սպառնացող Սուրբ Հովհաննեսի ասպետների հենակետ Ռոդոսը ամիսներ տևած արյունալի պաշարումից հետո հանձնվեց պայմանագրով. ասպետներին թույլատրվեց ազատ հեռանալ կղզուց (հետագայում նրանք հաստատվեցին Մալթայում)։ Ապահովվեց Անատոլիայի ափերի անվտանգությունը, և Ստամբուլ-Եգիպտոս ծովային գիծը անընդհատ կերպով անցավ օսմանյան վերահսկողության տակ։", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Մոհաչի դաշտային ճակատամարտը", "f3418b0d"], "d": ["Հունգարական բանակը Մոհաչի դաշտում մոտ երկու ժամվա ընթացքում ոչնչացվեց թնդանոթային կրակի և զորաշարժի գերազանցությամբ. թագավոր Լայոշ II-ը փախչելիս մահացավ ճահիճում։ Օսմանյան պատմության ամենաարագ տարած մեծ դաշտային ճակատամարտերից մեկը եղած Մոհաչը փաստացի վերջ տվեց Հունգարիայի անկախ թագավորությանը և Կենտրոնական Եվրոպայում բացեց օսմանա-հաբսբուրգյան մրցակցության դարաշրջանը։", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Վիեննայի առաջին պաշարումը", "dc49ea4f"], "d": ["Հաբսբուրգների՝ հունգարական գահին ձեռք մեկնելու դեմ ձեռնարկված արշավանքի ժամանակ օսմանյան բանակը պաշարեց Վիեննան. ծանր թնդանոթները ճանապարհին թողնելու, վաղ վրա հասած ձմռան և պարենավորման դժվարության պատճառով պաշարումը երեք շաբաթ անց վերացվեց։ Թեև քաղաքը չգրավվեց, օսմանյան ազդեցությունը Հունգարիայում պահպանվեց. Վիեննայի մատույցները նշեցին Կենտրոնական Եվրոպայում կայսրության լոգիստիկ հասանելիության սահմանը։", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Բաղդադի նվաճումը — երկու Իրաքների արշավանքը", "897092c3"], "d": ["«Երկու Իրաքների» (Արաբական Իրաք և Պարսկական Իրաք) դեմ ձեռնարկված արշավանքի ժամանակ նախ մտան Թավրիզ, ապա առանց կռվի՝ Բաղդադ. Աբբասյանների նախկին մայրաքաղաքի գրավումը օսմանյան տիրակալին մեծ հեղինակություն բերեց իսլամական աշխարհում։ Վերականգնվեց Իմամ Ազամ Աբու Հանիֆայի դամբարանը. Բաղդադի և Բասրայի միացմամբ օսմանյան հողերը հասան Պարսից ծոցին։ Նույն ամսաթվին միացած այլ վայրեր՝ Կիրկուկ, Քարբալա։", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Պրևեզայի ծովային հաղթանակը", "30dc0f97"], "d": ["Պապի նախաձեռնությամբ կազմված խաչակիր նավատորմը, թեև թվաքանակով գերազանց էր, Պրևեզայի մերձակա ջրերում ցրվեց Բարբարոսայի՝ քամին և ափը հմտորեն օգտագործող մարտավարությամբ. Անդրեա Դորիան լքեց մարտադաշտը։ Հաղթանակը Միջերկրական ծովում հաստատեց շուրջ 33 տարի տևելիք անվիճելի օսմանյան ծովային գերակայություն. թուրքական ծովագնացության ավանդույթում դա նավատորմի օրվա խորհրդանշական ամսաթիվն է։ Նույն ամսաթվին միացած այլ վայրեր՝ Ադեն, Բենդեր։", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Բուդայի բռնակցումը — Հունգարիան՝ օսմանյան էյալեթ", "db53b244"], "d": ["Բուդայի՝ Հաբսբուրգների պաշարման առիթով արշավանքի ելած Կանունին, քաղաքը փրկելուց հետո, Կենտրոնական Հունգարիան անմիջականորեն ներառեց օսմանյան կառավարման մեջ և հիմնեց Բուդայի բեյլերբեյությունը. իսկ Տրանսիլվանիան դարձավ Օսմանյան պետությանը ենթակա ինքնավար իշխանապետություն։ Հունգարիայի՝ երեք մասի բաժանված այս կարգը տևեց շուրջ 150 տարի և կազմեց օսմանյան մշտական կառավարման կմախքը Կենտրոնական Եվրոպայում։", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Ամասիայի պայմանագիրը", "a5afe0d1"], "d": ["Սա տարիներ տևած օսմանա-սեֆյան պատերազմներին վերջ դրած առաջին պաշտոնական հաշտության պայմանագիրն է։ Բաղդադը և Իրաքը մնացին օսմանցիներին, Արևելյան Անատոլիայի սահմանն առաջին անգամ փոխադարձաբար ճանաչվեց. Սեֆյանները պարտավորվեցին դադարեցնել շիայական քարոզչությունը օսմանյան երկրում, իսկ օսմանցիները՝ ապահովել իրանցի ուխտավորների անցման անվտանգությունը։ Պայմանագիրը դարձավ երկու պետությունների հարաբերությունների իրավական շրջանակի առաջին օրինակը։", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Սիգետվար — Կանունիի մահը", "e2917ed2"], "d": ["72-ամյա Կանունին իր տասներեքերորդ արշավանքի ժամանակ պաշարած Սիգետվարի ամրոցի անկումից մի քանի ժամ առաջ մահացավ իր վրանում. Սոքոլլու Մեհմեդ փաշան, որպեսզի բանակը չցրվի, շաբաթներ շարունակ թաքցրեց մահը։ Ամրոցը գրավվեց, սակայն պետությունը կորցրել էր ամենաերկարատև գահակալությամբ և ամենափառահեղ փադիշահին. գահ բարձրացավ նրա որդի Սելիմ II-ը, և պետության կառավարման մեջ սկսեց աճել մեծ վեզիրների կշիռը։", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Կիպրոսի նվաճումը", "e364a2b3"], "d": ["1570 թվականին վենետիկյան կառավարման տակ գտնվող Կիպրոսում ափհանում կատարվեց. Նիկոսիան արագորեն ընկավ, իսկ Ֆամագուստան հանձնվեց միայն տասնմեկամյա պաշարումից հետո՝ 1571 թվականի օգոստոսին։ Արևելյան Միջերկրածովի առևտրի և ուխտագնացության ուղիների անվտանգության տեսանկյունից վճռորոշ կղզին կազմակերպվեց որպես բեյլերբեյություն, և Անատոլիայից բնակչություն բնակեցվեց. նվաճումը նաև դարձավ դեպի Լեպանտո տանող խաչակրաց մեծ դաշինքի պատրվակը։", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Լեպանտոյի (Ինեբահթը) պարտությունը", "6a1d44a9"], "d": ["Կիպրոսի նվաճումից հետո միավորված խաչակիր նավատորմը Լեպանտոյի ծոցում բռնեց օսմանյան նավատորմը և ոչնչացրեց դրա մեծ մասը. կապուդան փաշա Մյուեզզինզադե Ալի փաշան նահատակվեց, փրկվեց միայն Ուլուջ Ալիի նավախումբը։ Աղետից հետո մեծ վեզիր Սոքոլլու Մեհմեդ փաշան Ուլուջ Ալի փաշային նշանակեց կապուդան փաշա, հանձնարարեց նրան հավաքել ցրված նավատորմը և Ստամբուլից մինչև Ալանիա բոլոր նավաշինարաններում սկսեց նոր նավատորմի կառուցումը. սակայն Միջերկրական ծովում բացարձակ գերակայությունը հոգեբանորեն խարխլվել էր։", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Կերեստեշի (Հաչովայի) դաշտային ճակատամարտը", "da308ec5"], "d": ["Երկարատև պատերազմի (1593–1606) ամենամեծ դաշտային ճակատամարտում Մեհմեդ III-ի անձամբ գլխավորած բանակը, հասնելով ցրվելու եզրին, Հոջա Սադեդդին էֆենդիի հորդորով վերախմբվեց և ջախջախեց Հաբսբուրգների բանակը։ Այն համարվում է օսմանցիների տարած վերջին մեծ դասական դաշտային ճակատամարտը. սակայն այն, որ չփոխեց պատերազմի ընդհանուր ընթացքը, դիտվեց նաև որպես ռազմական համակարգի մաշվածության նշան։", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Ժիտվատորոկի պայմանագիրը", "39c01142"], "d": ["Տասներեքամյա հյուծիչ պատերազմին վերջ դրած պայմանագրով հաբսբուրգյան տիրակալն առաջին անգամ «Հռոմեական կայսր» տիտղոսով համարվեց փադիշահին հավասար, և տարեկան խարաջը վերացվեց։ Հողային կորուստը գրեթե աննշան էր. սակայն դիվանագիտական լեզվի այս փոփոխությունը մեկնաբանվում է որպես Եվրոպայի նկատմամբ բացարձակ գերազանցության օսմանյան հավակնության ավարտի խորհրդանիշ։", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Կասրե Շիրինի պայմանագիրը", "c1acf3af"], "d": ["Մուրադ IV-ի կողմից Բաղդադը վերագրավելուց (1638) հետո ստորագրված պայմանագիրը վերջ դրեց ավելի քան հարյուր տարի տևած օսմանա-սեֆյան պատերազմներին։ Բաղդադը և Իրաքը վերջնականապես մնացին օսմանցիներին, Երևանը թողնվեց Սեֆյաններին. գծված սահմանագիծը, փոքր փոփոխություններով, դարձավ այսօրվա Թուրքիա-Իրան սահմանի հիմքը և համարվում է աշխարհի ամենաերկարակյաց սահմաններից մեկը։ Պայմանագիրը Բադրան, Ջասսանը, Մանդալին, Դերթանգը և Դերնեն թողեց օսմանցիներին. սահմանի վրա գտնվող Զենջիր ամրոցը պետք է քանդվեր, նրանից արևմուտք գտնվող գյուղերը մնալու էին օսմանցիներին, արևելքում գտնվողները՝ Իրանին։ Շահրիզորի մոտ գտնվող Զալիմ ամրոցի շրջակայքը և Քըզըլջա ամրոցը մնացին օսմանցիներին, իսկ Ավրոմանն ու Մեհրիվանը՝ Իրանին. Կոտուր, Մակու և Մաղազբերդ ամրոցները պետք է քանդվեին երկու կողմերի կողմից։", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Կրետեի նվաճումն ավարտվեց", "e0d85604"], "d": ["1645 թվականին սկսված Կրետեի պատերազմի վերջին արարը՝ Կանդիայի պաշարումը, ավարտվեց Ֆազըլ Ահմեդ փաշայի եռամյա վճռական գործողություններով. վենետիկյան հրամանատար Մորոզինին քաղաքը հանձնեց պայմանագրով։ Շուրջ քառորդ դար տևած պայքարը պատմության մեջ գրանցվեց որպես օսմանյան պատմության ամենաերկար պաշարումը. Արևելյան Միջերկրածովի վերջին մեծ լատինական ամրոցը ևս անցավ օսմանյան կառավարման տակ։ Կղզու հյուսիսային ափի երեք փոքր ժայռոտ ամրոցները՝ Սուդան, Սպինալոնգան և Գրամվուսան, դեռ մնացին Վենետիկին. քանի որ դրանք կառուցված են առանձին կղզյակների վրա, քարտեզում հնարավոր չէ դրանք ցույց տալ Կրետեի մնացած մասից առանձին։", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Բուչաչի պայմանագիրը — ամենաընդարձակ սահմանները", "b17b6e5a"], "d": ["Լեհաստանի արշավանքում Կամենեցի նվաճումից հետո ստորագրված Բուչաչի պայմանագրով Պոդոլիան միացավ Օսմանյան պետությանը, իսկ Ուկրաինայի մի մասը վերցվեց հովանավորության տակ։ Այսպիսով կայսրությունը հասավ Եվրոպայում իր ամենաընդարձակ սահմաններին. այս կետը համարվում է ընդարձակման դարաշրջանի գագաթնակետը և միաժամանակ վերջին օղակը։", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Վիեննայի երկրորդ պաշարման ջախջախումը", "7d889252"], "d": ["Մերզիֆոնցի Կարա Մուստաֆա փաշայի՝ Վիեննայի երկու ամիս տևած պաշարումը Լեհաստանի թագավոր Յան Սոբեսկիի՝ Կալենբերգի բլուրներից հասցրած հանկարծակի հարվածով վերածվեց ջախջախման. բանակը նահանջեց՝ թողնելով իր գումակը, իսկ Մերզիֆոնցին մահապատժի ենթարկվեց Բելգրադում։ Հաղթանակից հետո կազմված Սրբազան լիգայի դեմ պատերազմը տևեց 16 տարի. օսմանյան պատմության մեջ մեծ անկման սկզբի պահ է համարվում այս ջախջախումը։", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Գրամվուսա ամրոցի նվաճումը — Կրետեում Վենետիկին մնացած ժայռոտ ամրոցներից մեկը", "3ddf9eeb"], "d": ["Թեև 1669 թվականին Կանդիայի հանձնմամբ Կրետեի նվաճումը մեծ մասամբ ավարտված է համարվում, կղզու հյուսիսարևմտյան ծայրի ժայռոտ կղզի-ամրոց Գրամվուսան ևս քսաներեք տարի մնաց Վենետիկի ձեռքում։ 1692 թվականին դրա գրավմամբ մաքրվեց Կրետեում վենետիկյան երեք մնացորդներից մեկը. իսկ Սուդան և Սպինալոնգան սպասելու էին 1715 թվականի Մորեայի արշավանքին։", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Կառլովիցի պայմանագիրը — առաջին մեծ հողային կորուստը", "8f7e2546"], "d": ["Սրբազան լիգայի դեմ տասնվեցամյա պատերազմներին վերջ դրած Կառլովիցի պայմանագրով Հունգարիան և Տրանսիլվանիան թողնվեցին Ավստրիային, Պոդոլիան՝ Լեհաստանին, Մորեան և Դալմաթիայի ափերը՝ Վենետիկին։ Օսմանյան պատմության մեջ առաջին անգամ այս ծավալի հողեր կորսվում էին բանակցությունների սեղանի շուրջ և մշտապես. պայմանագիրը համարվում է Եվրոպայի նկատմամբ կայսրության պաշտպանության անցման նոր դարաշրջանի սկզբնական փաստաթուղթը և նաև օսմանյան դիվանագիտության պատմության շրջադարձային կետն է։ Նույն օրն ատլասում ձեռքից ձեռք անցած բնակավայրեր՝ Կոստայնիցա և Յասենովաց (Օսմանյան պետությունից Հաբսբուրգներին. պայմանագրի տեքստը Castanoviz-ը թողնում է կայսեր ձեռքում, Յասենովացի հանձնման օրը աղբյուրում նշված չէ, գրվել է պայմանագրի օրը) և Պրևեզա (Վենետիկից Օսմանյան պետությանը. TDV karlofca՝ 24 Ռաջաբ 1110 / 1699 թվականի հունվարի 26-ին ստորագրված դրույթի համաձայն՝ Լեպանտոյի ծոցից հյուսիս Վենետիկի օկուպացրած վայրերը վերադարձվեցին)։ Ատլասը նաև Կոստայնիցան (Kostajnica) և Յասենովացը գրում է հաբսբուրգյան կողմում, Աջափնյա Ուկրաինայի Ումանը և Վիննիցան՝ Օսմանյան պետությունից Լեհաստանին (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia՝ 1672-99 թուրքական տիրապետություն), իսկ Դալմաթիայի Նադինը՝ Վենետիկին (բնակավայրին հատուկ հանձնման օրը աղբյուրում նշված չէ, գրվել է պայմանագրի օրը. Նադինի ժամանակաշրջանի ծայրակետերն աղբյուրով չեն հաստատվել՝ հայտարարված մոտավորություն)։ Լեպանտոյի ծոցից հյուսիս գտնվող Վոնիցան ևս Վենետիկից վերադարձվում է օսմանցիներին (TDV karlofca). Դալմաթիայում Վրանան (Ուրանա) Վենետիկին մնացած վայրերի թվում է (ժամանակաշրջանի ծայրակետը չի հաստատվել՝ հայտարարված)։", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Պրուտի հաղթանակը", "2583572f"], "d": ["Պոլտավայի պարտությունից հետո Օսմանյան պետությունում ապաստանած Շվեդիայի թագավորի հարցի պատճառով ծագած պատերազմում ցար Պետրոս I-ի բանակը, Պրուտի ափին շրջապատվելով, ստիպված եղավ հանձնվել։ Ստորագրված պայմանագրով Ազովը հետ վերցվեց. իսկ բանակը չոչնչացնելը և ցարին ազատ արձակելը պատմության մեջ մտան որպես այդ օրից մինչ այսօր վիճարկվող որոշում։", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Սուդա և Սպինալոնգա ամրոցների նվաճումը — Կրետեում Վենետիկի վերջին հետքի ջնջումը", "7261f7ba"], "d": ["1692 թվականին Գրամվուսայի անկումից քսաներեք տարի անց Մորեայի արշավանքի կողմնային թևով նվաճվեցին նաև Կրետեում Վենետիկի վերջին երկու հենակետերը՝ Սուդա և Սպինալոնգա ամրոցները։ Այսպիսով 1645 թվականին սկսված Կրետեի նվաճումը քառասունվեց տարվա վերջում ավարտվեց մինչև կղզու վերջին սանտիմետրը։", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Պատրոնա Խալիլի ապստամբությունը", "100941a4"], "d": ["Իրանական ճակատում անհաջողությունը, հարկերը և պալատական շրջապատի շռայլության դեմ զայրույթը բաղնիքի սպասավոր Պատրոնա Խալիլի գլխավորությամբ վերածվեցին մեծ ապստամբության։ Մեծ վեզիր Իբրահիմ փաշան սպանվեց, Ահմեդ III-ը գահընկեց արվեց, և Կակաչների դարաշրջանն ավարտվեց. ապստամբների՝ ամիսներ շարունակ քաղաքում իշխելը ցայտուն կերպով ցույց տվեց կենտրոնական իշխանության փխրունությունը։", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Բելգրադի պայմանագիրը — Բելգրադի, Սմեդերևոյի և Հյուսիսային Սերբիայի հետգրավումը", "ba7f8e46"], "d": ["Ավստրիայի և Ռուսաստանի դեմ երկու ճակատով վարված պատերազմի (1736–1739) վերջում Բելգրադը և Հյուսիսային Սերբիան հետ վերցվեցին. Ռուսաստանը համաձայնեց ապառազմականացնել Ազովը և Սև ծովում նավատորմ չպահել։ 18-րդ դարի օսմանյան դիվանագիտության և բանակի վերջին մեծ հաջողությունը համարվող պայմանագիրը կայսրությանը պարգևեց քառորդ դարի խաղաղության շրջան։ Նույն օրն ատլասում Ավստրիայից օսմանցիներին վերադարձած այլ բնակավայրեր՝ Հիսարջըք (Գրոցկա) (Բելգրադի ավագ կենտրոնի շղթան. TDV belgrad), Կրայովա (Craiova), Ռիմնիկ (Râmnicu Vâlcea) և Տուրնու Սևերին (Փոքր Վալախիայի վերադարձը օսմանցիներին՝ Վալախիայի վասալությանը)։ Սավայի շերտի Բոսնիական Բրոդը (Bosanski Brod) և Բոսնիական Դուբիցան (Bosanska Dubica) ատլասում օսմանցիներին են վերադառնում 1739 թվականի սեպտեմբերի 28-ին (TDV bosna-hersek; TDV mahmud-i--osmanli՝ 28 սեպտեմբերի 1739)։ Փոքր Վալախիայում Տիրգու Ժիուն ևս նույն օրը վերադառնում է օսմանցիներին։", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Չեշմեի հարձակումը", "840b30bd"], "d": ["Անգլիացիների աջակցությամբ Միջերկրական ծով դուրս եկած ռուսական նավատորմը հրկիզող նավերով հարձակվեց Չեշմեի նավահանգստում ապաստանած օսմանյան նավատորմի վրա և գրեթե ամբողջությամբ այրեց այն։ Ռուսաստանն առաջին անգամ հանդես եկավ Միջերկրական ծովում որպես մեծ ծովային ուժ. աղետը դարձավ 1774 թվականի Քյուչուկ Կայնարջիին տանող պատերազմի ճակատագիրը որոշած հարվածներից մեկը և ակնհայտ դարձրեց նավատորմի արմատական բարեփոխման անհրաժեշտությունը։", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Քյուչուկ Կայնարջիի պայմանագիրը", "2776dcdb"], "d": ["1768–1774 թվականների պատերազմին վերջ դրած և օսմանյան պատմության ամենածանր պայմանագրերից համարվող Քյուչուկ Կայնարջիով Ղրիմի խանությանը «անկախություն» տրվեց. փաստացի ստեղծվեց ռուսական ազդեցության գոտի։ Ռուսաստանը հաստատվեց Սև ծովի ափին, ձեռք բերեց իր առևտրական նավերի՝ նեղուցներով անցնելու իրավունք և մշտական դեսպանություն Ստամբուլում. ուղղափառ հպատակների նկատմամբ հովանավորության անորոշ դրույթը կիսաբացեց հաջորդ դարի միջամտությունների պատրվակների դուռը։ Առաջին անգամ մուսուլման բնակչությամբ հող դուրս էր բերվում օսմանյան տիրապետությունից։", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Ղրիմի բռնակցումը Ռուսաստանին", "bdf6faa8"], "d": ["Քյուչուկ Կայնարջիով ստեղծված «անկախ» Ղրիմը, վերջին խան Շահին Գիրեյի ժամանակվա խառնակությունները պատրվակ դարձնելով, Եկատերինա II-ի մանիֆեստով բռնակցվեց Ռուսաստանին։ Օսմանա-ղրիմյան երեք դարի գործընկերությունն ավարտվեց. հյուսիսային տափաստանների կորուստը վերացրեց Ստամբուլի պաշտպանության խորությունը և սկիզբ դրեց տասնյակ հազարավոր Ղրիմի թաթարների՝ օսմանյան հողեր գաղթի առաջին մեծ ալիքին։ Այս օրը Ղրիմ թերակղզին (Ալուշտա, Կաֆա, Սուդակ, Յալթա, Բալակլավա, Ինկերման, Մանգուպ, Արաբաթ) միացավ Ռուսաստանին. Թամանը և Կուբանը նույն բռնակցմամբ ևս անցան Ռուսաստանին (TDV Kırım՝ 8 ապրիլի 1783 հուլյան = 19 ապրիլի գրիգորյան)։", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Սելիմ III-ը և Նիզամ-ը Ջեդիդը", "d53aec21"], "d": ["Պատերազմի թեժ պահին գահ բարձրացած Սելիմ III-ը, տեսնելով, որ պարտությունները կառուցվածքային բնույթ ունեն, «Նիզամ-ը Ջեդիդ» (Նոր կարգ) անունով սկսեց բարեփոխումների ընդգրկուն ծրագիր՝ եվրոպական ձևով մարզված նոր բանակ, այն ֆինանսավորող առանձին գանձարան (Իրադ-ը Ջեդիդ), ինժեներական դպրոցների ուժեղացում և առաջին մշտական դեսպանությունները եվրոպական մայրաքաղաքներում։ Ծրագիրը համարվում է ժամանակակից թուրքական բարեփոխումների ավանդույթի սկիզբը. սակայն զորաբանակների (օջախների) և այանների դիմադրության պատճառով այն տապալվելու էր 1807 թվականին։", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Մալթայի ասպետների վերացումը — ֆրանսիական նավատորմի կանգառը ճանապարհին", "d62f901d"], "d": ["Եգիպտոս մեկնող ֆրանսիական նավատորմն իր ճանապարհին կանգ առավ Մալթայում. Սուրբ Հովհաննեսի (Մալթայի) ասպետները, առանց մեծ դիմադրության, հանձնեցին կղզին։ Այսպիսով վերացավ 1522 թվականին Ռոդոսից վտարված և այստեղ հաստատված ասպետական միաբանության վերջին ամրոցը։ Երկու տարի անց Մալթան անցնելու էր Անգլիայի ձեռքը, իսկ Նապոլեոնը կղզուց ուղղակիորեն շարժվելու էր դեպի Ալեքսանդրիա։", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Նապոլեոնի կողմից Եգիպտոսի գրավումը (օկուպացիան)", "93fede5f"], "d": ["Գեներալ Բոնապարտի բանակը, ափհանվելով Ալեքսանդրիայում, օկուպացրեց Եգիպտոսը. Անգլիայի՝ դեպի Հնդկաստան ճանապարհը թիրախ դարձրած այս արշավանքը եվրոպական ուժի առաջին ուղղակի հարձակումն էր օսմանյան կենտրոնական հողերի վրա։ Նելսոնի՝ Աբուկիրի հարձակումը և Ջեզզար Ահմեդ փաշայի՝ Աքքայի պաշտպանությունը կոտրեցին ֆրանսիական առաջխաղացումը. օկուպացիան ավարտվեց 1801 թվականին, բայց նրա թողած դատարկության մեջ սկսվեցին Կավալացի Մուհամմեդ Ալի փաշայի վերելքը և «Արևելյան հարցի» դարաշրջանը։", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Սենեդ-ի Իթթիֆաք (Դաշինքի ակտ)", "cce49ef5"], "d": ["Մահմուդ II-ին գահ բարձրացրած Ռուսչուկի այան Ալեմդար Մուստաֆա փաշայի նախաձեռնությամբ պալատի և գավառի հզոր այան ընտանիքների միջև ստորագրված փաստաթուղթ. այանները պարտավորվում էին հավատարիմ մնալ փադիշահին և զորքով աջակցել, իսկ պետությունը ճանաչում էր նրանց գոյությունն ու իրավունքները։ Քանի որ սա օսմանյան պատմության մեջ փադիշահի իշխանությունը փաստաթղթով սահմանափակելու առաջին օրինակն է, որոշ պատմաբաններ այն համարում են սահմանադրական ավանդույթի հեռավոր սկիզբը. գործնականում մի քանի ամսվա ընթացքում այն կորցրեց ուժը։", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Սկսվեց հունական ապստամբությունը", "a7293715"], "d": ["Ֆիլիկի Էթերիա կազմակերպության նախապատրաստած ապստամբությունը բռնկվեց նախ Վալախիայում, ապա իր հիմնական ուժով՝ Մորեայում. Թեփեդելենլի Ալի փաշայի հոգսով զբաղված պետությունը առաջին միջամտությունն ուշացրեց։ Եվրոպական հասարակական կարծիքում հույների հանդեպ ուժեղ համակրանքի (ֆիլհելլենիզմի) շնորհիվ ապստամբությունը կարճ ժամանակում վերածվեց միջազգային գործի. այսպես վառվեց ազգայնականության դարաշրջանում օսմանյան հողերում առաջին հաջող անկախության շարժման պատրույգը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Աթենք, Բալյաբադրա (Պատրաս), Իստեֆե (Թեբե), Լիվադիա, Էլևսիս (Ատտիկա), Միսսոլոնգի։", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Առաջին զինված ապստամբությունը Մորեայում", "77e6250f"], "d": ["Պրուտն անցնելուց հետո ապստամբությունը տարածվեց Մորեա. Կալավրիտայում (հուլյան 21 մարտի) սկսված զինված գործողությանը հաջորդեցին Պատրասի, Կալամատայի և Մանիի շարժումները. Մորեան կարճ ժամանակում վերածվեց համընդհանուր ապստամբության, և օսմանյան վարչությունը կորցրեց թերակղզու մեծ մասը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Աթենք, Բալյաբադրա (Պատրաս), Իստեֆե (Թեբե), Լիվադիա, Էլևսիս (Ատտիկա), Միսսոլոնգի։", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Վաքա-ի Խայրիյե — ենիչերիական զորաբանակի վերացումը", "08c9372a"], "d": ["Նորաստեղծ Էշքինջի զորաբանակի վարժանքների դեմ ապստամբած («կաթսան շրջած») ենիչերիները Մահմուդ II-ի նախապես պատրաստած հավատարիմ զորամասերի թնդանոթային կրակով ոչնչացվեցին Էթմեյդանիի իրենց զորանոցներում. զորաբանակը լուծարվեց իր բոլոր ճյուղերով և դրան կապված բեքթաշիական թեքքեներով։ «Բարեբեր իրադարձություն» նշանակող անունով պատմության մեջ մտած այս գործողությունը, վերացնելով չորս դարի հաստատությունը, ճանապարհ բացեց Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյե բանակի և կենտրոնացման հետագա բոլոր բարեփոխումների առաջ։", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Նավարինի հարձակումը", "ee579e7f"], "d": ["Հունական ապստամբությունը ճնշող օսմանա-եգիպտական նավատորմը Նավարինում այրվեց առանց պատերազմ հայտարարելու նավահանգիստ մտած անգլո-ֆրանս-ռուսական միացյալ նավախմբի կողմից. կորսվեցին մոտ վաթսուն նավ և հազարավոր նավաստիներ։ Եվրոպական դիվանագիտության մեջ որպես «դժբախտ դեպք» շրջանցված այս հարձակումը փաստացի երաշխավորեց Հունաստանի անկախությունը և ճանապարհ բացեց 1828–29 թվականների ռուս-թուրքական պատերազմի համար։", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Թանզիմաթի ֆերմանը", "5042ce7b"], "d": ["Գյուլհանեում ընթերցված Խաթթ-ը Հյումայունով առանց կրոնի խտրության բոլոր հպատակների կյանքի, գույքի և պատվի անվտանգությունը վերցվեց պետական երաշխիքի տակ. հռչակվեցին հարկերում արդարության, զինվորական ծառայության մեջ կարգուկանոնի և առանց դատաստանի պատիժ չսահմանելու սկզբունքները։ Մուստաֆա Ռեշիդ փաշայի ստեղծագործությունը եղած ֆերմանը համարվում է օսմանյան արդիականացման սահմանադրական բնույթի առաջին մեծ փաստաթուղթը և իր անունը տվել է «Թանզիմաթի դարաշրջան» (1839–1876) բարեփոխումների ժամանակաշրջանին. կառավարման, իրավունքի, կրթության և ֆինանսների արմատական վերակառուցումը իրականացվեց այս շրջանակում։", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Սկսվեց Ղրիմի պատերազմը", "3b9ca3c8"], "d": ["Սրբավայրերի հարցից և ուղղափառ հպատակների նկատմամբ Ռուսաստանի հովանավորության հավակնությունից սկիզբ առած ճգնաժամը Օսմանյան պետության պատերազմ հայտարարելով վերածվեց բացահայտ ընդհարման. Սինոպի հարձակումից հետո Անգլիան և Ֆրանսիան (ապա Պիեմոնտը) պատերազմի մեջ մտան օսմանցիների կողմում։ Դաշնակից բանակների՝ Ղրիմում ափհանվելով Սևաստոպոլը գրավելով պատերազմը հաղթական ավարտվեց 1856 թվականի Փարիզի պայմանագրով. սակայն պատերազմի տարիներին վերցված առաջին արտաքին պարտքը (1854) կայսրությանը ներքաշեց կես դար տևելիք ֆինանսական կախվածության պարույրի մեջ։", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Բարեփոխումների (Իսլահաթի) ֆերմանը", "78ff234d"], "d": ["Փարիզի հաշտության բանակցություններից առաջ հռչակված ֆերմանը, ընդլայնելով Թանզիմաթի սկզբունքները, ոչ մուսուլման հպատակներին ընձեռեց լայն հավասար իրավունքներ՝ ներառյալ պետական պաշտոն, զինվորական ծառայություն և դպրոց բացելը. վերակարգավորվեցին համայնքային կազմակերպությունները։ Դրանից հետո ստորագրված Փարիզի պայմանագրով Օսմանյան պետությունը պաշտոնապես ընդունվեց եվրոպական պետությունների իրավունքի ընտանիք, և նրա տարածքային ամբողջականությունը վերցվեց մեծ տերությունների համատեղ երաշխիքի տակ. այս երաշխիքը գործնականում դառնալու էր միջամտությունների նոր դուռ։", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Կանուն-ը Էսասի — Առաջին սահմանադրական շրջանը", "0fe052c1"], "d": ["Բալկանյան ճգնաժամը քննարկելու համար Ստամբուլում հավաքված միջազգային խորհրդաժողովի բացման օրը թնդանոթային համազարկերով հռչակվեց օսմանյան առաջին սահմանադրությունը. Միդհաթ փաշայի գլխավորած «Նոր օսմանցիների» շարժման ստեղծագործությունը եղած Կանուն-ը Էսասիով հիմնվեց երկպալատ խորհրդարան։ Մեբուսանների ժողովը (Meclis-i Meb'ûsan) բացվեց 1877 թվականի մարտին. սակայն Աբդուլ Համիդ II-ը, պատճառաբանելով «93 թվականի պատերազմը», 1878 թվականի փետրվարին անորոշ ժամկետով արձակեց ժողովը, և սահմանադրությունը երեսուն տարի մնաց կասեցված։", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["«93 թվականի պատերազմը» (1877–78 թվականների ռուս-թուրքական պատերազմ)", "5bd96af7"], "d": ["Քանի որ համընկնում էր ռումի 1293 թվականին՝ «93 թվականի պատերազմ» անվանված այս պատերազմում ռուսական բանակները հարձակվեցին երկու ճակատով. թեև Ղազի Օսման փաշայի՝ Պլևնայի պաշտպանությունը և Ահմեդ Մուխթար փաշայի կովկասյան մարտերը դարձան լեգենդար, ճակատը փլուզվեց, և ռուսները առաջացան մինչև Եշիլքյոյ (Սան Ստեֆանո)։ Պատերազմը սկիզբ դրեց Բալկաններից և Կովկասից Ստամբուլ ուղղված՝ մուսուլմանների գաղթի մեծ ալիքների, որոնց հետևանքները հասնում են մինչև այսօր. կայսրության ժողովրդագրական և ֆինանսական կառուցվածքը այլևս չվերադարձավ նախկին վիճակին։", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Բեռլինի պայմանագիրը", "47f76a49"], "d": ["Սան Ստեֆանոյի ստեղծած «Մեծ Բուլղարիան» մեծ տերությունների հավասարակշռության անունից վերանայած Բեռլինի վեհաժողովը, այնուամենայնիվ, թողեց ծանր պատկեր. Սերբիան, Չեռնոգորիան և Ռումինիան անկախացան. հիմնվեց Բուլղարիայի ինքնավար իշխանապետությունը. Բոսնիա և Հերցեգովինան թողնվեց ավստրիական օկուպացիային, Կիպրոսը՝ անգլիական կառավարմանը, Կարս-Արդահան-Բաթումը՝ Ռուսաստանին։ Ռումելիում հինգհարյուրամյա օսմանյան կարգը մեծ մասամբ քայքայվեց. «Արևելյան հարցը» դարձավ եվրոպական դիվանագիտության մշտական օրակարգ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ֆիլիպե, Վիդին, Տառնովո, Վառնա, Շումեն, Սիլիստրա, Ռուսչուկ, Բուխարեստ, Յասսի, Քյոսթենջե։ Ռումինիան Բեսարաբիան Ռուսաստանին տալու դիմաց ստացավ Թուլչան (Tulcea) և Դոբրուջան. Հյուսիսային Դոբրուջայի Թուլչան, Բաբադագը (Babadag), Մաչինը, Իսակչան (Isaccea), Հըրշովան (Hârșova) և Մանգալիան (Mangalia) անցան Ռումինիային։", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Թունիսի օկուպացիան և Օսմանյան պետական պարտքի վարչությունը (Դույուն-ը Ումումիյե)", "c7e25598"], "d": ["Ֆրանսիան, պատրվակ դարձնելով Ալժիրի սահմանի դեպքերը, օկուպացրեց Թունիսը և Բարդոյի պայմանագրով վերցրեց իր հովանավորության տակ. Հյուսիսային Աֆրիկայում օսմանյան ներկայությունը սահմանափակվեց Տրիպոլիտանիայով։ Նույն տարում ընդունված Մուհառամի հրամանագրով սնանկացած արտաքին պարտքերի կառավարման համար հիմնվեց Պետական պարտքի վարչությունը, որտեղ ներկայացված էին պարտատերերը. աղը, ծխախոտը, մետաքսը և այլ հիմնական եկամուտներ ուղղակիորեն կապվեցին այս օտար վարչությանը, և ֆինանսական ինքնիշխանությունը ծանր կերպով սահմանափակվեց։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Կայրավան, Գաբես, Սֆաքս, Ջերբա (Djerba)։", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Եգիպտոսի անգլիական օկուպացիան", "f1269768"], "d": ["Եգիպտոսում ֆինանսական սնանկության և օտարերկրյա վերահսկողության դեմ բարձրացած Ուրաբի փաշայի շարժումը ճնշվեց Ալեքսանդրիայի ռմբակոծությունից հետո ափհանված անգլիական բանակի՝ Թել ալ-Քեբիրի հաղթանակով, և Կահիրեն օկուպացվեց։ Եգիպտոսը իրավաբանորեն շարունակեց կապված մնալ Օսմանյան պետությանը, սակայն փաստացի անցավ անգլիական կառավարման տակ. Սուեզի ջրանցքի վերահսկողությունը տեղավորվեց Բրիտանական կայսրության ռազմավարության կենտրոնում։", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Երկրորդ սահմանադրական շրջանի հռչակումը", "95ee2fd2"], "d": ["«Միություն և առաջադիմություն» կոմիտեին կապված սպաների՝ Մակեդոնիայում լեռներ բարձրանալով մեծացած շարժման դեմ Աբդուլ Համիդ II-ը կրկին ուժի մեջ դրեց Կանուն-ը Էսասին. «ազատության հռչակումը» դիմավորվեց խանդավառությամբ, և անցկացվեցին ընտրություններ։ Սակայն կայունությունը չեկավ. մարտի 31-ի դեպքը (1909 թվականի ապրիլ) ճնշելուց հետո Աբդուլ Համիդը գահընկեց արվեց. Բուլղարիայի անկախությունը, Բոսնիայի բռնակցումը և Կրետեի՝ դեպի Հունաստան թեքվելը ևս տեղի ունեցան այս խռովահույզ ամիսներին։", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Տրիպոլիտանիայի պատերազմը", "ed441994"], "d": ["Գաղութներ փնտրող Իտալիան պատերազմ հայտարարեց Օսմանյան պետության վերջին հյուսիսաֆրիկյան հողին՝ Տրիպոլիտանիային, և օկուպացրեց ափերը. քանի որ նավատորմ չունեցող պետությունը չկարողացավ կանոնավոր բանակ ուղարկել, երիտասարդ սպաներ, ինչպիսիք էին Մուստաֆա Քեմալը և Էնվեր բեյը, գաղտնի անցան շրջան և սանուսի ցեղերի հետ կազմակերպեցին արդյունավետ դիմադրություն։ Բալկանյան պատերազմի բռնկման պատճառով ստորագրված Ուշիի պայմանագրով (1912 թվականի հոկտեմբերի 18) Լիբիան թողնվեց Իտալիային. Իտալիան նաև օկուպացրեց Ռոդոսը և Դոդեկանեսը (Տասներկու կղզիները)։", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Լոնդոնի պայմանագիրը — Ռումելիի կորուստը", "f3f976df"], "d": ["Բալկանյան առաջին պատերազմին վերջ դրած Լոնդոնի պայմանագրով կորսվեցին Միդիա-Էնոս գծից արևմուտք գտնվող բոլոր հողերը և Էգեյան կղզիները. Ալբանիան անկախացավ։ Ավելի քան հինգ հարյուր տարի կայսրության ժողովրդագրական, տնտեսական և մշակութային ծանրության կենտրոնը եղած Ռումելիից մնալու էր միայն Արևելյան Թրակիան (Էդիրնեն հետ վերցվեց Բալկանյան երկրորդ պատերազմում). կորուստն արմատապես կոշտացրեց իթթիհադական կառավարության պատերազմի և բնակեցման քաղաքականությունը։ Միդիա-Էնոս գծից արևմուտք մնացած հետևյալ վայրերը ձեռքից դուրս եկան՝ Սկոպյե, Քյոփրյուլյու (Վելես), Իշտիպ (Štip), Ուստրումջա, Դոյրան, Գևգիլի (Gevgelija), Մանաստիր, Օհրիդ, Դեբրե (Dibra), Պրիզրեն, Պրիշտինա, Պեչ (Pejë), Ենիփազար (Novi Pazar), Կոսովոյի դաշտ (Kosovo Polje). Սերեզ, Դրամա, Կավալա, Պետրիչ, Նևրոկոփ, Իսքեչե, Գյումյուլջինե, Դեդեաղաչ, Դիդիմոտիխո, Չիրմեն, Ֆերեջիկ (Feres), Սոֆուլու (Soufli), Օրեստիադա (Կումչիֆթլիղի), Պրավիշտե (Eleftheroupoli), Stérna, Távri, Ումուր Ֆաքիհ (Fakia), Մալաք Դերվենթ (Lalkovo). Կրետեում՝ Խանիա, Կանդիա, Կրետե (Ռեսմո), Սիտիա (Sitia) և Իսֆաքիյե (Sfakia)։", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Մուտքը Առաջին համաշխարհային պատերազմ", "05a0252e"], "d": ["Անգլիացիներից փախած «Գյոբեն» և «Բրեսլաու» զրահանավերը, ներկայացվելով որպես գնված, ներս թողնվեցին Բոսֆոր, ինչը քայլ առ քայլ պետությանը տարավ Գերմանիայի կողմը. ծովակալ Սուշոնի հրամանատարությամբ նավատորմի կողմից ռուսական նավահանգիստների ռմբակոծումով (հոկտեմբերի 29) պատերազմը փաստացի սկսվեց, իսկ փոխադարձ հայտարարությունները եղան նոյեմբերի սկզբին։ Չնայած Մեծ ջիհադի (Cihâd-ı Ekber) հռչակմանը՝ սպասված ազդեցությունը չառաջացավ. կայսրությունը չորս տարի շարունակ Կովկասից Պաղեստին՝ հինգ առանձին ճակատներում, գոյության պատերազմի մեջ մտավ։", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Չանաքքալեի (Դարդանելի) հաղթանակը", "95d888e8"], "d": ["Ստամբուլը գցելու և Ռուսաստանի հետ կապ հաստատելու նպատակ ունեցող դաշնակից արմադան մարտի 18-ին ականապատ գծերի և ամրությունների կրակով ետ շպրտվեց նեղուցից. «Նուսրեթ» ականակիրի դրած ականային գիծը որոշեց մարտի ճակատագիրը։ Ապրիլին սկսված Գելիբոլուի ցամաքային գործողությունը ևս կանգնեցվեց Անաֆարթալարում և Ջոնքբայըրըում. դաշնակիցները 1916 թվականի հունվարին ամբողջությամբ դատարկեցին թերակղզին։ Փոխգնդապետ Մուստաֆա Քեմալի անունը լսելի դարձավ այս ճակատում. շուրջ քառորդ միլիոն նահատակների և կորուստների գնով տարած այս հաղթանակը համարվում է այն վայրը, որտեղ ծնվեցին Ազգային պայքարի կադրերն ու ոգին։", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Շերիֆ Հուսեյնի ապստամբությունը", "75f7c58c"], "d": ["Մեքքայի էմիր Շերիֆ Հուսեյնը, անգլիացիների հետ վարած գաղտնի նամակագրությունից հետո, ապստամբեց անկախ արաբական թագավորության խոստումով. Հիջազի երկաթուղին դարձավ հարձակումների թիրախ։ Թեև Ֆահրեդդին փաշայի՝ Մեդինայի լեգենդար պաշտպանությունը, որ շարունակվեց մինչև զինադադարից հետո, մնաց որպես դիմադրության խորհրդանիշ, ապստամբությունը, միանալով Պաղեստինի ճակատում անգլիական առաջխաղացմանը, արագացրեց արաբական վիլայեթներում օսմանյան տիրապետության քայքայումը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Խուրմա, Թուրաբա։", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Մուդրոսի զինադադարը", "9e87c767"], "d": ["Բուլղարիայի փլուզմամբ ճակատներն իրարից կտրված Օսմանյան պետությունը դուրս եկավ պատերազմից «Ագամեմնոն» զրահանավի վրա ստորագրված զինադադարով։ Նեղուցների բացումը և հատկապես 7-րդ հոդվածը, որը հնարավորություն էր տալիս գրավել անվտանգությանը սպառնացող վայրերը, կարճ ժամանակում դարձան փաստացի բաժանման իրավական քող. օկուպացվեցին Մոսուլը, Ալեքսանդրետը, ապա Իզմիրը և Ստամբուլը։ Զինադադարը համարվում է կայսրության փաստացի ավարտի փաստաթուղթը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Համա, Դամասկոս, Հոմս։", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Մուստաֆա Քեմալը Սամսունում — Ազգային պայքարը", "09a8f784"], "d": ["Իզմիրի օկուպացիայի առաջացրած զայրույթի մթնոլորտում 9-րդ բանակի տեսուչի կարգավիճակով Սամսունում ափ իջած Մուստաֆա Քեմալ փաշան իր պաշտոնական հանձնարարությունը վերածեց Անատոլիայում դիմադրության կազմակերպման։ Ամասիայի շրջաբերականը և Էրզրումի ու Սեբաստիայի վեհաժողովները այս քայլի շարունակությունն են. «ազգի անկախությունը կփրկի դարձյալ ազգի հաստատակամությունն ու որոշումը» սկզբունքը դարձավ Ազգային պայքարի քաղաքական ծրագրի միջուկը։", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Թուրքիայի Ազգային մեծ ժողովի բացումը և Սևրը", "2008feec"], "d": ["Ստամբուլի պաշտոնական օկուպացիայի և Մեբուսանների ժողովի ցրման առիթով 1920 թվականի ապրիլի 23-ին Անկարայում բացվեց Ազգային մեծ ժողովը. արտակարգ լիազորություններն իր ձեռքում կենտրոնացրած ժողովը դարձավ ազգային կամքի վրա հիմնված նոր պետության միջուկը։ Օգոստոսին Ստամբուլի կառավարության ստորագրած Սևրի պայմանագիրը բաժանում էր Անատոլիան. Ազգային մեծ ժողովը պայմանագիրը ստորագրողներին հայտարարեց հայրենիքի դավաճաններ, և Սևրը երբեք չկիրառվեց։", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Սաքարիայի դաշտային ճակատամարտը", "f2f970a6"], "d": ["Անկարային մինչև 50 կիլոմետր մոտեցած հունական հարձակումը կոտրվեց 22 օր ու 22 գիշեր տևած ճակատամարտում, որը վարվեց գերագույն հրամանատարի լիազորությունն ստանձնած Մուստաֆա Քեմալ փաշայի «չկա պաշտպանության գիծ, կա պաշտպանության տարածք» հրամանով։ Հունական բանակն առաջին անգամ անցավ ռազմավարական պաշտպանության. հաղթանակը Մուստաֆա Քեմալին բերեց ղազիի կոչում և մարշալի աստիճան, բացեց Անկարայի համաձայնագրի (Ֆրանսիայի հետ) և արտաքին ճանաչման դուռը։", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Մեծ հարձակումը և Իզմիրի ազատագրումը", "172a50c4"], "d": ["Օգոստոսի 26-ի առավոտյան Քոջաթեփեից սկսված հարձակումը օգոստոսի 30-ին Դումլուփընարում Գերագույն հրամանատարի դաշտային ճակատամարտով հասավ հունական հիմնական ուժերի ոչնչացմանը. «Բանակներ, ձեր առաջին նպատակակետը Միջերկրական ծովն է, առա՛ջ» հրամանով շարունակվող հետապնդմամբ սեպտեմբերի 9-ին Իզմիրը ազատագրվեց։ Մուդանիայի զինադադարով (հոկտեմբերի 11) Արևելյան Թրակիան հետ վերցվեց առանց պատերազմի. ռազմական հաղթանակը որոշեց Լոզանում ստեղծվելիք նոր պետության ուժը բանակցային սեղանի շուրջ։", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Սուլթանության վերացումը", "9f36a9f6"], "d": ["Լոզանի բանակցություններին նաև Ստամբուլի կառավարությանը հրավիրելու առիթով Ազգային մեծ ժողովը 1922 թվականի նոյեմբերի 1-ին, իրարից բաժանելով սուլթանությունը և խալիֆայությունը, վերացրեց սուլթանությունը. 623-ամյա օսմանյան հարստության կառավարումը իրավաբանորեն ավարտվեց։ Մեհմեդ VI Վահիդեդդինը նոյեմբերի 17-ին անգլիական զրահանավով լքեց երկիրը. խալիֆայության աթոռին Ազգային մեծ ժողովի որոշմամբ նշանակվեց Աբդուլմեջիդ էֆենդին, և այդ աթոռը ևս վերանալու էր 1924 թվականի մարտի 3-ին։", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Լոզանի պայմանագիրը", "38c27f7d"], "d": ["Ութ ամիս տևած ծանր բանակցությունների վերջում ստորագրված Լոզանի հաշտության պայմանագրով միջազգային մակարդակում ճանաչվեցին նոր թուրքական պետության սահմանները, լիակատար անկախությունը և ինքնիշխանությունը. վերացվեցին կապիտուլյացիաները, Պետական պարտքի վարչությունը մտավ լուծարման գործընթաց, կարգավորվեց բնակչության փոխանակությունը։ Սևրը փաստացի անվավեր դարձրած Լոզանը համարվում է Ազգային պայքարի դիվանագիտական հաղթանակը և Հանրապետության հիմնադիր արտաքին փաստաթուղթը։", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Հանրապետության հռչակումը", "d5bfcdfb"], "d": ["Ազգային մեծ ժողովի՝ սահմանադրության փոփոխությամբ «Թուրքիայի պետության կառավարման ձևը հանրապետությունն է» դրույթն ընդունելով հռչակվեց Հանրապետությունը. Մուստաֆա Քեմալ փաշան ընտրվեց առաջին նախագահ։ Այսպիսով ավարտվեց 1299 թվականին որպես սահմանամերձ բեյլիք սկսված 624-ամյա օսմանյան ուղին, և կայսրության ժառանգության վրա հիմնվեց նոր պետություն, որտեղ ինքնիշխանությունն անվերապահորեն պատկանում է ազգին։", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["Թեփեդելենլի Ալի փաշայի պաշտոնանկությունը և Յանինայի պաշարման սկիզբը", "e8a6530b"], "d": ["Մահմուդ II-ի՝ տեղական ուժերը վերացնելու քաղաքականությունը հասավ Թեփեդելենլի Ալի փաշային, ով երեսուներեք տարի կառավարում էր Յանինան և փաստացի իր ձեռքում էր պահում Թեսալիան և Էպիրոսը։ Փաշան ազատվեց լեռնանցքների գլխավորի պաշտոնից, իսկ նրա որդի Վելին՝ Տրիկալայի փաշայությունից. քանի որ սպասվում էր, որ նա չի ենթարկվի, նրա դեմ զորք ուղարկվեց։ Այս գործը հանձնարարված Հուրշիդ Ահմեդ փաշան միաժամանակ Մորեայի կուսակալն էր և նրան տրվել էր նաև Ռումելիի սերասքերությունը. շրջանի բոլոր քաղաքացիական և ռազմական ղեկավարներին հանձնարարվեց ձերբակալել Թեփեդելենլիին։ Այսինքն, երբ հունական ապստամբությունը բռնկվեց, Մորեան կառավարելու ենթակա հրամանատարը և նրա ենթակա ուժերը պաշարում էին Յանինայի բերդը։ Ալի փաշան 1820 թվականի մայիսի 23-ին Յանինայում հույների հետ հանդիպում կազմակերպեց, փորձեց իր կառավարման տակ հիմնել հունական էյալեթ և նրանց դրամով ու զենքով օգնեց։ Հակառակ կողմում արհամարհելի ուժ չկար. Ալի փաշան ուներ 30-40.000-անոց բանակ, որից 7.000-ը մշտական, և փոքր նավատորմ. նրա կառավարման տակ գտնվող բնակչությունը գնահատվում էր 1,5-2 միլիոն, տարեկան եկամուտը՝ 4-5 միլիոն ղուրուշ։", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["Սկսվեց օսմանյան-իրանական պատերազմը. Կարսի և Բայազիդի կորուստը, Էրզրումի պաշարումը", "570b27bd"], "d": ["Հունական ապստամբության երկրորդ տարում կայսրության արևելյան սահմանը վերածվեց պատերազմի գոտու։ Ղաջարյան գահաժառանգ Աբբաս Միրզան, պատրվակ դարձնելով այն, որ շահի հաջի գնացող կնոջ գտնվելու քարավանը խուզարկվել էր օսմանյան ներկայացուցիչների կողմից, մեծ ռազմական ուժով անցավ սահմանը. գրավեց Կարսի և Բայազիդի վիլայեթները և պաշարեց Էրզրումը։ Նրա դեմ կանգնած ուժը սովորական սահմանային զորամաս չէր. Աբբաս Միրզան Ատրպատականի բանակը վարժեցրել էր եվրոպական եղանակով, Թավրիզում վառոդի արհեստանոց և թնդանոթի գործարաններ էր հիմնել տվել։ Իսկ Օսմանյան պետությունը այդ ժամանակ արևմուտքում զբաղված էր Մորեայի ապստամբությամբ, հյուսիս-արևմուտքում՝ Թեփեդելենլի Ալի փաշայի Յանինայի դիմադրությամբ և ձեռքի տակ եվրոպական եղանակով վարժված բանակ չուներ. ենիչերիների օջախը պիտի գոյատևեր մինչև 1826 թվականը։", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["Սուլեյմանիեի և Բաղդադի իրանական օկուպացիան. Կիրկուկի պաշարումը", "384d74e4"], "d": ["Արևելյան Անատոլիայի գործողությանը զուգահեռ իրանական ուժերը լայնածավալ հարձակում կազմակերպեցին օսմանյան կառավարման տակ գտնվող Հյուսիսային Իրաքի և Բաղդադի էյալեթի վրա։ Բաղդադը այդ ժամանակ կառավարում էր 1817 թվականից կուսակալ եղած Քյոլեմեն Դավուդ փաշան. փաշան ուներ Նապոլեոնի նախկին համհարզներից Դևոյի վարժեցրած 10.000-անոց հետևակային և թնդանոթաձիգ ուժ։ Կայսրության կենտրոնում դեռ այդպիսի բանակ չկար. եվրոպական եղանակով վարժված զորամասերը այդ տարիներին միայն գավառի ուժեղ կուսակալների ձեռքում էին։ Պատերազմն ավարտողը օսմանյան հաղթանակ չեղավ. օսմանյան դիմադրությունը և Ատրպատականը պատած համաճարակը ստիպեցին իրանական ուժերին նահանջել։", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["Թեփեդելենլի Ալի փաշայի սպանությունը. Յանինայի պաշարման ավարտը", "da679150"], "d": ["Յանինայի դիմադրությունը տևեց մոտ երկու տարի, և հենց այս ընթացքում հունական ապստամբությունը ընդհանուր տարածում ստացավ։ Երբ Հուրշիդ փաշան, լրտեսներ ուղարկելով բերդ, փախչողներին կոչումներ և նվերներ բաժանեց, Ալի փաշայի շուրջ եղած զինվորների թիվը իջավ քառասուն-հիսունի. փաշան, երաշխիք ստանալով, որ հանձնվելու դեպքում իր կյանքին ձեռք չեն տա, քաշվեց լճի վրա գտնվող Սուրբ Պանդելեյմոնի վանքը։ Այդ ժամանակ Հուրշիդ փաշայի ընտանիքն ընկել էր հույն ապստամբների ձեռքը. որպեսզի շուտ վերադառնա Մորեա, նա, անտեսելով տված ապահովագիրը, կեղծ մահապատժի ֆերման պատրաստել տվեց։ Երբ մտան նրա սենյակ, Ալի փաշան պատասխանեց զենքով և սպանվեց ծագած բախման մեջ. նրա գլուխը փետրվարի 24-ին բերվեց Ստամբուլ։ Պաշարումը բացահայտել էր նաև օսմանյան հրամանատարության ներքին ճեղքը. երբ Մորեայի ապստամբությունը Թեփեդելենլիի հարցից վտանգավոր դարձավ, Սեյիդ Ալի փաշան նշանակվեց Մորեայի առանձին սերասքեր, և դրանից դժգոհ Հուրշիդ փաշան մերժեց նրա օգնության խնդրանքները, նույնիսկ փորձեց նրան պետության աչքում անհաջող ցույց տալ։ Ալի փաշային վերացնելու տարվա վերջում ընկավ Մորեայի ամենաուժեղ բերդը՝ Նավպլիոնը։", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["Էրզրումի պայմանագիր. իրանական ուժերի դուրսբերումը վաթսուն օրում", "166373c3"], "d": ["Երկու տարի տևած պատերազմն ավարտվեց Էրզրումում ստորագրված հաշտության պայմանագրով։ Պայմանագրի համաձայն իրանական ուժերը վաթսուն օրվա ընթացքում պիտի հեռանային իրենց օկուպացրած հողերից։ Պայմանագիրը նոր սահման չգծեց, վերադարձրեց նախապատերազմյան վիճակը. երկու պետության սահմանային վեճերը 1833-1842 թվականներին կրկին կվերածվեն բախման և միայն 1847 թվականին կկարգավորվեն երկրորդ պայմանագրով՝ կրկին Էրզրումում ստորագրված։ Արևելյան ճակատի փակվելը նախապայման էր, որ կայսրությունը կարողանա իր ամբողջ ուժը ուղղել հունական ապստամբության դեմ։", "7c54983b"]},
"OLAYLAR_2S0920:0224-04-28:0":{"b": ["Հորմոզգանի ճակատամարտը. Արտաշիր I-ը հաղթեց պարթև տիրակալ Արտաբան V-ին. Սպահանը մտավ Սասանյան կորիզի մեջ", "3689fd45"], "d": ["Ֆարսի տեղական տիրակալ Արտաշիրը Հորմոզգանում հաղթեց պարթև տիրակալ Արտաբան V-ին. Պարթևական (Արշակունյաց) հարստությունը փլուզվեց, և բարձրացավ Սասանյան հարստությունը։ Ատլասն այս օրվանից սկսած Սպահանը համարում է Սասանյան հող։", "3551fe9f"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["Կարաֆերիեի (Վերիա) անցումը օսմանյան տիրապետության տակ", "b0ece3f3"], "d": ["1387 թվականին Սալոնիկի հանձնվելու հետ նույն տարում օսմանյան տիրապետության տակ անցավ նաև Ստորին Մակեդոնիայի ներքին մասի Կարաֆերիեն։ Քաղաքը Սալոնիկի և Թեսալիայի միջև ճանապարհի հանգուցակետն էր։", "4e571f7b"]},
"OLAYLAR_2S0920:1506-07-08:0":{"b": ["Ալբրեխտ IV Վիտելսբախը հրապարակեց պրիմոգենիտուրայի կանոնադրությունը. Բավարիայի դքսությունները միավորվեցին և դարձան անբաժանելի մեկ դքսություն", "86ee6f77"], "d": ["Լանդսհուտի ժառանգական պատերազմից (1503-1505) հետո Բավարիայի դքսությունները կրկին մեկ ձեռքում հավաքած դուքս Ալբրեխտ IV-ը 1506 թվականի հուլիսի 8-ին հրապարակեց պրիմոգենիտուրայի կանոնադրությունը, որը նախատեսում էր երկրի անբաժանելիությունը և գահի անցումը ավագ արու զավակին։ Այսպիսով վերջ գտան 1255 թվականից շարունակվող Բավարիայի բաժանումները. Մյունխեն կենտրոնով Բավարիան գերմանական պետությունների շարքում շարունակեց որպես անբաժանելի մեկ դքսություն։", "26058158"]},
"OLAYLAR_2S0920:1517-04-15:0":{"b": ["Ամիր II-ը սպանվեց Սանաայի մոտ. Թահիրյան հարստության վախճանը", "713ae406"], "d": ["Թահիրյանների վերջին տիրակալ Ամիր II-ը, մամլուքների նավատորմի հետ հարաբերությունների վատթարացման պատճառով սկսված պատերազմում, երբ եմենյան ցեղերն ու զեյդիները աջակցեցին մամլուքներին, նախ պարտվեց Զաբիդի մոտ (1516 թ. նոյեմբեր), ապա զոհվեց Սանաայի մոտ տեղի ունեցած ճակատամարտում։ Այսպիսով ավարտվեց 1454 թվականից Եմենը կառավարող Թահիրյան հարստությունը. հարստության քաղաքները (ներառյալ Թաիզը) այլևս ենթակա չէին Թահիրյան տիրակալությանը։", "4b9725ef"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["Լուգոշ (Լուգոժ) և Կարանշեբեշ ամրոցների նվաճումը՝ Թեմեշվարի արշավանքի շարունակությունը", "1af5a2be"], "d": ["Թեմեշվարի ամրոցը երեք շաբաթ դիմադրելուց հետո 1552 թվականի հուլիսի 26-ին հանձնվեց։ Օգոստոսին գրավվեցին նաև Լուգոշի և Կարանշեբեշի ամրոցները. Մուրեշի հովտի երկայնքով գրավվեց տասնհինգ ամրոց, և ստեղծվեց Թեմեշվար կենտրոնով նոր բեյլերբեյություն։", "ecd1e532"]},
"OLAYLAR_2S0920:1723-11-18:0":{"b": ["Հիմնադրվեց Եկատերինբուրգի երկաթի գործարան-ամրոցը՝ Ուրալի հանքային շրջանի կենտրոնը", "c416e12e"], "d": ["Իսետ գետի վրա Տատիշչևի ընտրած տեղում դե Գենինի ավարտին հասցրած երկաթի գործարանի դարբնամուրճերը գործարկվեցին. Եկատերինբուրգն այս օրն է համարում իր հիմնադրման թվականը։ Ուրալի հանքերի ու երկաթի շրջանի կենտրոն դառնալիք բնակավայրը դարձավ Ռուսական թագավորության՝ դեպի Սիբիր տանող ճանապարհի դարպասը։", "8d081bcf"]},
"OLAYLAR_2S0920:1902-03-01:0":{"b": ["Զարիան (Զազաուն) անցավ բրիտանական վարչական վերահսկողության տակ. Սոկոտոյի խալիֆայության Զարիայի ամիրայությունը կապվեց Հյուսիսային Նիգերիայի պրոտեկտորատին", "c2e4131e"], "d": ["Սոկոտոյի խալիֆայությանը ենթակա Զարիայի ամիրայությունը 1902 թվականի մարտին առնվեց Անգլիայի Հյուսիսային Նիգերիայի վարչության տակ. անգլիացիները Զարիայում տեղակայեցին ռեզիդենտ և կայազոր։ Ամիր Կվասաուն 1902 թվականի հուլիսին անձնատուր եղավ, իսկ սեպտեմբերին պաշտոնանկ արվեց։", "d2ce29e8"]},
"OLAYLAR_2S0920:1903-02-01:0":{"b": ["Անգլիացիները գրավեցին Կանոն. Սոկոտոյի խալիֆայության ամենամեծ ամիրայությունն անցավ Հյուսիսային Նիգերիայի պրոտեկտորատին", "0484009d"], "d": ["Հյուսիսային Նիգերիայի բարձր կոմիսար Լուգարդի ենթակայության տակ գտնվող գնդապետ Մորլենդի զորաջոկատը, Զարիայից շարժվելով, 1903 թվականի փետրվարին գրավեց Կանոն. Սոկոտոյի խալիֆայությանը ենթակա Կանոյի ամիրայությունն անցավ բրիտանական կառավարման տակ։ Սոկոտոն գրավվեց մեկ ամիս անց՝ 1903 թվականի մարտի 15-ին։", "33350275"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["Պրիշտինայի անցումը սերբական բանակի ձեռքը", "2ef111c0"], "d": ["Բալկանյան առաջին պատերազմում Կոսովո մտած սերբական բանակը գրավեց Պրիշտինան, և քաղաքում վերսկսվեց սերբացման քաղաքականությունը։ Պրիշտինայի անկումը Կոսովոյի վիլայեթում օսմանյան դիմադրության փլուզման առաջին օղակներից է։", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["Մոնաստիրի գրավումը սերբական ուժերի կողմից", "db9b3353"], "d": ["Բալկանյան առաջին պատերազմում Մակեդոնիայի կարևորագույն վարչական և ռազմական կենտրոններից մեկը՝ Մոնաստիրը, հինգ օր տևած մարտերից հետո անցավ սերբական ուժերի ձեռքը։ Քաղաքի կորուստը նշանակում էր Մակեդոնիայում Օսմանյան պետության ներկայության փաստացի ավարտը։", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["Ալբանիայի անկախության հռչակումը. Իսմաիլ Քեմալին Վլյորայում", "2cdbd4d9"], "d": ["Մինչ Բալկանյան պատերազմի բանակները մտնում էին ալբանական վիլայեթները, Իսմաիլ Քեմալին Վլյորայում հռչակեց Ալբանիայի անկախությունը։ Այսպիսով Դուրեսից, Էլբասանից, Բերատից, Գիրոկաստրայից և Կրույայից մինչև Սարանդա ձգվող ծովափնյա և ներքին շրջանները դուրս եկան օսմանյան կառավարումից և կազմեցին նոր ալբանական պետության կորիզը։", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["Օսմանյան տիրապետության վախճանը Օհրիդում և Դիբրայում", "5273f1ec"], "d": ["Մոնաստիրի անկումից տասնմեկ օր անց սերբական բանակը մտավ արևմտյան Մակեդոնիայի լճերի շրջանը. Օհրիդում ավարտվեց հինգդարյա օսմանյան տիրապետությունը, և հյուսիսում գտնվող Դիբրան ևս նույն գործողության ընթացքում դուրս եկավ ձեռքից։", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["Շկոդրայի գրավումը չեռնոգորցիների կողմից", "db704247"], "d": ["Բալկանյան առաջին պատերազմի ամենաերկար պաշարումներից մեկը տեղի ունեցավ Շկոդրայում. ամիսներ տևած դիմադրությունից հետո քաղաքը հանձնվեց Չեռնոգորիայի ուժերին։ Շկոդրան այն վերջին օսմանյան ամրոցներից էր, որոնք դիմադրեցին մինչև պատերազմի ավարտը։", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["Չեռնոգորիան դուրս բերեց ուժերը Շկոդրայից. մեծ տերությունների միջազգային զորամիավորումը մտավ քաղաք", "8a6593e9"], "d": ["Մեծ տերությունների ճնշման տակ Չեռնոգորիան 1913 թվականի ապրիլի 23-ին գրաված Շկոդրան 1913 թվականի մայիսի 14-ին դատարկեց. քաղաք մտավ միջազգային զորամիավորումը, և այն դարձավ Ալբանիայի հիմնադիր վարչակարգի մաս։", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["Իբն Սաուդը գրավեց Լահսան. Օսմանյան տիրապետության վախճանը Պարսից ծոցի ափին", "505f26d5"], "d": ["Նեջդի ամիր Աբդուլ Ազիզ բ. Սաուդը, դուրս մղելով օսմանյան կայազորը, գրավեց Լահսայի շրջանը և հաստատվեց կենտրոն Հուֆուֆում։ Կատիֆի և Ուքայրի նավամատույցների հետ միասին Ծոցի արևմտյան ափն անցավ Սաուդյան կառավարմանը. ավարտվեց Օսմանյան պետության հիսնամյա կառավարումը շրջանում։", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["Բուխարեստի պայմանագիր. Արևմտյան Թրակիան և Կավալայի ավազանը Բուլղարիայից անցան Հունաստանին", "56123a58"], "d": ["Բալկանյան երկրորդ պատերազմն ավարտվեց Բուլղարիայի և Սերբիայի, Հունաստանի ու Չեռնոգորիայի միջև ստորագրված Բուխարեստի պայմանագրով։ Առաջին պատերազմում Բուլղարիայի ձեռքն անցած Կավալայի, Դրամայի և Սերեսի ավազանն այս պայմանագրով թողնվեց Հունաստանին։ Այս պայմանագրով Տուտրականը (Թուրթուքայա) անցավ Ռումինիային։", "dd427970"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["Շաթթ ալ-Արաբի դեսանտը. Բասրայի անկումը և Իրաքի ճակատի բացումը", "c0a87d5d"], "d": ["Առաջին համաշխարհային պատերազմի սկզբում Հնդկաստանից եկած բրիտանական արշավախմբային ուժերը ափ իջան Շաթթ ալ-Արաբի գետաբերանին գտնվող Ֆավում և կարճ ժամանակում գրավեցին Բասրան։ Քաղաքի անկումը նշանակում էր Իրաքի ճակատի բացումը և Ծոցի հյուսիսային ծայրի անցումը բրիտանական վերահսկողության տակ։", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["Վրաստանը հռչակեց անկախություն. Անդրկովկասի սեյմը ցրվեց", "6c79a8c7"], "d": ["Բրեստ-Լիտովսկից հետո ստեղծված Անդրկովկասի սեյմից դուրս եկած Վրաստանը հռչակեց անկախություն, և ստեղծվեց Վրաստանի դեմոկրատական հանրապետությունը։ Քութայիսիի հետ միասին արևմտյան Վրաստանն անցավ այս նոր պետության կառավարմանը։ Այս հռչակմամբ Սուխումը, Փոթին, Զուգդիդին, Գորին, Թելավին և Դուշեթին անցան Վրաստանի դեմոկրատական հանրապետությանը։", "5500d335"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["Հռչակվեց Ադրբեջանի դեմոկրատական հանրապետությունը", "8baecec3"], "d": ["Վրաստանի անջատումից երկու օր անց հռչակվեց Ադրբեջանի դեմոկրատական հանրապետությունը. առաջին կենտրոնը դարձավ Գանձակը։ Նույն օրը Երևանում ստեղծվեց նաև Հայաստանի Հանրապետությունը, և Անդրկովկասը բաժանվեց երեք առանձին պետությունների։ Այս հռչակմամբ Շամախին, Կաբալան, Էրեշը, Շաբրանը, Սալյանը, Կուբան, Շաքին և Բարդան անցան Ադրբեջանի դեմոկրատական հանրապետությանը։", "474c35d5"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["Հալեպի գրավումը արաբական և բրիտանական ուժերի կողմից", "00efb2da"], "d": ["Պաղեստինյան ճակատի փլուզումից հետո դեպի հյուսիս առաջացող ուժերը մտան Հալեպ. քաղաքը նախ անցավ արաբական, ապա բրիտանական զորամասերի ձեռքը։ Մուդրոսի զինադադարից երեք օր առաջ տեղի ունեցած այս գրավումը փաստացի վերջ դրեց Սիրիայում Օսմանյան պետության չորսդարյա կառավարմանը։", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["Կարմիր բանակը գրավեց Ադրբեջանը. դեմոկրատական հանրապետության վախճանը", "ebbb4566"], "d": ["Կարմիր բանակը, մտնելով Ադրբեջան, ցրեց խորհրդարանն ու կառավարությունը. ավարտվեց երկամյա Ադրբեջանի դեմոկրատական հանրապետությունը։ Բաքվի նավթային ավազանը և Գանձակն այսպիսով անցան խորհրդային կառավարմանը։ Այս գրավմամբ Շամախին, Կաբալան, Էրեշը, Շաբրանը, Սալյանը, Կուբան, Շաքին և Բարդան անցան Խորհրդային Ռուսաստանի վերահսկողության տակ։", "e475b579"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["Խան Մեյսալուն. ավարտվեց Ֆեյսալի շրջանը, Սիրիան անցավ ֆրանսիական մանդատի տակ", "80a932b0"], "d": ["Բեյրութ-Դամասկոս ճանապարհի Խան Մեյսալունում ֆրանսիացիները ծանր պարտության մատնեցին սիրիական ուժերին, և վերջ գտավ Ֆեյսալի Արաբական թագավորությունը Դամասկոսում։ Ֆրանսիան փաստացի հաստատեց Սան Ռեմոյում իրեն տրված մանդատային իրավասությունը. Հալեպից Դամասկոս, Ալեքսանդրետից Դեր Զոր ձգվող շրջանը ենթարկվեց ֆրանսիական մանդատային վարչությանը։", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["Ստեղծվեց Անդրհորդանանի ամիրայությունը. Աբդուլլահ բ. Հուսեյնը հռչակեց իր ամիրությունը", "5ef520c2"], "d": ["Շերիֆ Հուսեյնի որդի Աբդուլլահը, Մաանի վրայով գալով դեպի հյուսիս, հռչակեց Անդրհորդանանի ամիրայությունը. Անգլիան կարճ ժամանակ անց այս վարչությունը ճանաչեց մանդատի շրջանակում։ Ամմանը դարձավ ամիրայության կենտրոնը, և Հորդանանի սարահարթը, ներառյալ Քարաքը, կապվեց այս նոր վարչությանը։", "113f01ba"]},
"OLAYLAR_2S0920:1941-05-03:0":{"b": ["Իտալիան Լյուբլյանայի գավառը բռնակցեց թագավորությանը. Լյուբլյանան պոկվեց Հարավսլավիայից", "c451f492"], "d": ["1941 թվականի ապրիլին Հարավսլավիայի փլուզմամբ Լյուբլյանան և Սլովենիայի արևմտյան կեսը գրաված Իտալիան 1941 թվականի մայիսի 3-ի հրամանագրով շրջանը «Լյուբլյանայի գավառ» անվամբ բռնակցեց թագավորությանը. բարձր կոմիսար դարձավ Գրացիոլին։ Լյուբլյանան դուրս եկավ Հարավսլավիայից և անցավ իտալական կառավարման տակ (մինչև 1943 թվականի սեպտեմբերը)։", "894bdb8c"]},
"OLAYLAR_2S0920:1941-05-05:0":{"b": ["Հայլե Սելասիեն վերադարձավ Ադիս Աբեբա. Հաբեշստանը անջատվեց Իտալական Արևելյան Աֆրիկայից", "42470af3"], "d": ["Այն բանից հետո, երբ անգլո-հաբեշական ուժերը ապրիլի սկզբին գրավեցին Ադիս Աբեբան, կայսր Հայլե Սելասիեն 1941 թվականի մայիսի 5-ին հաղթական վերադարձավ մայրաքաղաք. իտալական օկուպացիայի (1936-41) պաշտոնական ավարտը համարվում է այս օրը։ Ատլասն այս օրն օգտագործում է որպես Հաբեշստանի՝ Իտալական Արևելյան Աֆրիկայից վերադառնալու սահմանագիծ։", "b9c24f62"]},
"OLAYLAR_2S0920:1942-01-01:0":{"b": ["Ճապոնական ուժերը գրավեցին անպաշտպան Լաբուան կղզին. բրիտանական Մալայան (Straits Settlements) կորցրեց իր կղզին Հյուսիսային Բորնեոյում", "a946e926"], "d": ["Բորնեոյի գործողության ընթացքում ճապոնական մի փոքր ուժ ափ իջավ չպաշտպանվող Լաբուան կղզում և գրավեց այն. կղզին 1942 թվականի հունվարից մինչև 1945 թվականի սեպտեմբերը մնաց ճապոնական ռազմական օկուպացիայի տակ։ Օրն աղբյուրներում տարբերվում է՝ հունվարի 1 կամ 3 (տես ic_not)։", "f83ac693"]},
"OLAYLAR_2S0920:1955-11-23:0":{"b": ["Կոկոսյան (Քիլինգ) կղզիները հանվեցին Սինգապուրի գաղութից և փոխանցվեցին Ավստրալիային", "5c2d70c7"], "d": ["Բրիտանիայի 1955 թվականի Cocos Islands Act-ի համաձայն հրապարակված Order in Council-ի և Ավստրալիայի Cocos (Keeling) Islands Act 1955-ի հռչակագրի (Proclamation) օրը՝ 1955 թվականի նոյեմբերի 23-ին, կղզիները դադարեցին լինել Սինգապուրի գաղութի մաս և անցան Ավստրալիայի Համագործակցության իրավասության տակ։ Հոմ Այլենդը (Home Island, Կլունիս-Ռոս ընտանիքի սեփականությունը և կոկոս-մալայական բնակավայրը) այդ օրվանից հետո ավստրալական կառավարման տակ է։", "0edcf278"]},
"OLAYLAR_2S0920:1958-10-01:0":{"b": ["Սուրբ Ծննդյան կղզին Բրիտանիայից փոխանցվեց Ավստրալիային", "c971c518"], "d": ["Բրիտանիայի The Christmas Island (Transfer to Australia) Order in Council 1958-ը 1958 թվականի հոկտեմբերի 1-ին ուժի մեջ մտավ. կղզու ինքնիշխանությունը բրիտանական Սինգապուրի գաղութից անցավ Ավստրալիայի Համագործակցությանը։ Flying Fish Cove-ը կղզու բնակավայրի և նավահանգստի կենտրոնն է։", "7c935123"]},
"OLAYLAR_2S0920:1991-11-18:0":{"b": ["Վուկովարը ընկավ. ՀԺԲ-ն և սերբական զորամասերը եռամսյա պաշարումից հետո գրավեցին քաղաքը", "30db2698"], "d": ["Պաշարված Վուկովարի մնացած խորվաթ պաշտպանները 1991 թվականի նոյեմբերի 18-ին անձնատուր եղան. քաղաքն անցավ Հարավսլավիայի ժողովրդական բանակի և սերբական ուժերի ձեռքը։ Հետագայում քաղաքն անցավ ՄԱԿ-ի Արևելյան Սլավոնիայի անցումային վարչակազմի (UNTAES) ժամանակաշրջանը։", "09aa356a"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["Ղիյաս ադ-Դին Քեյխուսրևը նվաճեց Անթալիան. սելջուկները հասան Միջերկրական ծով", "9812e629"], "d": ["Լատինների՝ Կոստանդնուպոլիսը վերցնելուց հետո իտալացի Ալդոբրանդինիի ձեռքն անցած Անթալիան լատինական կառավարումից դժգոհ հույների աջակցությամբ վերցրեց Անատոլիայի սելջուկ սուլթան Ղիյաս ադ-Դին Քեյխուսրև I-ը։", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["Իզզ ադ-Դին Քեյկավուսը Անթալիան ետ վերցրեց կիպրացիներից", "ec2446f9"], "d": ["1212 թ. Կիպրոսի թագավորի աջակցությամբ կազմակերպված ապստամբության հետևանքով ձեռքից գնացած Անթալիան Իզզ ադ-Դին Քեյկավուս I-ը վերանվաճեց և կուսակալությունը դարձյալ տվեց Մուբարիզ ադ-Դին Էրթոքուշին։", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["Բայբարսը Յաֆան վերցրեց խաչակիրներից. Երուսաղեմի թագավորության իշխանությունը Յաֆայում ավարտվեց", "c7629d70"], "d": ["Մամլուք սուլթան Բայբարս I-ը վերջ դրեց Յաֆայում խաչակրաց իշխանությանը, քանդել տվեց քաղաքը. միջնաբերդի փայտն ու մարմարը ուղարկեց Կահիրեի իր մզկիթի կառուցման համար։", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["Բայբարսը վերցրեց Անտիոքը. Անտիոքի իշխանապետության վերջը", "da2b511a"], "d": ["Մամլուքյան բանակը ընդհանուր գրոհով հաղթահարեց Անտիոքի պարիսպները. 170-ամյա խաչակրաց իշխանապետությունն ավարտվեց, և Ալեքսանդրետը վերստին միացվեց իսլամական հողերին։", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["Կարամանօղուլները Կոնիան ետ վերցրին իլխաններից", "057ec073"], "d": ["Անատոլիայի իլխանական կուսակալ Դեմիրթաշի՝ Եգիպտոս փախչելուց հետո Կոնիան դարձյալ անցավ Կարամանօղուլների ձեռքը։ Քաղաքը 1350 թ. անցնելու էր Էրեթնային։", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["Կաստիլիայի թագավոր Ալֆոնսո XI-ը վերցրեց Ալխեսիրասը. քսանամսյա պաշարումից հետո մարինյան իշխանությունն ավարտվեց", "5de2a877"], "d": ["Կաստիլիայի թագավոր Ալֆոնսո XI-ի մոտ քսան ամիս տևած պաշարումից հետո 1344 թ. մարտի 21-ին սկսված բանակցությունների վերջում մարինյան տիրակալ Աբու ալ-Հասանը հայտնեց մուսուլմաններին լքել քաղաքը. մարտի 26-ին դատարկվեց Villa Nueva-ն, հաջորդ օրը՝ Villa Vieja-ն, և կաստիլիացիները ստանձնեցին քաղաքը։ Ալֆոնսո XI-ը 1344 թ. մարտի 28-ին (Ծաղկազարդ) հանդիսավոր մտավ քաղաք։ Ալխեսիրասը մինչև 1369 թ. մնաց Կաստիլիային։", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["Ստեֆան Դուշանը Սերեն վերցրեց Բյուզանդիայից", "2cc79d36"], "d": ["Բյուզանդական քաղաքացիական պատերազմից օգտվելով՝ սերբ թագավոր Ստեֆան Դուշանը գրավեց Սերեսը և քաղաքը դարձրեց Սերբական կայսրության մայրաքաղաք։", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["Ֆելդկիրխի կոմսությունը վաճառվեց Հաբսբուրգյան Ավստրիային", "fe4a0306"], "d": ["Մոնֆոր-Ֆելդկիրխ ճյուղի վերջին կոմս Ռուդոլֆը 1375 թ. իր ամբողջ տիրույթը վաճառեց Ավստրիայի դքսեր Հաբսբուրգներին. փաստացի փոխանցումն ավարտվեց նրա մահով (1390)։ Ֆելդկիրխը դարձավ Ֆորարլբերգի՝ Հաբսբուրգների ձեռքն անցած առաջին մեծ մասը։", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["Բալչիկը և Դոբրուջայի ափն անցան օսմանյան կառավարման տակ", "dfd348b9"], "d": ["Կոսովոյի հաղթանակից հետո Դոբրուջայի ափի Բալչիկն անցավ օսմանյան կառավարման տակ։ Շրջանն անմիջապես հետո գրավելու էր Վալախիայի վոևոդա Միրչան, օսմանյան իշխանությունը վերահաստատվելու էր 1393 թ.։", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["Մարաշի սեյիդները Մահանեսերում հանձնվեցին Լենկթեմուրին. Մազանդարանն անցավ Թեմուրյաններին", "125dbed8"], "d": ["Իր հնգամյա արշավանքում Մազանդարան մտած Լենկթեմուրը Կարաթողանում իր դեմ դուրս եկած մարաշիներին սեղմեց Մահանեսեր ամրոցում և ընդունեց նրանց հանձնումը։ Սարիում և Ամոլում մեծ կոտորած կատարվեց. Սարին տրվեց Քիա Աֆրասիյաբի որդի Իսկանդար Շեյխիին։", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["Շիբենիկը վերստին անցավ Վենետիկի Հանրապետության կառավարման տակ", "9b7998bf"], "d": ["Նեապոլցի Լադիսլասի՝ Դալմաթիայի նկատմամբ իր իրավունքները 1409 թ. Վենետիկին վաճառելուց հետո դիմադրած Շիբենիկը 1412 թ. վերստին անցավ վենետիկյան կառավարման տակ։ Քաղաքը մինչև 1797 թ. Հանրապետության կործանումը մնաց որպես Վենետիկի դալմաթական տիրույթ։", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["Չելեբի Մեհմեդի ջանդարյան արշավանքը. Չանկըրին տրվեց օսմանյան հովանավորության տակ գտնվող Կասիմ բեյին", "da03b919"], "d": ["Շեյխ Բեդրեդդինի՝ Վալախիա անցնելուն օգնած Ջանդարօղլու Իսֆենդիյար բեյի դեմ արշավող Չելեբի Մեհմեդը առաջացավ դեպի Կաստամոնու և պաշարեց Սինոպը, ուր քաշվել էր Իսֆենդիյարը։ Իսֆենդիյարը ճանաչեց օսմանյան գերիշխանությունը. Իլգազ լեռը ընդունվեց որպես սահման, և օսմանցիներին ապաստանած նրա որդի Կասիմ բեյին տրվեցին Չանկըրին և շրջակայքը։", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["Սմեդերևոյի գրավմամբ Հիսարջըքն (Գրոցկա) էլ անցավ Օսմանյան պետությանը", "ab724ec9"], "d": ["Երեք ամիս տևած պաշարումից հետո վերցվեց Սմեդերևոն։ Սմեդերևոյից 17 կմ հեռու Հիսարջըքը (Գրոցկա) ատլասում հետևում է իր ավագ կենտրոն Սմեդերևոյի ճակատագրին և նույն օրը Սերբական դեսպոտությունից անցնում է Օսմանյան պետությանը (1444 թ. վերադարձվելու է)։", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["Բրեգենցի կոմսության առաջին կեսը վաճառվեց Հաբսբուրգյան Ավստրիային", "3a9598db"], "d": ["Մոնֆոր-Բրեգենցի ժառանգորդ Հոխբերգյան Էլիզաբեթը 1451 թ. Բրեգենցի կոմսության կեսը վաճառեց Հաբսբուրգներին. մնացած կեսը վերցվեց 1523 թ.։ Այսպիսով Բրեգենցը դարձավ Հաբսբուրգյան Ֆորարլբերգի մաս։", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["Կորնթոսի հանձնմամբ Սիկիոնն էլ անցավ Օսմանյան պետությանը", "c7b0d22d"], "d": ["Ֆաթիհը Մորեայի արշավանքում երեք ամիս տևած պաշարումից հետո խաղաղ ճանապարհով վերցրեց Կորնթոսը։ Կորնթոսից 17 կմ հեռու Սիկիոնը ատլասում հետևում է ավագ կենտրոն Կորնթոսի ճակատագրին և նույն օրն անցնում Օսմանյան պետությանը։", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["Սմեդերևոյի հանձնմամբ Հիսարջըքն (Գրոցկա) էլ անցավ Օսմանյան պետությանը", "e3d76f5c"], "d": ["Լազար Բրանկովիչի այրի Հելենան Սմեդերևոյի ամրոցը հանձնեց օսմանցիներին. Սերբական դեսպոտությունն ավարտվեց։ Սմեդերևոյի ավագ կենտրոնության ներքո Հիսարջըքը (Գրոցկա) նույն օրն անցնում է Օսմանյան պետությանը։", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["Կաֆայի հանձնումը և Ղրիմի խանի ենթակայությունը. Չերքեզիայի ափը (Սոչի, Տուապսե, Մայկոպ) որպես թույլ հովանավորության տարածք կապվեց Ղրիմի խանությանը", "e99eb8e8"], "d": ["Չորսօրյա պաշարումից հետո Կաֆան հանձնվեց Ահմեդ փաշային, Մենգլի Գիրեյը ընդունեց օսմանյան սուլթանի գերիշխանությունը։ Ղրիմի խաներին որպես տեր ճանաչող չերքեզ ցեղերի հայրենիք Սոչիի, Տուապսեի և Մայկոպի շրջակայքը ատլասում այս ամսաթվից սկսած ցուցադրվում է որպես Ղրիմի խանությանը թույլ հովանավորությամբ կապված։", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["Մոսկվան Բրյանսկը վերցրեց Լիտվական Մեծ դքսությունից", "fb1c3a61"], "d": ["1500-1503 թթ. մոսկովա-լիտվական պատերազմում ռուսական բանակը վերցրեց Բրյանսկը, և քաղաքը միացվեց Մոսկովյան պետությանը. 1503 թ. զինադադարը ճանաչեց այս ձեռքբերումը։", "8e507991"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["Բըյըքլը Մեհմեդ փաշան Մոսուլը, Սինջարը և Ամադիան վերցրեց Սեֆյաններից", "3039d6af"], "d": ["Կոչհիսարում Կարա խանին հաղթած Բըյըքլը Մեհմեդ փաշան Մարդինը պաշարելիս շրջակա ամրոցները վերցրեց Սեֆյաններից. գրավվեցին Մոսուլը, Ուռհան, Բիրեջիքը և Սինջարը, Ամադիան և մյուս քուրդ կառավարիչները ընդունեցին օսմանյան հպատակությունը։ Իսկ Մարդինի ամրոցը հանձնվելու էր փաշայի՝ Մարջ Դաբիկից վերադարձից հետո։", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["Գուստավ Վազան Ստրենգնեսում ընտրվեց թագավոր. Շվեդիայի թագավորությունը դուրս եկավ Կալմարյան միությունից", "a6e95f4c"], "d": ["Ստոկհոլմյան արյան բաղնիքից (1520) հետո Դանիայի թագավոր Քրիստիան II-ի դեմ ապստամբած Գուստավ Էրիքսոն Վազան 1523 թ. մայիսին Ստրենգնեսում գումարված շվեդական ռիքսդագում 1523 թ. հունիսի 6-ին ընտրվեց թագավոր։ Շվեդիան և նրան ենթակա Ֆինլանդիան այսպիսով վերջնականապես դուրս եկան 1397-ից տևող Կալմարյան միությունից, և սկսվեց անկախ Շվեդական թագավորության Վազաների շրջանը։", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["Սիլեզիայի դասերը Ֆերդինանդ I-ին ճանաչեցին թագավոր. Սիլեզիան անցավ Հաբսբուրգյան Ավստրիային", "a28e10c2"], "d": ["Մոհաչում Լայոշ II-ի մահով թափուր մնացած Բոհեմիայի թագին 1526 թ. հոկտեմբերին ընտրված Հաբսբուրգ Ֆերդինանդին Վերին և Ստորին Սիլեզիայի դասերը ընդհանուր ժողովում, իրենց արտոնությունները հաստատելու պայմանով, 1526 թ. դեկտեմբերի 5-ին ճանաչեցին թագավոր, իսկ նրա կնոջը՝ Աննային, թագուհի։ Սիլեզիական դքսություններն այսպիսով Բոհեմիայի թագի հետ անցան Հաբսբուրգյան կառավարման տակ։", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["Շվեդիայի թագավոր Գուստավ Վազան հիմնեց Հելսինկին", "43468b54"], "d": ["Շվեդիայի թագավոր Գուստավ Վազան 1550 թ. Վանտաա գետի գետաբերանում, որպեսզի Ռևելի (Տալլին) հետ մրցի բալթյան առևտրում, որպես նոր առևտրական քաղաք հիմնել տվեց Հելսինկին։ Քաղաքը 1640 թ. տեղափոխվեց իր ներկայիս տեղը՝ դեպի ծով։", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["Օմանի Յարուբյան իմամ Նասիր իբն Մուրշիդը Ջուլֆարը վերցրեց Պորտուգալիայից", "6ca9fb0c"], "d": ["1622 թ. Հորմուզի անկումից հետո էլ Ջուլֆարում մնացած պորտուգալացիները դուրս հանվեցին շրջանից Օմանի Յարուբյան իմամ Նասիր իբն Մուրշիդի՝ 1633 թ. գրավմամբ։", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["Սին (Սինյ) ամրոցի կորուստը Վենետիկի օգտին. Դալմաթիայի ներքին մասը", "3af8e103"], "d": ["Մորեայի պատերազմի ժամանակ վենետիկյան ուժերը 1686 թ. օսմանցիներից վերցրին Դալմաթիայի ներքին մասի Սին (Սինյ) ամրոցը. ամրոցը դիմացավ նաև 1715 թ. օսմանյան պաշարմանը և մնաց Վենետիկին։", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["Վարադինի և Բաչի անցումը Հունգարիայի թագավորության (Հաբսբուրգյան թագ) ձեռքը. Հարշանից հետո նահանջ Բաչկայից", "6bc2b1ac"], "d": ["Հարշանի ջախջախիչ պարտությունից նահանջող Սարը Սուլեյման փաշայի բանակը 1687 թ. սեպտեմբերի 1-ին անցավ Վարադինով և ամրոցը թողեց Ջաֆեր փաշային. կարճ ժամանակ անց Վարադինը և Բաչկայի Բաչն անցան դաշնակից հաբսբուրգյան ուժերի ձեռքը։ Կառլովիցում Սավան սահման ընդունվելով՝ Վարադինը մնաց Ավստրիայի կողմում։", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["Օսիեկի անցումը Հունգարիայի թագավորության (Հաբսբուրգյան թագ) ձեռքը. սկսվեց Սլավոնիայի կորուստը", "7af97ffe"], "d": ["Հարշանի պարտությունից հետո Դրավայի վրայի Օսիեկի կամրջային ամրոցը 1687 թ. սեպտեմբերի 26-ին անցավ հաբսբուրգյան ուժերին։ Սլավոնիայում օսմանյան ռազմական ներկայությունը և թուրք բնակչությունը 1686-1688 թթ. աստիճանաբար ետ քաշվեցին. շրջանն անցավ հաբսբուրգյան կառավարման տակ։", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["Հերցեգ Նովիի կորուստը Վենետիկի օգտին. Կոտորի ծոցի մուտքը", "b88046d8"], "d": ["Մորեայի պատերազմի ժամանակ վենետիկյան նավատորմն ու նրա դաշնակիցները 1687 թ. պաշարեցին և վերցրին Կոտորի ծոցի մուտքի Հերցեգ Նովիի ամրոցը. քաղաքը մինչև 1797 թ. Վենետիկի Հանրապետության կործանումը մնաց Վենետիկին։", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["Կորսիկայի միացումը անգլիական թագին. Անգլո-կորսիկյան թագավորություն", "10f18bde"], "d": ["Հեղափոխական Ֆրանսիայի դեմ ապստամբած Պաոլին անգլիական նավատորմի աջակցությամբ կղզին մաքրեց ֆրանսիական կայազորներից. Կորտեում գումարված խորհրդաժողովը ընդունեց Կորսիկան անգլիական թագավորին կապող սահմանադրություն։ Կղզին երկու տարի որպես Անգլո-կորսիկյան թագավորություն մնաց անգլիական ընդհանուր կուսակալ Գիլբերտ Էլիոթի կառավարման տակ։", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["Անգլիացիների կողմից Կորսիկայի լքումը. կղզին դարձյալ Ֆրանսիայինն է", "c9f986fe"], "d": ["Բոնապարտի իտալական հաղթանակներով և Իսպանիայի՝ Ֆրանսիայի կողմն անցնելով Միջերկրականում նեղված Անգլիան դատարկեց Կորսիկան։ Անգլո-կորսիկյան թագավորությունն ավարտվեց, և կղզին վերստին կապվեց Ֆրանսիային։", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["Ավստրո-հունգարական բանակը, կոտրելով դիմադրությունը, վերցրեց Բիհաչը", "ffec53e0"], "d": ["Բեռլինի պայմանագրով Բոսնիա-Հերցեգովինան գրավելու իրավունք ստացած Ավստրո-Հունգարիան Բիհաչում բախվեց տեղական մուսուլմանական դիմադրության։ Գեներալ Վիլհելմ ֆոն Ռայնլենդերի հրամանատարությամբ ուժերը 1878 թ. սեպտեմբերի 18-ին վերցրին քաղաքը. Ունայի հովտի Օստրովիցայի կայազորը նույն գործողությամբ դուրս եկավ օսմանյան ձեռքից։", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["Անգլիացիները գրավեցին Սոկոտոն. Սոկոտոյի խալիֆայությունը կորցրեց մայրաքաղաքը", "e744f986"], "d": ["Հյուսիսային Նիգերիան 1900 թ. գաղութ հռչակած Անգլիայի կուսակալ Լուգարդը ամիրայությունները մեկ առ մեկ վերցնելուց հետո ծանր պարտության մատնեց Սոկոտոյի բանակը և 1903 թ. մարտի 15-ին գրավեց մայրաքաղաքը։ Փախած խալիֆ Թահիրի՝ հուլիսին Բուրմիում սպանությամբ ավարտվեց խալիֆայության քաղաքական իշխանությունը։", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["Իբն Սաուդը հաղթեց Ռաշիդյան ամիրային. Կասիմը Շամմարի ամիրայությունից անցավ Սաուդյաններին", "a32201dd"], "d": ["Էր Ռիադը 1902 թ. ետ վերցրած Աբդ ալ-Ազիզ իբն Սաուդը 1906 թ. ապրիլի 13-ին հաղթեց և սպանեց Ռաշիդյան ամիրա Աբդ ալ-Ազիզ իբն Մութիբին։ Այս ճակատամարտից հետո նա գրավեց Կասիմի շրջանը (Բուրայդա, Ունայզա). Ռաշիդյաններն այսուհետ իշխում էին միայն Հայիլում և շրջակայքում։", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["Քամարան կղզին գրավվեց անգլիացիների կողմից", "c514bb66"], "d": ["Կարմիր ծովի եմենյան ափի Քամարան կղզին Առաջին համաշխարհային պատերազմի ժամանակ 1915 թ. գրավվեց անգլիացիների կողմից և սկսեց կառավարվել Ադենից։", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["Նաբլուսի գրավումը անգլիացիների կողմից. Պաղեստինյան ճակատի փլուզումը", "b5e85950"], "d": ["1918 թ. սեպտեմբերին Ալենբիի մեծ հարձակումը պաղեստինյան ճակատում ցրեց օսմանյան 7-րդ և 8-րդ բանակները. Նաբլուսն անցավ անգլիացիների ձեռքը, և քաղաքում ավարտվեց չորսդարյա օսմանյան իշխանությունը։ Քաղաքը մինչև 1920 թ. մնաց անգլիական ռազմական կառավարման տակ։", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["Անգլիացիների մուտքը Մոսուլ. Մոսուլի վիլայեթի՝ զինադադարին հակասող գրավումը", "ed5e8e33"], "d": ["Երբ ստորագրվեց Մուդրոսի զինադադարը, Մոսուլը թուրքական ուժերի ձեռքին էր։ Անգլիացիները, հիմնվելով զինադադարի 7-րդ հոդվածի վրա, 1918 թ. նոյեմբերի 8-ին (կամ 10-ին) մտան քաղաք, և նոյեմբերի 15-ին թուրքական զորամասերը ստիպված եղան դուրս գալ վիլայեթից։ Մոսուլի հարցը Լոզանում էլ չլուծվեց և մնաց 1926 թ. Անկարայի պայմանագրին։", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["Լոզանի պայմանագիր. Պատմոսը թողնվեց Իտալիային, Էգեյան կղզիներում հաստատվեց հունական իշխանությունը", "185960b3"], "d": ["Լոզանի 15-րդ հոդվածով Թուրքիան Իտալիայի օգտին հրաժարվեց Տասներկու կղզիների (Դոդեկանես), ներառյալ Պատմոսը, նկատմամբ իր բոլոր իրավունքներից և տիտղոսներից. կղզիները 1912-ից փաստացի իտալական օկուպացիայի տակ էին։ Իսկ 12-րդ հոդվածը հաստատեց Լեմնոսի, Սամոթրակեի, Լեսբոսի, Քիոսի, Սամոսի և Իկարիայի նկատմամբ հունական իշխանությունը։ Այոս Էֆստրատիոսը (Ai Strati) և Ֆուրնին 1912-ից հունական ձեռքում էին և Լոզանից հետո էլ մնացին Հունաստանին. այս երկու անունները իրենք Լոզանի 12-րդ հոդվածում չեն թվարկվում։", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["Թունջելիի օրենք. Դերսիմի սանջակի փոխարեն ստեղծվեց Թունջելիի վիլայեթ (կենտրոնը՝ Կալան)", "1ae9ad50"], "d": ["2885 համարի օրենքով որոշվեց Դերսիմի շրջանում ստեղծել Թունջելի անունով նոր վիլայեթ. վիլայեթի վարչական կենտրոնը դարձավ Կալան բնակավայրը, և բնակավայրը հետագայում ստացավ Թունջելի անունը։ Շրջանը մնաց Թուրքիայի Հանրապետության կազմում. փոխվածը վարչական կարգավիճակն ու անունն են։", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["Մարոկկոյի անկախությունը. ֆրանսիական պրոտեկտորատն ավարտվեց, Սալեն և Ռաբաթը մնացին Մարոկկոյի թագավորությանը", "a62a3fdb"], "d": ["1956 թ. մարտի 2-ին ստորագրված անկախության պայմանագրով ավարտվեց 1912-ից տևող ֆրանսիական պրոտեկտորատը. Սալեն և Ռաբաթը դարձան անկախ Մարոկկոյի թագավորության հողը։ Իսպանիան Մարոկկոյի անկախությունը ճանաչեց 1956 թ. ապրիլի 5-ին։", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["Նոր Հեբրիդները անկախացան. հիմնվեց Վանուատուի Հանրապետությունը", "cc93330f"], "d": ["Ֆրանսիայի և Միացյալ Թագավորության համատեղ իշխանության տակ գտնվող Նոր Հեբրիդների կոնդոմինիումը 1980 թ. հուլիսի 30-ին անկախացավ Վանուատու անունով։ Էֆաթե կղզու մայրաքաղաք Պորտ-Վիլան և Թեումա բնակավայրը կոնդոմինիումի կառավարումից անցան Վանուատուին։", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["Հարավային Աֆրիկան Ուոլֆիշ Բեյը (Walvis Bay) փոխանցեց Նամիբիային", "96bb0184"], "d": ["Հարավաֆրիկյան Հանրապետությունը 1994 թ. մարտի 1-ին Ուոլֆիշ Բեյի նավահանգիստը և բաց ծովի տասներկու կղզիները փոխանցեց Նամիբիայի կառավարությանը. ութսունչորսամյա հարավաֆրիկյան վերահսկողությունն ավարտվեց։", "fdd93117"]},
"OLAYLAR_2S_0918:1284-01-01:0":{"b": ["Բելգրադն ու Մաչվան հունգարական թագավորի կողմից տրվեցին Դրագուտինին", "a4c2c535"], "d": ["1282 թ. գահից հրաժարված սերբ թագավոր Ստեֆան Դրագուտինին հունգարական թագավորը 1284 թ. տվեց Մաչվայի և Բելգրադի կառավարումը. Բելգրադը ավելի քան երեսուն տարի մնաց Դրագուտինի ձեռքին (հունգարական հպատակությամբ Սրեմի թագավորությունը)։", "2fb699cd"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["Ալանիան (Ալայիյե) սելջուկյան շրջանից հետո անցավ տեղական բեյության վերահսկողության տակ", "7b1489b3"], "d": ["1290-ականներին Անատոլիական Սելջուկյան պետության փաստացի քայքայմամբ Միջերկրական ծովի ափի Ալայիյե (Ալանիա) նավահանգիստը, անկախանալով կենտրոնական իշխանությունից, անցավ շրջանի բեյությունների (այս շրջանում Կարամանօղուլների ազդեցության գոտում) վերահսկողության տակ. ստույգ թվականը և թե որ բեյությունն էր ուղղակիորեն իշխում, աղբյուրներում պարզ չէ։", "78a4ff46"]},
"OLAYLAR_2S_0918:1319-01-01:0":{"b": ["Հունգարացիները Բելգրադը հետ վերցրին Միլուտինից", "16d254a2"], "d": ["1316 թ. Դրագուտինի մահից հետո Սերբիան ցանկացավ իր ձեռքին պահել Բելգրադը, Հունգարիան պահանջեց վերադարձը. 1319 թ. հունգարացիները հարձակվեցին, ամիսներ տևած բախումներից հետո սերբական բանակը նահանջեց, և քաղաքը ավերված վիճակում միացվեց հունգարական Մաչվայի բանությանը։ Բելգրադը, մինչև 1403-04 թվականներին Ստեֆան Լազարևիչին թողնվելը, մնաց հունգարական կառավարման տակ։", "feb8ea91"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["Սինոպը գրավեց Ղազի Չելեբին, և այն անցավ Ջանդարօղուլների ազդեցության տակ", "f107586a"], "d": ["Իլխանական տիրապետության թուլացմամբ Կաստամոնուի և Սինոպի շրջանում հզորացած Ջանդարօղլու (Իսֆենդիյարօղլու) բեյության հիմնադիր ընտանիքից Ղազի Չելեբին մոտ 1322 թ. գրավեց Սինոպը և քաղաքը դարձրեց բեյության նավահանգստային կենտրոններից մեկը։", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["Շիբենիկը, մնալով Շուբիչ կոմսերի և Վենետիկի միջև, կապվեց Վենետիկին", "99b341e0"], "d": ["Խորվաթ ավատատեր Բրիբիրցի Շուբիչ կոմսերի և Վենետիկի միջև մնացած Շիբենիկը 1322 թ. մարտի 1-ին իրեն հանձնեց Վենետիկին և մինչև 1357 թ. մնաց վենետիկյան կառավարման տակ։", "120581de"]},
"OLAYLAR_2S_0918:1322-04-17:0":{"b": ["Տրոգիրը Բրիբիրի իշխանների դեմ կապվեց Վենետիկին", "4ccf9ce4"], "d": ["Բրիբիրցի Շուբիչ կոմսերի ճնշման տակ գտնվող Տրոգիրը իր ազատությունները պահպանելու համար 1322 թ. ապրիլի 17-ին իրեն հանձնեց Վենետիկին և մինչև 1357 թ. մնաց վենետիկյան հովանու ներքո։", "e69237c1"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["Սպլիտում ավարտվեց հունգարական գերիշխանությունը. սկսվեց վենետիկյան կառավարումը", "4b04ca1a"], "d": ["Սպլիտի կոմունայում 1133 թվականից տևող հունգարական գերիշխանությունն ավարտվեց 1327 թ. սեպտեմբերի 18-ին. քաղաքը անցավ վենետիկյան կառավարման և այնտեղ մնաց մինչև 1357 թ.։", "75ef7dfc"]},
"OLAYLAR_2S_0918:1357-01-01:0":{"b": ["Սպլիտում վենետիկյան կառավարումը ավարտվեց. վերսկսվեց հունգարական տիրապետությունը", "e99628fc"], "d": ["1327 թ. Սպլիտում սկսված վենետիկյան կառավարումը ավարտվեց 1357 թ.. քաղաքը կրկին անցավ ուղղակի հունգարական տիրապետության տակ (մինչև 1420 թ.)։", "84447172"]},
"OLAYLAR_2S_0918:1357-07-09:0":{"b": ["Տրոգիրը դուրս եկավ վենետիկյան հովանուց. վերսկսվեց հունգարական տիրապետությունը", "7f112aa8"], "d": ["Տրոգիրը մինչև 1357 թ. հուլիսի 9-ը մնաց վենետիկյան հովանու և կառավարման տակ. երբ Լայոշ Անժուացին սկսեց Դալմաթիան պոկել Վենետիկից, այն դուրս եկավ այս հովանուց և վերադարձավ խորվաթ-հունգարական թագավորության գերիշխանությանը։", "6a7c7a44"]},
"OLAYLAR_2S_0918:1357-12-14:0":{"b": ["Շիբենիկը բաժանվեց Վենետիկից. անցավ հունգարական տիրապետության տակ", "adb9d6ca"], "d": ["Երբ Լայոշ Անժուացին Դալմաթիան պոկում էր Վենետիկից, Շիբենիկը 1357 թ. դեկտեմբերի 14-ին բաժանվեց Վենետիկից և անցավ հունգարական տիրապետության տակ։", "7af69a3b"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["Զադարի պայմանագիրը. Դուբրովնիկը Վենետիկից անցավ հունգարական հովանու ներքո", "57fb81f9"], "d": ["1358 թ. փետրվարի 18-ին ստորագրված Զադարի պայմանագիրը վերջ դրեց Դալմաթիայի նկատմամբ Վենետիկի 150-ամյա տիրապետությանը. Դուբրովնիկը (Ռագուզա) այսպիսով, դուրս գալով վենետիկյան կառավարումից, ձեռք բերեց կիսանկախ հանրապետության կարգավիճակ՝ անցնելով հունգարական թագավոր Լայոշ I-ի հովանու ներքո։", "e207c893"]},
"OLAYLAR_2S_0918:1358-05-27:0":{"b": ["Վիշեգրադի արտոնագիրը. Դուբրովնիկը կապվեց հունգարական թագավոր Լայոշ I-ին", "9d3d02a8"], "d": ["Երբ Զադարի խաղաղությամբ (1358 թ. փետրվար) Վենետիկը հրաժարվեց Դալմաթիայի նկատմամբ իր իրավունքներից, Դուբրովնիկը թագավոր Լայոշ I-ի հետ առանձին բանակցեց. 1358 թ. մայիսին Վիշեգրադի արտոնագրով կապվեց հունգարական թագին (պաշտպանության դիմաց հավատարմություն, տարեկան խարաջ և զինվոր)։", "d37ccc8a"]},
"OLAYLAR_2S_0918:1390-06-01:0":{"b": ["Տվրտկո I-ը ստացավ Դալմաթիայի ափամերձ քաղաքների (ներառյալ Շիբենիկը) տիրապետությունը", "c53aad4d"], "d": ["Բոսնիայի թագավոր Տվրտկո I-ը 1390 թ. ստացավ Դալմաթիայի ափամերձ քաղաքների տիրապետությունը՝ բացի Զադարից. Շիբենիկն էլ, դուրս գալով հունգարական տիրապետությունից, ճանաչեց բոսնիական թագավորի գերիշխանությունը։", "dfb86467"]},
"OLAYLAR_2S_0918:1391-01-01:0":{"b": ["Տվրտկո I-ի մահը. Շիբենիկը վերադարձավ հունգարական տիրապետության", "ef2d3b2f"], "d": ["1391 թ. Բոսնիայի թագավոր Տվրտկո I-ի մահով Շիբենիկի նկատմամբ բոսնիական գերիշխանությունն ավարտվեց. քաղաքն անցավ հունգարական թագավոր Սիգիզմունդի տիրապետության տակ (1391-1402)։", "0f8c4ab3"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["Էրզրումի և Աշկալեի շրջանը ձեռքից ձեռք անցավ Կարա Կոյունլու-թեմուրյան մրցակցության մեջ", "ca64775a"], "d": ["1405 թ. Թեմուրի մահից հետո առաջացած իշխանության դատարկության պայմաններում Կարա Կոյունլու տիրակալ Կարա Յուսուֆը 1406-1408 թվականներին գործի անցավ Արևելյան Անատոլիայի թեմուրյան կուսակալների դեմ. Էրզրումը և շրջակա Աշկալեն այս պայքարում դուրս գալով թեմուրյան վերահսկողությունից՝ անցան Կարա Կոյունլուների ազդեցության տակ։", "10b1b07c"]},
"OLAYLAR_2S_0918:1409-07-31:0":{"b": ["Զադարն անցավ վենետիկյան կառավարման. Santa Intrada", "820c9276"], "d": ["Նեապոլի թագավոր Լադիսլասի՝ Դալմաթիան Վենետիկին վաճառելուց հետո Զադարի բնակչությունը նեապոլիտանական զինվորներին դուրս արեց քաղաքից. 1409 թ. հուլիսի 31-ին վենետիկյան պրովեդիտորները մտան քաղաք և հաստատեցին վենետիկյան կառավարումը, որը տևելու էր մինչև 1797 թ.։", "06e4d6fa"]},
"OLAYLAR_2S_0918:1420-06-22:0":{"b": ["Տրոգիրը անցավ վենետիկյան կառավարման", "fbca501f"], "d": ["Վենետիկի՝ Հունգարիայի դեմ պատերազմի ժամանակ, գլխավոր նավապետ Պիերո Լորեդանի նավատորմի ժամանումով 1420 թ. հունիսի 22-ին Տրոգիրը անցավ վենետիկյան կառավարման. Դալմաթիայի քաղաքներից վերջինը Վենետիկին միացած այս քաղաքը մինչև 1797 թ. մնաց վենետիկյան դրոշի ներքո։", "8ebaf8eb"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["Ակ Կոյունլու Ուզուն Հասանը վերացրեց Հիսն Քեյֆայի Էյյուբյան ճյուղը", "2b464a1f"], "d": ["Վերին Տիգրիսում Էյյուբյան հարստության՝ Համայի հետ միասին կանգուն մնացած վերջին երկու ճյուղերից մեկը՝ Հիսն Քեյֆան (Հասանքեյֆ) և Սղերդը, 1462 թ. Ակ Կոյունլու տիրակալ Ուզուն Հասանի կողմից բռնակցվելով՝ վերջ դրվեց Էյյուբյան տիրապետությանը։", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["Պորտուգալիան ամբողջացրեց իր տիրապետությունը Որմուզի նեղուցի ափերին", "bef031f0"], "d": ["Աֆոնսու դե Ալբուկերկեի 1507 թ. սկսած Պարսից ծոցի արշավանքը 1515 թ. ավարտվեց այնպես, որ ընդգրկեց Որմուզ կղզին և հանդիպակաց ափի Քեշմն ու Բուրայմին. Իրանին ենթակա Որմուզի թագավորությունը փաստացի անցավ պորտուգալական հովանու ներքո, և Պորտուգալիան տիրեց ծոցի առևտրի վերահսկողությանը։", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["Լյուբլինի ունիան. ուկրաինական հողերը Լիտվայից անցան Լեհաստանին", "1881ceff"], "d": ["1569 թ. հուլիսի 1-ին ստորագրված Լյուբլինի ունիան Լիտվայի Մեծ դքսությունն ու Լեհաստանի թագավորությունը միավորեց մեկ պետության մեջ (Rzeczpospolita)։ Համաձայնագրի պայմանով Պոդոլիան, Վոլինիան և Կիևի շրջանը (ներառյալ Բարը, Բերդիչևը, Բելոստոկը, Բրացլավը) վարչականորեն Լիտվայից ուղղակիորեն փոխանցվեցին Լեհաստանի թագավորությանը։", "184b03dd"]},
"OLAYLAR_2S_0918:1776-02-14:0":{"b": ["Ֆիումեի կառավարումը փոխանցվեց հունգարական թագին կապված Խորվաթիային", "dfedccf8"], "d": ["Կայսրուհի Մարիա Թերեզան 1776 թ. փետրվարի 14-ի ֆիրմանով Ֆիումեի կառավարումը Զագրեբի խորհրդի միջոցով տվեց Հունգարիային. 1779 թ. դիպլոմը քաղաքը դարձրեց հունգարական թագին ուղղակիորեն կապված առանձին մարմին (corpus separatum)։", "bbf160dd"]},
"OLAYLAR_2S_0918:1809-10-14:0":{"b": ["Ֆիումեն Շյոնբրունի խաղաղությամբ հանձնվեց Ֆրանսիային (Իլիրական նահանգներ)", "16bf1fca"], "d": ["1809 թ. հոկտեմբերի 14-ի Շյոնբրունի խաղաղությամբ Ֆիումեն Ավստրիայից անցավ Ֆրանսիային և մինչև 1813 թ. Նապոլեոնի Իլիրական նահանգների մաս էր։", "417a8ae7"]},
"OLAYLAR_2S_0918:1813-01-01:0":{"b": ["Ֆիումեի վերադարձը ֆրանսիական իլիրիական կառավարումից Հաբսբուրգներին", "1b5b9954"], "d": ["1813 թ., Ռուսաստանում Նապոլեոնի պարտությունից հետո, Ֆիումեն դուրս եկավ Իլիրական նահանգներից և վերադարձավ Ավստրիական կայսրությանը։", "5db16c92"]},
"OLAYLAR_2S_0918:1822-10-15:0":{"b": ["Ֆիումեն վերադարձվեց Հունգարական թագավորությանը", "aafdd0ee"], "d": ["Ֆրանց I-ի 1822 թ. հուլիսի 5-ի որոշումից հետո կոմս Դյորդ Մայլատը հունգարական կառավարության անունից 1822 թ. հոկտեմբերի 15-ին ստացավ քաղաքը. Ֆիումեն վերադարձավ Հունգարական թագավորությանը։", "e30af380"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["Եգիպտական ուժերը դուրս եկան Ահսայի (Լահսա) շրջանից", "5ea75c8d"], "d": ["Մեհմեդ Ալի փաշայի եգիպտական ուժերը 1836 թ. գրավել էին Նեջդը և արևելյան Արաբիան (ներառյալ Ահսան, Կատիֆը, Ուքայրը, Ջուբայլը). երբ 1840 թ. Լոնդոնի նեղուցների կոնվենցիան Եգիպտոսին ստիպեց հրաժարվել Արաբական թերակղզու նվաճումներից, ուժերը 1841 թ. դուրս եկան շրջանից, և կառավարումը վերադարձավ տեղական ուժերին (Սաուդյան/Ալ Խալիֆայի ազդեցություն)։", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["Ակ-Մեչեթի բերդը վերցրին ռուսական ուժերը. Կոկանդի խանության Սիր Դարիայի գիծը փլուզվեց", "e9f9a9c7"], "d": ["Գեներալ Վասիլի Պերովսկու հրամանատարությամբ ռուսական ուժերը 1853 թ. հուլիսին երկարատև պաշարումից հետո գրավեցին Կոկանդի խանությանը պատկանող Սիր Դարիայի ափի Ակ-Մեչեթի բերդը. բերդը հետագայում Պերովսկ անունով դարձավ ռուսական Թուրքեստանի առաջավոր պահակակետը։", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["Գյոք-Թեփեի ճակատամարտը. Ախալ-թեքե թուրքմենները պարտվեցին Ռուսաստանին", "76c7a102"], "d": ["Գեներալ Միխայիլ Սկոբելևի հրամանատարությամբ ռուսական ուժերը 1881 թ. հունվարի 24-ին վերցնելով Գյոք-Թեփեի (Գեոկ-Թեփե) բերդը՝ կոտրեցին Ախալ-թեքե թուրքմենների դիմադրությունը. Դահիստանի հարթավայրը, Աբիվերդը և Նեսան ներառող անդրկասպյան թուրքմենական շրջանը մտավ Ռուսական կայսրությանը միանալու ընթացքի մեջ (Անդրկասպյան մարզը հիմնվեց 1881 թ.)։ Այս իրադարձությամբ Կիզիլ-Արվատը և Աշխաբադը (Ախալի թուրքմենական հողերը) անցան Ռուսաստանին։", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["Հռչակվեց Ռումինիայի թագավորությունը. իշխանապետությունը դարձավ թագավորություն", "4d413f0c"], "d": ["1877-78 թթ. ռուս-թուրքական պատերազմից հետո Բեռլինի վեհաժողովում անկախությունը ճանաչված Ռումինիայի իշխանապետությունը 1881 թ. մարտի 26-ին (հուլյան օրացույցով մարտի 14) թագավոր Կարոլ I-ի թագադրմամբ վերածվեց թագավորության. ողջ երկիրը՝ Բաբադագը, Բիրլադը, Բուզաուն և մայրաքաղաք Բուխարեստը ներառյալ, վարչականորեն դարձավ նոր թագավորության մաս։ Թագավորության հռչակմամբ ողջ Ռումինիան (Յասսի, Գալաց, Բրեյիլա, Կոնստանցա, Տուլչա, Կալաֆատ և մյուս քաղաքները) դարձավ Ռումինիայի թագավորություն։", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["Իտալիան բռնակցեց Էրիթրեայի սարահարթը՝ ներառյալ Ասմարան և Կերենը", "31308dc8"], "d": ["Օգտվելով Եթովպիայի կայսր Հովհաննես II-ի 1889 թ. մահով առաջացած իշխանության դատարկությունից՝ Իտալիան, Ուչչալիի (Վուչալե) պայմանագրից (1889 թ. մայիսի 2) հետո, փաստացի բռնակցեց Էրիթրեայի սարահարթը՝ ներառյալ Ասմարան և Կերենը. 1890 թ. հունվարի 1-ին պաշտոնապես հռչակվեց «Էրիթրեա» անունով գաղութ։ Այս իրադարձությամբ Կերենը անցավ իտալական կառավարման։", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["Քենիայի հյուսիս-արևելյան շրջանը (Գարիսսա-Մարսաբիտ գիծ) միացվեց Բրիտանական Արևելյան Աֆրիկայի պրոտեկտորատին", "e45c6d43"], "d": ["Բրիտանական Արևելյան Աֆրիկայի ընկերության արտոնությունը 1895 թ. թագավորությանը փոխանցելով հիմնված Բրիտանական Արևելյան Աֆրիկայի պրոտեկտորատը ընդարձակվեց այնպես, որ ընդգրկեց նաև Գարիսսայի, Կիտուիի, Մարսաբիտի և Վաջիրի (Wajir) նման հյուսիս-արևելյան շրջանները. այս ներքին շրջանները փաստացի կառավարման տակ առնելը տարածվեց 1890-ականների երկրորդ կեսի վրա։", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["Իլորինի ամիրայությունը գրավվեց Թագավորական Նիգերի ընկերության ուժերի կողմից", "b111cb7d"], "d": ["Սոկոտոյի խալիֆայությանը ենթակա Իլորինի ամիրայությունը գրավվեց սըր Ջորջ Գոլդիի հրամանատարությամբ Թագավորական Նիգերի ընկերության ուժերի 1897 թ. փետրվարի արշավանքում. ամիրայության ռազմական ուժը կոտրվեց, և շրջանը փաստացի անցավ անգլիական ազդեցության տակ (պաշտոնական բռնակցումը ավարտվեց 1900 թ. Հյուսիսային Նիգերիայի պրոտեկտորատի հիմնմամբ)։", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["Բունյորոյի թագավոր Կաբալեգան գերի ընկավ, թագավորությունը կապվեց Բրիտանական Ուգանդայի պրոտեկտորատին", "62bc7c64"], "d": ["1894 թվականից անգլիական ուժերին դիմադրող Բունյորոյի թագավոր Կաբալեգան 1899 թ. ապրիլի 9-ին ձերբակալվեց Լանգո շրջանում (Դոկոլոյի մոտ) և աքսորվեց Սեյշելյան կղզիներ. թագավորության հողերը, ներառյալ մայրաքաղաք Հոյիման և Մասինդին, միացան Բրիտանական Ուգանդայի պրոտեկտորատին։", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["Տորոյի պայմանագիրը. Տորոյի թագավորությունը դարձավ Բրիտանական Ուգանդայի պրոտեկտորատի ինքնավար մաս", "c55340a2"], "d": ["1899 թ. Բունյորոյի անկումից հետո հարևան Տորոյի թագավորությունը 1896 թվականից տևող անգլիական հովանավորությունը պաշտոնականացրեց 1900 թ. Ուգանդայի համաձայնագրի շրջանակում. թագավորությունը, ներառյալ մայրաքաղաք Ֆորտ Պորտալը, ստացավ ինքնավար տեղական կառավարման կարգավիճակ Բրիտանական Ուգանդայի պրոտեկտորատի ներսում։", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["Ադամավայի ամիրայությունը բաժանվեց Գերմանիայի և Անգլիայի միջև", "b9230d3d"], "d": ["Սոկոտոյի խալիֆայությանը ենթակա Ադամավայի (Ֆոմբինա) ամիրայությունը, գերմանական և անգլիական գաղութային ուժերի 1899-1901 թվականների արշավանքների արդյունքում, բաժանվեց երկու մասի. արևելյան հատվածը (ներառյալ Գարուան, Բանյոն, Մարուան, Նգաունդերեն) միացավ գերմանական Կամերունին, արևմտյան հատվածը (մայրաքաղաք Յոլա)՝ անգլիական Հյուսիսային Նիգերիային. էմիր Զուբեյրին աքսորեցին։ Այս իրադարձությամբ Ռեյ Բուբան (Ադամավա (գերմանական բաժին)) անցավ գերմանական Կամերունի կառավարման։", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["Թիթի ճակատամարտը. Ահագգարի տուարեգները պարտվեցին ֆրանսիական ուժերին", "831143d6"], "d": ["Կոտենեստի արշավանքի ժամանակ 1902 թ. մայիսի 7-ին Թիթի օազիսի մոտ տեղի ունեցած ճակատամարտում ֆրանսիական ուժերը վճռական պարտության մատնեցին Քել Ահագգար տուարեգներին. Ահագգարի կենտրոն Աբալեսան և Իդելեսը ներառող Սահարայի այս ներքին շրջանը անցավ Ֆրանսիական Ալժիրի վերահսկողության տակ։", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["Ֆրանսիական ուժերը գրավեցին Ուբանգի-Շարիի ներքին շրջանները (Բամբարի-Բրիա գիծ)", "0b9a9f72"], "d": ["Ֆրանսիական Կոնգոյի հյուսիսային արշավանքները 1900-ականների սկզբին փաստացի վերահսկողության տակ առան Բամբարին, Բատանգաֆոն, Բոսանգոան և Բրիան ներառող Ուբանգի-Շարիի ներքին շրջանը. շրջանը 1903 թ. դեկտեմբերի 29-ին պաշտոնապես կազմավորվեց որպես Ուբանգի-Շարի գաղութ (Ֆրանսիական Հասարակածային Աֆրիկայի մաս)։", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["Սուլթան Մուհամմեդ աս-Սենուսիի Դար ալ-Կուտի սուլթանությունը վերացվեց ֆրանսիական ուժերի կողմից", "644b2c3f"], "d": ["1897 թ. ֆրանսիական հովանու ներքո անցած, Նդելե մայրաքաղաքով, ստրկավաճառության վրա հիմնված Դար ալ-Կուտիի սուլթանությունը, քանի որ սուլթան Մուհամմեդ աս-Սենուսին շարունակում էր դիմադրել ֆրանսիական իշխանությանը, 1911 թ. կազմակերպված արշավանքով փաստացի վերացվեց. Սենուսին սպանվեց կռվում, սուլթանությունը պաշտոնապես վերացվեց 1912 թ.։", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["Լիվոնյան օրդենը Կլայպեդայի (Մեմել) հողերը փոխանցեց Տևտոնական օրդենի պրուսական ճյուղին", "e61e5d50"], "d": ["Լիվոնյան օրդենը Նեմանի գետաբերանի Կլայպեդայի (Մեմել) բերդը և շրջակա իր հողերը թողեց Տևտոնական օրդենի պրուսական ճյուղին. Կուրլանդիայի եպիսկոպոսը նույնպես իր բաժինը 1392 թ. փոխանցեց նույն ճյուղին։ Կլայպեդան 1411 թ. Տորունի և 1422 թ. Մելնոյի խաղաղություններով մնաց օրդենին, 1525 թ. անցավ Պրուսիայի դքսությանը։", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["Ումուր բեյը ջենովացիներից վերցրեց Իզմիրի նավահանգստի բերդը", "ab92d96e"], "d": ["Այդընօղլու Ումուր բեյը երկուսուկես տարի պաշարեց Իզմիրի՝ լատինների ձեռքում մնացած նավահանգստի բերդը։ Բերդի ջենովացի կառավարիչ Մարտինո Ձակկարիան, հանձնելով բերդը, գնաց Քիոս։", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["Սութայյաններից Իբրահիմ շահը տիրեց Դիարբեքիրին", "179196cf"], "d": ["Իլխանության փլուզումից հետո Ջելայիրյանների և Չոբանյանների միջև պայքարի թատերաբեմ դարձած Դիարբեքիրի շրջանին տիրեց Սութայյաններից Իբրահիմ շահը. նրա իշխանությունը տևեց մինչև 1353 թ.։", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["Բերաթը Բյուզանդիայից անցավ սերբերի ձեռքը. Ստեֆան Դուշանի ալբանական նվաճումը", "1eba202e"], "d": ["1281 թ. անժուական պաշարումը ճեղքած և այդ թվականից Ադրիատիկում Բյուզանդիայի վերջին նահանգի կենտրոն եղած Բերաթի բերդը բյուզանդական քաղաքացիական պատերազմի ընթացքում, Ստեֆան Դուշանի՝ Ալբանիայում առաջխաղացման ժամանակ, անցավ սերբերի ձեռքը։ 1343 թ. մայիսին կամ հունիսին Կրույայի հանձնվելուց հետո Բերաթը, Կանինան և Ավլոնիան երկու տարվա ընթացքում դարձան սերբական. նահանգի գլուխ բերվեց Դուշանի կնոջ եղբայր Հովհաննես Կոմնենոս Ասենը։", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["Աբդ ալ-Վադյանները (Զայյանյանները) Թլեմսենում ազատվեցին Մարինյան տիրապետությունից", "a4aa9573"], "d": ["Թլեմսենի Աբդ ալ-Վադյանները Օսման II-ի և նրա եղբոր՝ Աբու Սաբիթի առաջնորդությամբ ազատվեցին Մարինյանների տիրապետությունից։ Այս անկախությունը կարճ տևեց։", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["Բայրամ խոջան ձեռք բերեց անկախություն. Կարա Կոյունլու բեյության ծնունդը", "37964815"], "d": ["Կարա Կոյունլուների առաջին բեյը համարվող Բայրամ խոջան, սպանելով Սութայյանների տիրակալ Աքչասաքալ Հուսեյն բեյին, ձեռք բերեց անկախություն։ Վերցրեց Մոսուլը և նրա կառավարումը տվեց իր եղբոր՝ Բիրդի խոջային։", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["Իբրահիմ շահի մահով Դիարբեքիրն անցավ Ջելայիրյանների կառավարման", "11c338ef"], "d": ["1343 թվականից Դիարբեքիրի շրջանին տիրող Սութայօղլու Իբրահիմ շահի մահից հետո շրջանը անցավ Ջելայիրյանների կառավարման։", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["Էնեզն անցավ ջենովական կառավարման (Գատիլյուզի ընտանիք)", "5dc12940"], "d": ["Բյուզանդական շրջանում կարևոր նավահանգստային քաղաք եղած Էնեզը 1355 թ. անցավ ջենովական կառավարման և կառավարվեց Գատիլյուզի ընտանիքի կողմից։", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["Լիտվայի մեծ իշխան Ալգիրդասը (Օլգերդ) վերցրեց Բրյանսկը", "3cad9caf"], "d": ["Լիտվայի մեծ իշխան Ալգիրդասի բանակը վերցրեց Բրյանսկը։ Քաղաքը մինչև 1500 թ. մնաց Լիտվայի Մեծ դքսությանը կապված։", "03107c6d"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["Ինանչօղուլները ճանաչեցին Գերմիյանօղուլների գերիշխանությունը", "0679db27"], "d": ["Դենիզլիի շրջակայքում իշխող Ինանչօղուլների բեյությունը, հավանաբար 1368 թ., ճանաչեց Գերմիյանօղուլների գերիշխանությունը։", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["Սալոնիկի դեսպոտ Մանուելը Սերեսի և Դրամայի շրջանը վերցրեց բյուզանդական կառավարման", "abb99c3e"], "d": ["Չիրմենում (1371 թ. սեպտեմբերի 26) թագավոր Վուկաշինի և Սերեսի դեսպոտ Ուգլեշայի մահով Սերեսի շրջանում սերբական կառավարումն ավարտվեց։ Սալոնիկում իշխող բյուզանդական արքայազն Մանուել II Պալեոլոգոսը 1371 թ. նոյեմբերին Սերեսը և Դրաման ներառող շրջանը վերցրեց բյուզանդական կառավարման։ Շրջանը 1383 թ. սեպտեմբերին անցավ օսմանցիներին։", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["Փիր Հուսեյն բեյի մահով Երզնկան և Բայբուրթն անցան Մութահհարթենին", "3269e55d"], "d": ["Երզնկայի էմիր Փիր Հուսեյն բեյի մահից հետո Երզնկան և Բայբուրթն անցան Էրեթնայի էմիրներից Մութահհարթենի ձեռքը. Մութահհարթենը դարձավ Երզնկայի էմիր։", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["Թաջեդդին բեյը Նիկսարում ջախջախեց Էրեթնայի բանակը և սկսեց անկախ գործել", "42982ea7"], "d": ["1379 թ. գարնանը Նիկսարի վրա հարձակված Կադի Բուրհանեդդինի և Էրեթնայի բեյ Ալաեդդին Ալիի ուժերը ջախջախեց Թաջեդդին բեյը։ Նա դադարեց հարկ վճարել Էրեթնայի բեյությանը և հիջ. 781 (1379) թվականից սկսած անկախ գործեց։", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["Թեմուրը վերջնականապես գրավեց Խորեզմը", "ef76d2c9"], "d": ["Թեմուրը 1371 թ. Խորեզմի առաջին արշավանքից հետո կազմակերպեց ևս երեք արշավանք։ 1379 թ. արշավանքում վերջնականապես գրավեց շրջանը, թալանեց այն և վերադարձավ առատ ավարով։", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["Բոսնիայի թագավոր Տվրտկո I-ը հիմնեց Հերցեգ Նովին", "1628221a"], "d": ["Բոսնիայի թագավոր Տվրտկո I-ը, որպեսզի աղի առևտրում Դուբրովնիկին մրցակից լինի, Տոպլա ծովախորշում հիմնեց նոր ավան. այն հետագայում հիշատակվեց Նովի (Հերցեգ Նովի) անունով։", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["Թեմուրը Ղանդահարը վերցրեց Քարթիներից և տվեց իր թոռ Փիր Մուհամմեդին", "84760f70"], "d": ["1281 թվականից իլխանների վասալ Հերաթի Քարթիների ձեռքում գտնվող Ղանդահարը Թեմուրի խորասանյան արշավանքների ժամանակ գրավվեց և տրվեց նրա թոռ Փիր Մուհամմեդին. այնուհետև քաղաքը կառավարվեց թեմուրյան կուսակալների կողմից։", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["Դուլկադիրօղլու Խալիլ բեյը Էլբիսթանը հետ վերցրեց մամլուքներից", "ee3da686"], "d": ["1381 թ. մամլուքների ձեռքն անցած Էլբիսթանը 1384 թ. Դուլկադիրօղլու Խալիլ բեյը հետ վերցրեց։", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["Թեմուրը գրավեց և թալանեց Դիարբեքիրը (Ամիդ)", "f8d200a8"], "d": ["1394 թ. ապրիլի 25-ին կամ 26-ին Թեմուրը գրավեց Դիարբեքիրը և թալանեց քաղաքը։", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["Գերարդո Ապիանին Պիզան թողեց Վիսկոնտիին և հիմնեց Պյոմբինոյի սինյորիան", "ac45a9dd"], "d": ["Պիզայի սինյոր Գերարդո Ապիանին քաղաքը 200.000 ֆլորինով թողեց Միլանի տիրակալ Ջան Գալեացցո Վիսկոնտիին։ Իր համար առանձնացրեց Պյոմբինոյի սինյորիան, որը կազմված էր Պյոմբինոյից, Սուվերետոյից, Սկարլինոյից և Էլբա, Պիանոզա ու Մոնտեքրիստո կղզիներից։", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["Դիարբեքիրը տրվեց Կարայուլուք Օսման բեյին. սկսվեց Ակ Կոյունլուների տիրապետությունը", "38262401"], "d": ["Թեմուրի 1394 թ. գրաված Դիարբեքիրը 1401 թ. տրվեց Կարայուլուք Օսման բեյին, և այսպիսով շրջանում սկսվեց Ակ Կոյունլուների տիրապետությունը։", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["Երզնկան անցավ Կարա Կոյունլուների տիրապետության տակ", "5729a50b"], "d": ["Մութահհարթենից հետո Երզնկան անցավ Կարա Կոյունլու տիրակալ Կարա Յուսուֆի ձեռքը։ Կարա Յուսուֆը քաղաքի կուսակալ նախ նշանակեց իր վստահելի մարդկանցից Փիր Օմերին։", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["Ասքիա Մուհամմեդը վերցրեց Զաղան (Դիա)", "24561a8c"], "d": ["Սոնգայի գահ բարձրացած Ասքիա Մուհամմեդը հիջ. 899 թ. վերջում իր եղբոր՝ Կուրմինա-Ֆարի Ամար Կոմձաղոյի միջոցով գրավեց Նիգերի ներքին դելտայից արևմուտք գտնվող Զաղա (Դիա) քաղաքը։", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["Շեյբանի խանը վերցրեց Բուխարան և Սամարղանդը", "8f8f40eb"], "d": ["Մուհամմեդ Շեյբանի խանը, օգտվելով թեմուրյանների միջև խառնակությունից, վերցրեց Բուխարան և Սամարղանդը և հիմնեց Շեյբանյանների (ուզբեկների) հարստությունը։ 1500-1507 թվականներին գրավեց Մավերանահրի, Խորեզմի և Խորասանի գրեթե բոլոր քաղաքները։", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["Իսպանացիները գրավեցին Բեջայան", "8faa0133"], "d": ["Նավերով ժամանած 8000 հոգանոց իսպանական բանակը գրավեց Բեջայան. քաղաքի բնակչությունը, խուճապի մատնվելով, լքեց իր հայրենի օջախը։", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["Ագադեզը կապվեց Սոնգային", "997362b0"], "d": ["Այր շրջանի կենտրոն Ագադեզը սոնգայի սուլթան Ասքիա Մուհամմեդը կապեց Գաոյին. քաղաքը այս ենթակայությունը կրեց մինչև 1591 թ. Տոնդիբիում Սոնգայի կործանումը։", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["Հիմնվեց Բագիրմիի սուլթանությունը", "03829f94"], "d": ["Կենգա ցեղը Բիրնի Բեսիի առաջնորդությամբ Չադ լճից արևելք ստեղծեց Մասինյա (Մասենյա) կենտրոնով ուժեղ պետություն։ Բագիրմիի հարստության հիմնումը ավանդաբար թվագրվում է 1522 թ.։", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["Մահացավ Սֆորցաների վերջին դուքսը, Միլանն անցավ Կարլոս V-ին", "53230b5c"], "d": ["Միլանի դուքս Ֆրանչեսկո II Սֆորցան 1535 թ. նոյեմբերի 1-2-ի գիշերը մահացավ անզավակ։ Դքսությունը անցավ կայսր Կարլոս V-ին և սկսեց կառավարվել իսպանացի կուսակալի միջոցով։", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["Ջենովացիները հաստատվեցին Թաբարկա կղզում", "0cb474f8"], "d": ["Կարլոս V-ի՝ Թունիսի տիրակալի հետ կնքած, ափին բերդ կառուցելը և մարջանի որսը թույլատրող պայմանագրի հիման վրա Պելլիից ջենովական մի համայնք բնակեցվեց Թաբարկա կղզում։ Կղզին դարձավ Լոմելլինի ընտանիքի կառավարած առևտրական հենակետ։", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["Հումայունի մահից հետո սեֆյանները Ղանդահարը վերցրին Մեծ մողոլներից", "318eabc8"], "d": ["1556 թ. Դելիում Հումայունի մահից հետո շահ Թահմասպը օգտվեց Ղանդահարի և Զամինդավարի մեծմողոլական կուսակալների միջև վեճից. Զամինդավարի կուսակալի հրավերով ժամանած սեֆյան մի ջոկատ մտավ Ղանդահար, և Թահմասպը իր հորեղբորորդի սուլթան Հուսեյն Միրզային քաղաքի կուսակալ նշանակեց։ Քաղաքը մինչև 1595 թ. մնաց սեֆյան ձեռքին։", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["Ռուսաստանը ներխուժեց Լիվոնիա, Դորպատն ընկավ", "dcb46a8a"], "d": ["Իվան IV-ը, Բալթիկ ելք ստանալու համար ներխուժելով Լիվոնիա, սկսեց Լիվոնյան պատերազմը. գրավեց Նարվան և Դորպատը (Տարտու) և պաշարեց Ռևելը։", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["Հիմնվեց Կառլովացի բերդը", "9b28e6ad"], "d": ["Խորվաթիան և Ավստրիայի ժառանգական հողերը օսմանցիներից պաշտպանելու համար Կուպա և Կորանա գետերի միջև ընկած ողողատ տարածքում հիմնվեց Կառլովացի բերդը. բերդը կառուցել տվեց Խորվաթիայի ռազմական սահմանի հրամանատար էրցհերցոգ Կարլ II-ը։", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["Զամոշչի հիմնադրման (լոկացիայի) վկայագիրը", "e1157f3b"], "d": ["Լեհաստանի մեծ կանցլեր Յան Զամոյսկին տվեց Զամոշչ քաղաքի հիմնադրման (լոկացիայի) վկայագիրը։", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["Յամ Զապոլսկու զինադադարը. Լիվոնիան և Դորպատը անցան Լեհաստանին", "7d02d8ad"], "d": ["Լեհաստան-Լիտվայի և Ռուսաստանի միջև ստորագրվեց Յամ Զապոլսկու զինադադարը. Մոսկվան հրաժարվեց Լիվոնիայի նկատմամբ իր հավակնություններից և վերադարձրեց Պոլոցկի հողերը։ Դորպատը (Տարտու) 1582 թվականից մնաց Լեհաստանի ձեռքին։", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["Ցարիցինի բերդը առաջին անգամ հիշատակվեց փաստաթղթում", "ddf65b06"], "d": ["Ցար Ֆյոդոր Իվանովիչի 1589 թ. հուլիսի 2-ի ֆիրմանը հիշատակում է Վոլգայի հարավային սահմանը պաշտպանելու համար հիմնված Ցարիցինի բերդը. այս թվականը ընդունված է քաղաքի հիմնադրման օր։", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["Հիմնվեց Սարատովի բերդը", "a3ca702c"], "d": ["Սարատովը, Վոլգայի ճանապարհը և պետության արևելյան սահմանները քոչվորների ասպատակություններից պաշտպանելու համար, իշխան Զասեկինը հիմնեց որպես բերդ-պահակակետ։", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["Հիմնվեց Պելիմի բերդը", "baf3e7eb"], "d": ["Վոյեվոդ Պյոտր Գորչակովը Տավդա գետի ափին հիմնեց Պելիմը. բերդը դարձավ Արևմտյան Սիբիրում ռուսական առաջխաղացման հենակետերից մեկը։", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["Հիմնվեց Վերխոտուրյեի բերդը", "81be29bb"], "d": ["Տուրայի ափին, հին Նեռոմկար բնակավայրի տեղում, հիմնվեց Վերխոտուրյեի ամրացված կետը. նրա հիմնումը կապված է Սիբիր տանող ավելի կարճ ճանապարհի որոնման հետ։", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["Տուրայի ափին հիմնվեց Տուրինսկի բերդը", "c1d8534e"], "d": ["1600 թ. այսօրվա Տուրինսկի շրջանում հիմնվեց ռուսական կազակական-յասակային բերդ (օստրոգ) Տուրինսկը. բերդը Արևմտյան Սիբիրում ռուսական առաջխաղացման ճանապարհամերձ ամրություններից է։", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["Շահ Աբբաս I-ը Մազանդարանում հիմնեց Ֆարահաբադ քաղաքը", "cab4d0fe"], "d": ["Սեֆյան տիրակալ Աբբաս I-ը Մազանդարանում, Կասպից ծովի ափին մոտ մի վայրում, կառուցել տվեց Ֆարահաբադ քաղաքը և երկրի բոլոր ծայրերից այնտեղ բնակեցրեց մարդկանց։ Շինարարությունը սկսվեց հիջ. 1020/1611 թ.։", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["Անգարայի ափին հիմնվեց ռուսական Բրատսկի բերդը", "e7b4be59"], "d": ["Արևելյան Սիբիր ռուսական առաջխաղացման ժամանակ Անգարա գետի վրա հիմնվեց Բրատսկի բերդը։", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["Ռոսկիլեի պայմանագիրը. Սկոնեն, Հալլանդը, Բլեկինգեն և Բորնհոլմը անցան Շվեդիային", "afcae41b"], "d": ["Ստորագրվեց Կարլ Գուստավի առաջին պատերազմին վերջ դրած Ռոսկիլեի պայմանագիրը. Դանիա-Նորվեգիան Շվեդիային թողեց Սկոնեն, Հալլանդը, Բլեկինգեն և Բորնհոլմը։", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["Ռուսաստանը Սուրայի ափին հիմնեց Պենզայի բերդը", "49e8d90b"], "d": ["Պենզան հիմնվեց որպես մեծ բերդ Պենզա և Սուրա գետերի միախառնման վայրում. 1684 թվականից հետո այն կազմեց Սիզրանի պաշտպանական գծի արևմտյան ծայրը։", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["Մարկետը Սոլտ Սենտ Մարիում հիմնեց ֆրանսիական առաքելությունը", "86612bcd"], "d": ["Ճիզվիթ Ժակ Մարկետը Սուպերիոր և Հուրոն լճերի միջև գտնվող Սոլտ Սենտ Մարիի ջրվեժների գլխին հիմնեց առաքելություն։", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["Հիմնվեց Hudson's Bay Company-ի առաջին պահակակետը (Վասկագանիշ)", "07b32d57"], "d": ["Ջեյմսի ծոցում, Ռուպերտ գետի գետաբերանին, Մեդար Շուարդե դե Գրոզեյեն հիմնեց մի բնակավայր, որը հետագայում համարվեց Hudson's Bay Company-ի առաջին պահակակետը։", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["Իսպանական գաղութային վարչակարգը հիմնեց Պիտիկը (Էրմոսիլյո)", "11e5cc04"], "d": ["Իսպանական գաղութային վարչակարգը հին բնիկ բնակավայրի տեղում հիմնեց ավան. ավանը 1828 թ. ստացավ Խոսե Մարիա Գոնսալես դե Էրմոսիլյոյի անունը։", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["Իրտիշ-Օմ միախառնման վայրում հիմնվեց ռուսական Օմսկի բերդը", "13dcce5e"], "d": ["Օմսկը հիմնվեց որպես բերդ Տոբոլի և Իրտիշի միջև ընկած Իշիմի ամրությունների գծի արևելյան ծայրին. 1804 թ. դարձավ քաղաք։", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["Ջունգարները հարձակվեցին Լհասայի վրա. սպանվեց Լհավզանգ խանը, Տիբեթն անցավ ջունգարական օկուպացիայի տակ", "65beea29"], "d": ["Ցերինգ Դոնդուպի հրամանատարությամբ ջունգարական բանակը կեսգիշերից հետո բոլոր կողմերից հարձակվեց խոշուտ տիրակալ Լհավզանգ խանի պաշտպանած Լհասայի վրա. ներսից աջակցություն գտած ջունգարները գրավեցին և թալանեցին քաղաքը, կողոպտեցին նաև Պոտալան։ Լհավզանգ խանը սպանվեց փախչելիս. ջունգարները sTag-rtse-pa-ի գլխավորությամբ ստեղծեցին տիբեթյան խամաճիկ կառավարություն։", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["Ցին բանակը մտավ Լհասա. ջունգարական օկուպացիան ավարտվեց, սկսվեց Ցինի հովանավորությունը", "083358c1"], "d": ["Կանսիի՝ Տիբեթ ուղարկած երկու բանակներից Գալբիի հրամանատարությամբ սիչուանյան զորասյունը դժվարին երթով հասավ Լհասա և առանց դիմադրության վերցրեց քաղաքը. ջունգարները իրենց բոլոր ուժերը կենտրոնացրել էին Դամում՝ հյուսիսից եկող կուկունորյան բանակի դեմ։ Ջունգարների՝ Տիբեթից հեռանալուց հետո Ցինը Լհասայում հաստատեց մշտական հովանավորության կարգ։", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["Ագուայոյի արշավախումբը հիմնեց Լոս Ադաեսի պրեսիդիոն", "2031793a"], "d": ["Ագուայոյի մարկիզի արշավախումբը Լոս Ադաեսում հիմնեց պրեսիդիո (ռազմական պահակակետ) և կրկին բնակեցրեց առաքելությունը. պահակակետը դարձավ Նոր Իսպանիայի Արևելյան Տեխասի սահմանային կետը ֆրանսիական Լուիզիանայի դեմ։", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["Բարաբայի տափաստանում հիմնվեց ռուսական Կաինսկի պահակակետը", "b14552a8"], "d": ["Բարաբայի տափաստանում կառուցված երեք մշտական ռուսական ամրություններից (պաս) Կաինսկի պասը հիմնվեց Օմ գետի միջին հոսանքում՝ Կաինկա վտակի միախառնման վայրում։", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["Ույ գետի ափին հիմնվեց ռուսական Տրոիցկի բերդը", "623d75f2"], "d": ["Տրոիցկը հիմնվեց որպես բերդ Ույ գետին Ուվելկայի միախառնման վայրում և 1784 թ. ստացավ քաղաքի հրովարտակ։", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["Ելիզավետայի ֆիրմանով Դոնի գետաբերանին հիմնվեց Թեմեռնիկի մաքսատունը (Ռոստովի միջուկը)", "46519168"], "d": ["Կայսրուհի Ելիզավետա Պետրովնան հրովարտակ արձակեց Դոնի վրա Թեմեռնիկ գետի գետաբերանին մաքսատուն հիմնելու մասին. Թեմեռնիկի մաքսատունը Դոնի Ռոստով քաղաքի վաղ պատմության սկիզբն է։", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["Ֆրանսիացիները Տորոնտոյում Համբերի վրա առևտրական պահակակետ հիմնեցին", "18975f4c"], "d": ["Ֆրանսիացիները Համբեր գետի վրա հիմնեցին երկրորդ պահակակետը. հաջորդ տարի այսօրվա Exhibition Place-ի տեղում կառուցեցին Ֆորտ Ռույեն (Fort Rouillé)։", "66aeb450"]},
"OLAYLAR_2S_0919:1750-01-01:1":{"b": ["Ղաջար Մուհամմեդ Հասան խանը հռչակեց իր անկախությունը. վերցրեց Մազանդարանը և Գիլանը", "42fc62e8"], "d": ["Աֆշար Սուլեյման շահի գահընկեցությունից հետո Աստարաբադի ղաջար առաջնորդ Մուհամմեդ Հասան խանը հռչակեց իր անկախությունը. Աստարաբադից և Գորգանից բացի իր կառավարման տակ առավ նաև Մազանդարանն ու Գիլանը։", "f5398386"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["Ահմեդ շահ Դուրանին Բալխը միացրեց իր երկրին", "12c6bbf1"], "d": ["Աֆղան տիրակալ Ահմեդ շահ Դուրանին Բալխը միացրեց իր տիրապետության տարածքին։", "e3ef9016"]},
"OLAYLAR_2S_0919:1751-01-01:1":{"b": ["Քերիմ խան Զենդը տիրեց Սպահանին. Իրանում Աֆշարների իշխանությունը փոխարինվեց Զենդերի կառավարմամբ", "73cdc1e8"], "d": ["Նադիր շահի մահից (1747) հետո Սպահանը և Իրաք-ի Աջեմը կառավարվում էին Աֆշար շահերի՝ Ադիլ շահի (1747 թ. հուլիսի 6) և Իբրահիմ շահի (1748 թ. դեկտեմբերի 8) անունից։ Քերիմ խան Զենդը 1751 թ. հունվարին վերադառնալով Սպահան՝ տիրեց դրությանը։ Խորասանը Շահռուխի կառավարման տակ մնաց Աֆշարներին։", "daab8159"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["Իշիմի ափին հիմնվեց ռուսական Պետրոպավլովսկի բերդը", "5d16ef42"], "d": ["Պետրոպավլովսկը հիմնվեց որպես ռուսական բերդ և կարճ ժամանակում դարձավ Ռուսաստանի ու Կենտրոնական Ասիայի և ղազախական տափաստանի միջև առևտրի կարևոր կենտրոն։", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["Ագադեզի տուարեգները Բիլմայի աղահանքը վերցրին Կանեմ-Բորնուից", "1a563a74"], "d": ["18-րդ դարում անկում ապրած Կանեմ-Բորնուն 1759 թ., երբ Ագադեզի տուարեգները նրա ձեռքից վերցրին Բիլմայի աղահանքը, կորցրեց Սահարայի բազմաթիվ բնակավայրեր։", "ebfc53c3"]},
"OLAYLAR_2S_0919:1759-02-13:0":{"b": ["Ղաջար Մուհամմեդ Հասան խանը պարտվեց Քերիմ խան Զենդի բանակին և սպանվեց. Աստարաբադը, Մազանդարանը և Գիլանը անցան Զենդերի կառավարման", "38f0a375"], "d": ["Քերիմ խանի բանակը ծանր պարտության մատնեց Ղաջարներին. Մուհամմեդ Հասան խանը սպանվեց փախչելիս, նրա որդի Աղա Մուհամմեդին տարան Շիրազ։ Ղաջարների բեյության՝ Կասպից ծովի ափի հողերն անցան Զենդերի կառավարման։", "aa7e4a1e"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["Ուսման իբն Ֆոդիոյի ջիհադի բանակը վերցրեց Զարիան", "41279ca7"], "d": ["Ուսման իբն Ֆոդիոյի սկսած ջիհադի ընթացքում թեև Գոբիրի մայրաքաղաք Ալկալավայի վրա առաջին հարձակումը ձախողվեց, 1806 թ. գրավվեց Զարիան։", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["Հիմնվեց Սուլթանաբադ (Արաք) քաղաքը", "674237a0"], "d": ["Ղաջարների օրոք գեներալ Յուսուֆ խան Գորջին հիմնեց այսօրվա Արաք քաղաքը և այն անվանեց Սուլթանաբադ։", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["Հիմնվեց Բոֆորտ (Բոֆորտ Ուեսթ) ավանը", "c5cb1776"], "d": ["Անգլիական Բարեհուսո հրվանդանի գաղութում, Կարուի Hooyvlakte ագարակի վրա հիմնվեց Բոֆորտ ավանը։", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["Բալխը ենթարկվեց Բուխարայի էմիրի ներխուժմանը", "cd255a5d"], "d": ["Դուրանյան աֆղանական տիրապետության տակ գտնվող Բալխը 1826 թ. ենթարկվեց Բուխարայի էմիրի ներխուժմանը. քաղաքը 1841 թ. աֆղանները հետ վերցրին։", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["Ռուսաստանը Իշիմի վրա հիմնեց Ակմոլայի բերդը", "6c727ca9"], "d": ["Ռուսաստանը Իշիմ գետի Կարաուտկուլում կառուցեց Ակմոլայի բերդը և այդ վայրը դարձրեց սիբիրյան կիրգիզների (ղազախների) երկրի կենտրոնական ավանը։", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["Հիմնվեց Կոպալի ամրությունը. Հյուսիսային Սեմիրեչյեն սկսեց կապվել Ռուսաստանին", "8d4c24c6"], "d": ["Ռուսաստանը, Ավագ ժուզի ղազախների խնդրանքով, Սեմիրեչյեի Ալաթաուի ստորոտին հիմնեց Կոպալի ամրությունը։ Ըստ աղբյուրի՝ դա հեշտացրեց Հյուսիսային Սեմիրեչյեի՝ մինչև Իլի գետը Ռուսաստանին միանալը։", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["Ափի վաճառականները հաստատվեցին Կազեհում (Տաբորա)", "173223b0"], "d": ["Տեղական մի տիրակալի հետ բախումից հետո Արևելյան Աֆրիկայի ափից եկած վաճառականները գաղթեցին հարավ. Ունյանյեմբեի առաջնորդ Ֆունդիկիրան նրանց իր կենտրոն Իտետեմիայի մոտ բնակվելու տեղ տվեց։ Այս բնակավայրը դարձավ Տաբորա քարավանային կենտրոնի միջուկը։", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["Էլ-Հաջ Օմարի ֆուլանիները վերցրին Ջեննեն", "aa4e37f8"], "d": ["Մասինայի պետության կայազոր պահող Ջեննեն 1861 թ. անցավ էլ-Հաջ Օմարի ղեկավարած ֆուլանիների ձեռքը։", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["Էլ-Հաջ Օմարը վերցրեց Համդալլահին. Մասինայի պետության վերջը", "542f1c0d"], "d": ["Սեգուից փախած Բինա Ալիի ապաստանած Մասինայի դաշնակից զորամասերը պարտվեցին. Մասինայի կենտրոն Համդալլահին անցավ էլ-Հաջ Օմարի ձեռքը, Բինա Ալին և Ահմադու Ահմադուն մահապատժի ենթարկվեցին։", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["Բրազան հիմնեց Ֆրանսվիլը", "d28410d7"], "d": ["Պիեռ Սավորնյան դը Բրազան Մպասա գետին նայող ժայռոտ ելուստի վրա Ֆրանսիայի անունից հիմնեց Ֆրանսվիլի պահակակետը։", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["Կոնգոյի Ազատ պետության և Պորտուգալիայի սահմանային կոնվենցիան. Կոնգոյի գետաբերանի հարավային ափը՝ Պորտուգալիային", "08a16627"], "d": ["Բեռլինի կոնֆերանսի ընթացքում ստորագրված կոնվենցիայով Կոնգոյի Ազատ պետության և Պորտուգալիայի սահմանը Կոնգո (Զաիր) գետի գետաբերանից մինչև Ուանգո-Ուանգո վտակը գծվեց հենց գետով. Սոյոն գտնվող հարավային ափը մնաց Պորտուգալիային, իսկ Կաբինդան գետից հյուսիս նույնպես մնաց Պորտուգալիային։", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["Հադրամաուտի ափը (Մուկալլա) անցավ անգլիական հովանու ներքո", "dc824725"], "d": ["Շիհրն ու Մուկալլան ներառող Հադրամաուտի ափին տիրող յաֆիների (Քուայթիների) և Անգլիայի միջև ստորագրվեց հովանավորության պայմանագիր. անգլիացիները լիովին ստանձնեցին ափի յաֆիական կառավարման արտաքին հարաբերությունները։", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["Ֆրանսիացիները տիրեցին ամբողջ Ջոլոֆին", "c6d28eaa"], "d": ["Ցեղի առաջնորդների հետ կնքած համաձայնագրերով շրջանը գաղութացրած ֆրանսիացիները 1890 թ. տիրեցին ամբողջ Ջոլոֆին։", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["Ֆրանսիացիները գրավեցին Ջեննեն", "b207bf62"], "d": ["Էլ-Հաջ Օմարի հիմնած պետության ձեռքում գտնվող Ջեննեն 1893 թ. գրավվեց ֆրանսիական ուժերի կողմից և միացվեց Ֆրանսիական Սուդանին։", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["Գվերուն հիմնվեց որպես ռազմական պահակակետ", "bd37b323"], "d": ["Այսօրվա Զիմբաբվեի կենտրոնական մասում Գվերու քաղաքը հիմնվեց որպես ռազմական պահակակետ. հետագայում դարձավ գյուղատնտեսական կենտրոն և 1914 թ. ստացավ քաղաքապետարանի կարգավիճակ։", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["Բագիրմիի սուլթանությունը անցավ ֆրանսիական հովանու ներքո", "59f20c32"], "d": ["Ռաբիհի սպառնալիքի առջև Բագիրմիի տիրակալ Գաուրանգը ստիպված հովանավորության պայմանագիր կնքեց Ֆրանսիայի հետ։ Երբ դրան ի պատասխան Ռաբիհը ձեռնամուխ եղավ Բագիրմիի գրավմանը, Գաուրանգը իր ձեռքով այրեց մայրաքաղաք Մասինյան։", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["Կաֆֆայի թագավորությունը միացավ Եթովպիային. վերջին թագավոր Գակի Շերոչոն գերի ընկավ", "c03c44c5"], "d": ["Մենելիք II-ի՝ ռաս Վալդե Գիյորգիսի հրամանատարությամբ ուժերը 1897 թ. մարտին մտան Կաֆֆա։ Ծանր կռիվներից հետո Կաֆֆան նվաճվեց. վերջին թագավոր Գակի Շերոչոն 1897 թ. հոկտեմբերին ձերբակալվեց և անձնատուր եղավ։", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["Ֆրանսիացիները գրավեցին Գաոն", "01eabb4c"], "d": ["Նիգերի ափին գտնվող հին սոնգայական մայրաքաղաք Գաոն 1898 թ. գրավվեց ֆրանսիացիների կողմից. գրավումից հետո քաղաքը կրկին մեծացավ և դարձավ շրջանի կենտրոնը։", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["Հիմնվեց Ուգանդայի երկաթուղու Նայրոբիի մատակարարման պահեստը", "a3ce3389"], "d": ["Այսօրվա Նայրոբիի տեղում՝ մինչ այդ մեծ մասամբ անմարդաբնակ ճահճոտ տարածքում, անգլիացիները հիմնեցին Մոմբասան Ուգանդային կապող Ուգանդայի երկաթուղու մատակարարման պահեստը։", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["Ադամավան բաժանվեց. Յոլան մնաց անգլիական Հյուսիսային Նիգերիայում", "11104686"], "d": ["Ադամավան բաժանվեց Անգլիային ենթակա Հյուսիսային Նիգերիայի և Գերմանիային ենթակա Կամերունի միջև. Ադամայի չորրորդ որդի Բոբբո Ահմադուն անգլիական գոտում դարձավ Յոլայի էմիր։", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["Բուրմիի ճակատամարտը. Սոկոտոյի խալիֆայության քաղաքական իշխանությունը վերջացավ", "c7d87e2c"], "d": ["Անգլիացիների՝ Սոկոտոն գրավելուց հետո փախած խալիֆ Մուհամմեդ Թահիրը անգլիացիների հետ նոր կռվում սպանվեց. մոտ մեկ դար տևած Սոկոտոյի խալիֆայության քաղաքական իշխանությունն ավարտվեց։", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["Նակուրուն պաշտոնապես հիմնվեց որպես ավան", "d82a2d76"], "d": ["Ուգանդայի երկաթուղու վրա իր դիրքի շնորհիվ Նակուրուն պաշտոնապես հիմնվեց որպես ավան և դարձավ շրջանի գյուղատնտեսական մթերքների կենտրոնը։", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["Օրենբուրգ-Տաշքենդ երկաթուղու վրա բացվեց Արալյան ծովի կայարանը. հիմնվեց Արալսկ բնակավայրը", "85803dcb"], "d": ["Ռուսական կայսրության Օրենբուրգն ու Տաշքենդը կապող երկաթուղին Արալյան ծովի հյուսիս-արևելյան ծայրով անցնելիս ափին բացվեց «Արալսկոյե Մորե» կայարանը. կայարանի կողքին ծնվեց ձկնորսական բնակավայր։ Բնակավայրը 1938 թ. ստանալով քաղաքի կարգավիճակ՝ կոչվեց Արալսկ։", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["Ֆրանսիացիները վերցրին Աբեշեն. Վադաիի սուլթանության վերջը", "3c9b117b"], "d": ["Դեպի արևելք առաջխաղացումը շարունակած ֆրանսիացիները, գրավելով Վադաիի մայրաքաղաք Աբեշեն, վերջ դրեցին Վադաիի սուլթանությանը. վերջին սուլթանը հեռացավ՝ չկարողանալով փրկել իր մայրաքաղաքը։", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["Հիմնվեց Հարավաֆրիկյան միությունը", "7434a47f"], "d": ["1909 թ. South Africa Act-ի համաձայն Կապի, Նատալի, Տրանսվաալի և Օրանժ գետի գաղութները 1910 թ. մայիսի 31-ին միավորվեցին Բրիտանական կայսրությանը կապված Հարավաֆրիկյան միություն անունով. գործադիր կենտրոնը դարձավ Պրետորիան, օրենսդիր կենտրոնը՝ Քեյփթաունը։ Այս միավորմամբ Կապի, Նատալի, Տրանսվաալի և Օրանժի գաղութների քաղաքները (Քիմբերլի, Դուրբան, Պիտերմարիցբուրգ, Պոչեֆստրոմ, Պորտ Էլիզաբեթ և այլն) անցան Հարավաֆրիկյան միությանը։", "7fc35ce0"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["Ֆրանսիացիները գրավեցին Ջանետը (Djanet)", "f32997c8"], "d": ["Գատին ենթակա օսմանյան նահիյե Ջանետը 1911 թ. գրավվեց ֆրանսիացիների կողմից։ Նահիյեի կառավարիչ շեյխ Ամուդը մինչ այդ թվականը ռոճիկ էր ստացել Օսմանյան պետությունից։", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["Անքորիջը հիմնվեց որպես Ալյասկայի երկաթուղու կենտրոն", "f5014711"], "d": ["Կոնգրեսի՝ 1914 թ. մարտի 12-ին Alaska Railroad Act-ը ընդունելուց հետո, 1915 թ. գարնանը Ալյասկայի ինժեներական հանձնաժողովը Շիփ Քրիքում հիմնեց երկաթուղու շինհրապարակը. ափին ծնվեց վրանային քաղաք, և 1915 թ. ապրիլին փոստային վարչությունը նոր ավանը անվանեց Anchorage։ Քաղաքը դարձավ հյուսիսում Ֆերբենքս ձգվող Ալյասկայի երկաթուղու կենտրոնը։", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Սենուսիների անապատային կենտրոն Ջաղբուբի կապումը օսմանյան կարգին. Աբդուլմեջիդի ազատման ֆիրմանը", "039fce6d"], "d": ["Երկար տարիներ Մեքքայում մնացած Մուհամմեդ բ. Ալի աս-Սենուսին, Տրիպոլիտանիա վերադառնալուց հետո, հաստատվեց Եգիպտոսի սահմանին գտնվող Ջաղբուբի օազիսում և գերիշխող ժայռի վրա մեծ զավիե կառուցել տվեց. մի քանի խրճիթից բաղկացած վայրը կարճ ժամանակում վերածվեց քաղաքի։ 1856 թ. սուլթան Աբդուլմեջիդի ֆիրմանով միաբանության անդամներին պատկանող գույքը ազատվեց հարկերից, և մուրիդներին տրվեց զաքաթ հավաքելու իրավասություն։ Այս ֆիրմանը Արևմտյան Աֆրիկան և Սուդանը Կահիրեին կապող քարավանային ճանապարհի վրա գտնվող օազիսը դարձրեց օսմանյան ֆինանսական և վարչական կարգի մաս և ամրապնդեց Ջաղբուբը որպես առևտրի կենտրոն։ Շրջանի բնակչության հավատարմությունը խալիֆին հաստատում է նաև 1884 և 1893 թթ. այստեղ եղած գնդապետ Սադըք ալ-Մուայյադի ճանապարհորդագրությունը։", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Սուեզի ջրանցքի փորման սկիզբը և Պորտ Սաիդի հիմնումը", "cef0be8d"], "d": ["Բաբը Ալիի (Բարձր Դռան) 1856 թ. հունվարի 5-ին հավանություն տված Լեսեփսի նախագծի փորման աշխատանքները սկսվեցին 1859 թ. ապրիլի 25-ին. ջրանցքն ավարտվելու էր տասը տարի անց՝ 1869 թ. նոյեմբերի 16-ին։ Փորման միջերկրածովյան ծայրին՝ Մանզալա լճի և ծովի միջև ընկած ափային շերտի վրա, բանվորների համար կառուցված հինգ տնից բաղկացած խրճիթային գյուղը դարձավ Պորտ Սաիդի միջուկը։ Քաղաքին այս անունը, «Սաիդի նավահանգիստ» իմաստով, 1860 թ. տվեցին ջրանցքի ընկերության պաշտոնյաները՝ ի պատիվ ժամանակի Եգիպտոսի կուսակալ Սաիդ փաշայի։ Այսպիսով, օսմանյան քարտեզի վրա նոր նավահանգիստ ծնվեց մի ափային շերտի վրա, որտեղ նախկինում ոչ մի բնակավայր չի եղել։", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Սուլթան Աբդուլազիզի այցը Եգիպտոս և Իսմաիլիայի հիմնումը Սուեզի պարանոցում", "bcfacf38"], "d": ["Սուլթան Աբդուլազիզը մեծ վեզիր Յուսուֆ Քամիլ փաշայի խրախուսմամբ 1863 թ. ապրիլի 3-ին մեկնեց Եգիպտոս և դիմավորվեց մեծ ցույցերով. նպատակն էր ամրապնդել կենտրոնին ենթակայությունը այն վիլայեթի, որը Կավալացի Մեհմեդ Ալի փաշայի ապստամբությունից ի վեր սկսել էր փաստացի վերածվել առանձին պետության։ Նույն տարում պարանոցում՝ Թիմսահ լճի ափին գտնվող Թիլալ ալ-Ջիսրի բլուրների վրա, հիմնվեց ջրանցքի ընկերության կառավարման կենտրոնը. նախ ինժեներների համար հաստատվեց Քարյաթ ութ-Թիմսահ, ապա բանվորների համար՝ Քարյաթ ուլ-Արաբ գյուղը։ Երբ խեդիվ Իսմայիլ փաշան անձամբ հետաքրքրվեց քաղցրահամ ջրի ջրանցքով և այդ բլրի վրա իր համար ամառանոց կառուցել տվեց, բնակավայրը նրա անունով կոչվեց Իսմաիլիա։ Քաղաքի հիմնումը թվագրվում է 1863 թ.. ճշգրիտ օրը հայտնի չէ։", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Միդհաթ փաշայի Բաղդադի կուսակալությունը և ցեղերի բնակեցումը. Ռամադիի և Նասիրիայի հիմնումը", "0fa98f06"], "d": ["Պետական խորհրդի (Շյուրա-յը Դևլեթ) նախագահությունից հեռացված և Ստամբուլից հեռու ուղարկված Միդհաթ փաշան 1869-1872 թթ. լայն իրավասություններով կառավարեց Բաղդադի վիլայեթը, որն ընդգրկում էր նաև Մոսուլն ու Բասրան, միաժամանակ ղեկավարելով նաև Վեցերորդ բանակը։ Այստեղ կիրառելով Հողային օրենսգիրքը և վիլայեթների նոր օրենքը՝ նա հողերը բաժանեց տապուով (սեփականության վկայականով) և քոչվոր ցեղերը կապեց նստակյաց կյանքին և պետական իշխանությանը։ Այս բնակեցման քաղաքականության արդյունքում 1869 թ. Եփրատի ափին Դուլայմ ցեղի համար հիմնվեց Ռամադին, իսկ հարավում Մունթաֆիքի մութասարրիֆ Նասիր փաշա աս-Սաադունի ձեռքով՝ Նասիրիան. երկուսն էլ ծնվեցին այն կետերում, որտեղ մինչ այդ բնակավայր չէր եղել, և քարտեզ մտան առաջին անգամ այդ ժամանակ։", "7babb36f"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["Կոնրադ II-ը ընտրվեց Գերմանիայի թագավոր և թագադրվեց Մայնցում. սկսվեց Սալիական հարստությունը", "c88123e8"], "d": ["Հենրի II-ի մահից հետո գերմանական իշխանները 1024 թ. սեպտեմբերի 4-ին հավաքվեցին Ռենոսի աջ ափի Կամբայում. ընտրությունը ղեկավարեց Մայնցի արքեպիսկոպոս Արիբոն։ Կոնրադ Ավագը հաղթեց իր եղբորորդի Կոնրադ Կրտսերին և Աստվածածնի ծննդյան տոնին (սեպտեմբերի 8) Մայնցում Արիբոյի ձեռքով թագադրվեց որպես թագավոր։", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["Կոնրադ II կայսրը մահացավ Ուտրեխտում", "f967406b"], "d": ["Սալիական հարստության առաջին կայսր Կոնրադ II-ը 1039 թ. հունիսի 4-ին Ուտրեխտում մահացավ կարճատև ու տանջալից հիվանդությունից հետո։", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["Վորմսի կոնկորդատ. ինվեստիտուրայի վեճն ավարտվեց", "8073e4a0"], "d": ["Պապական պատվիրակության միջնորդությամբ Հենրի V կայսեր և Կալիքստոս II պապի միջև հաշտությունը 1122 թ. սեպտեմբերի 23-ին հռչակվեց Վորմսում (Լոբվիզենում, քաղաքի հենց կողքին)։ Հենրին հրաժարվեց մատանիով և գավազանով ինվեստիտուրայից, ընդունեց եպիսկոպոսների և վանահայրերի կանոնական ընտրությունը։", "a915c2e7"]},
"OLAYLAR_ALM1115B:1125-05-23:0":{"b": ["Հենրի V կայսրը մահացավ Ուտրեխտում", "790cadc4"], "d": ["Հենրի V կայսրը 1125 թ. մայիսի 23-ին մահացավ Ուտրեխտում. հիշվում է որպես Վորմսի կոնկորդատի (1122) կայսր։", "8402ca28"]},
"OLAYLAR_ALM1115B:1152-03-05:0":{"b": ["Ֆրիդրիխ I Բարբարոսան Ֆրանկֆուրտում ընտրվեց Գերմանիայի թագավոր", "b91f29a3"], "d": ["Իշխանները Ֆրիդրիխին 1152 թ. մարտի 5-ին Ֆրանկֆուրտում բարձրացրին թագավորության. մարտի 9-ին Աախենում թագադրվեց։ Այսպիսով սկսվեց Հոհենշտաուֆեն հարստության Բարբարոսայի շրջանը։", "26fcdb8c"]},
"OLAYLAR_ALM1115B:1156-09-17:0":{"b": ["Privilegium Minus. Ավստրիան դարձավ դքսություն, Բավարիան տրվեց Հայնրիխ Առյուծին", "a64c125b"], "d": ["Ռեգենսբուրգի իշխանների վճռով Ավստրիան բարձրացվեց դքսության, և Հայնրիխ Յազոմիրգոտին ճանաչվեցին հատուկ իրավունքներ. նույն կարգավորմամբ Հայնրիխը Բավարիան վերադարձրեց կայսրին, իսկ կայսրը Բավարիան որպես ավատ տվեց Հայնրիխ Առյուծին։", "fe899d87"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["Ցերինգեն տոհմի մարումով Բեռնը դարձավ ազատ կայսերական քաղաք", "1473c219"], "d": ["Երբ Ցերինգեն հարստությունը 1218 թ. մարեց, Բեռնը դարձավ ուղղակի կայսրությանը ենթակա ազատ քաղաք. 1353 թ. որպես ութերորդ անդամ մտավ Շվեյցարական համադաշնություն։", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["Հեսսենի լանդգրաֆությունը. Բրաբանտցի Հայնրիխ I-ը դարձավ Հեսսենի առաջին լանդգրաֆը, հաշտություն Մայսենի հետ 1264 թ.", "57067f04"], "d": ["Հեսսենի՝ որպես անկախ երկրի պատմությունը սկսվում է Հայնրիխ I-ից («Մանուկ»). Մայսենի հետ հաշտությունը կնքվեց 1264 թ.։ Հայնրիխը Կասելում ամրոց կառուցել տվեց, և այն հաջորդ տարիներին դարձավ նրա սովորական նստավայրը. 1292 թ. նա ընդունվեց կայսերական իշխանների դասը (Reichsfürstenstand)։", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["Շվերինի կոմսությունը համաձայնությամբ անցավ Մեկլենբուրգի դուքս Ալբրեխտ II-ի ձեռքը", "013b6860"], "d": ["Ալբրեխտ II-ը 1358 թ. դեկտեմբերի 1-ի պայմանագրով կոմս Նիկոլաուսին 10.000 մարկ արծաթ վճարելով ստացավ Շվերինի կոմսությունը. քաղաքն այդ ժամանակից դարձավ Մեկլենբուրգի դքսության հողը (իսկ որպես մայրաքաղաք հաստատվելը վերջնականացավ XVI դարում)։", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["Լանդգրաֆ Ֆիլիպ «Առատաձեռնը» մահացավ Կասելում. Հեսսենը բաժանվեց նրա չորս որդիների միջև", "c0cb27ed"], "d": ["Ռեֆորմացիայի քաղաքական առաջնորդներից Հեսսենի լանդգրաֆ Ֆիլիպ I-ը 1567 թ. մարտի 31-ին մահացավ Կասելում։ 1562 թ. կտակի համաձայն երկիրը բաժանվեց չորս որդիների միջև՝ Հեսսեն-Կասել (Վիլհելմ IV), Հեսսեն-Մարբուրգ (Լյուդվիգ IV), Հեսսեն-Ռայնֆելս (Ֆիլիպ II) և Հեսսեն-Դարմշտադտ (Գեորգ). այսպիսով ավարտվեց միացյալ Հեսսենի լանդգրաֆությունը։", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["Պոմերանիայի վերջին դուքս Բոգիսլավ XIV-ը մահացավ Շտետինում. Գրիֆինների հարստությունն ավարտվեց", "ab96746a"], "d": ["Պոմերանիայի վերջին դուքս Բոգիսլավ XIV-ը 1637 թ. մարտի 10-ին մահացավ Շտետինում, և նրա հետ մարեց Պոմերանիայի տեղական հարստությունը։ Դքսության փաստացի բաժանումը (Բրանդենբուրգ-Շվեդիա) հաստատվեց 1648 թ. Վեստֆալյան հաշտությամբ։", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["Ֆերդինանդ III-ը Բրեմենին շնորհեց ազատ կայսերական քաղաքի արտոնությունները", "174142ee"], "d": ["Ֆերդինանդ III կայսրը 1646 թ. Բրեմենին ճանաչեց ազատ կայսերական քաղաքի արտոնությունները. Շվեդիան դրան հակառակվեց և 1666 թ. փորձեց զենքով հնազանդեցնել քաղաքը, բայց չհաջողվեց։ Հանովերի կուրֆյուրստը, ստանալով արքեպիսկոպոսությունը (1720), Բրեմենը ճանաչեց ազատ քաղաք։", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["Բրեմենը միացվեց Ֆրանսիական կայսրությանը. դարձավ Վեզերի գետաբերանների դեպարտամենտի կենտրոն", "d5d149ae"], "d": ["Բրեմենը 1806 թ. գրավվեց ֆրանսիացիների կողմից և 1810-1813 թթ. եղավ Վեզերի գետաբերանների (Bouches-du-Weser) դեպարտամենտի կենտրոնը։", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["Նապոլեոնը Լյուբեկը միացրեց Ֆրանսիական կայսրությանը", "1ca78afe"], "d": ["Բլյուխերի՝ 1806 թ. նոյեմբերին Լյուբեկի մոտ անձնատուր լինելուց հետո քաղաքը կողոպտվել էր ֆրանսիացիների կողմից, և 1810 թ. դեկտեմբերին Նապոլեոնը քաղաքը միացրել է իր կայսրությանը։ Լյուբեկը մինչև այդ ժամանակ 1226-ից ազատ կայսերական քաղաք էր։", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["Լյուբեկը ապստամբեց ֆրանսիական իշխանության դեմ և վերականգնեց ազատ քաղաքի կարգավիճակը", "84e70d49"], "d": ["1813 թ. ֆրանսիական կառավարման դեմ ապստամբած Լյուբեկը 1815 թ. Վիեննայի կոնգրեսի կողմից ճանաչվել է Գերմանական միության ազատ և հանզեական քաղաք։", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["Ֆրանսիական իշխանությունն ավարտվեց. Բրեմենը վերականգնեց ազատ քաղաքի կարգավիճակը", "4afa71be"], "d": ["Բրեմենի՝ որպես Վեզերի գետաբերանների դեպարտամենտի կենտրոն, ֆրանսիական կառավարման տակ մնալը ավարտվեց 1813 թ.. քաղաքը 1815 թ. Վիեննայի կոնգրեսի կողմից ստացավ անկախություն և միացավ Գերմանական միությանը։", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["Մեկլենբուրգ-Շվերինի դքսությունն ստացավ մեծ դքսության տիտղոսը", "3f5d05eb"], "d": ["Մեկլենբուրգ-Շվերինի դուքս Ֆրիդրիխ Ֆրանց I-ը 1815 թ. ստացավ մեծ դքսի («großherzogliche Würde») տիտղոսը. Մեկլենբուրգի դքսության (1348-1815) գրառումը այստեղ ավարտվում է, երկիրը շարունակում է գոյությունը որպես Գերմանական միության կազմում մեծ դքսություն։", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["Ուժի մեջ մտավ Մեծ Համբուրգի օրենքը. Լյուբեկի անկախ նահանգի կարգավիճակն ավարտվեց", "6df2f92a"], "d": ["1937 թ. հունվարի 26-ին ընդունված Մեծ Համբուրգի օրենքը ուժի մեջ մտավ 1937 թ. ապրիլի 1-ին. Լյուբեկը, կորցնելով ավելի քան 700-ամյա ինքնավարությունը, կապվեց Պրուսիայի Շլեզվիգ-Հոլշտայն նահանգին, Համբուրգի սահմանները ընդլայնվեցին։", "b96594d2"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["Հիմնվեց Բարակոան. Կուբայի իսպանական նվաճման առաջին ավանը", "8c033cf1"], "d": ["Դիեգո Վելասկես դե Կուելյարը Իսպանյոլայից տեղափոխած ուժով 1511 թ. սկսեց Կուբայի նվաճումը և հիմնեց կղզու առաջին իսպանական ավանը՝ Nuestra Señora de la Asunción de Baracoa-ն։ Բարակոան հաջորդ քսան տարում դարձավ Մեքսիկա ուղղվող արշավախմբերի (Էռնանդես դե Կորդոբա, Գրիխալվա, Կորտես) հենակետային շրջանը։", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["Սենտլայի ճակատամարտը. մայաների Պոտոնչան իշխանությունն ընկավ, հիմնվեց Սանտա Մարիա դե լա Վիկտորիան", "8489a7d8"], "d": ["Կուբայից ճանապարհ ընկած Կորտեսի նավատորմը ափ իջավ Գրիխալվա գետի գետաբերանի չոնտալ մայաների Պոտոնչան քաղաքում։ Սենտլայի հարթավայրի ճակատամարտում հեծելազորի և հրազենի գերազանցությամբ հաղթած իսպանացիները քաղաքի տեղում հիմնեցին Սանտա Մարիա դե լա Վիկտորիա ավանը։ Սա Մեքսիկայի մայրցամաքային մասում առաջին մշտական իսպանական բնակավայրն է. Կորտեսին թարգմանություն անելիք Մալինցինը (դոնյա Մարինա) այստեղ տրված նվերների թվում էր։", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["Հիմնադրվեց Պանաման՝ Խաղաղ օվկիանոսի ափի առաջին եվրոպական քաղաքը", "c0d86c22"], "d": ["Դարիենի կուսակալ Պեդրարիաս Դավիլան պարանոցի խաղաղօվկիանոսյան ափին հիմնեց Պանամա քաղաքը և գաղութային վարչությունը Կարիբյան ափից տեղափոխեց այստեղ։ Քաղաքը դարձավ դեպի հարավ ուղղվելիք հետախուզական և նվաճողական արշավանքների ելման նավահանգիստը. Ֆրանսիսկո Պիսարոյի Պերուի արշավանքներն այստեղից են հանդերձվել։", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["Տեպեակայի գրավումը. Կորտեսի առաջին նվաճումը «Տխրության գիշերից» հետո", "a9c27711"], "d": ["1520 թ. հունիսի 30-ի գիշերը (Noche Triste) Տենոչտիտլանից ծանր կորուստներով նահանջած Կորտեսը, Տլաշկալայում ապաստանելուց հետո, իր առաջին հարձակումը գործեց Եռակի դաշինքին կապված Տեպեակա իշխանության վրա։ Վերցնելով քաղաքը՝ հիմնեց իսպանական ավան Segura de la Frontera անունով. այսպիսով ապահովվեց Վերակրուսի ափի և Տլաշկալայի միջև ճանապարհը և պատրաստվեց մայրաքաղաքի վրա երկրորդ երթի հենակետը։", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["Հիմնվեց Սան Սեբաստիան դե Կոլիման. Նոր Իսպանիայի ելքը Խաղաղ օվկիանոսի ափ", "30332cab"], "d": ["Կորտեսի հրամանատարներից Գոնսալո դե Սանդովալը, հնազանդեցնելով արևմտյան Մեքսիկայի Կոլիմա հովիտը, հիմնեց Սան Սեբաստիան դե Կոլիմա ավանը։ Ավանը դարձավ Նոր Իսպանիայի՝ Խաղաղ օվկիանոսի ափի առաջին հենակետերից մեկը և հետագա տարիներին սնուցեց Հարավային ծովի հետախուզական արշավախմբերի նավաշինարանները։", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["Հիմնադրվեց Սան Ֆրանսիսկո դե Կիտոն՝ իսպանական կարգ ինկերի հյուսիսային մայրաքաղաքում", "7bb9f316"], "d": ["Ինկերի զորավար Ռումինյաուին, նախքան հյուսիսի մայրաքաղաք Կիտոն իսպանացիներին թողնելը, այրեց այն։ Սեբաստիան դե Բենալկասարը ավերակների վրա հիմնեց Սան Ֆրանսիսկո դե Կիտոն. այսպիսով Կուսկոյից հետո ինկերի պետության երկրորդ կենտրոնը ևս ենթարկվեց իսպանական կառավարմանը, և Հյուսիսային Անդերի նվաճումը ղեկավարվեց այստեղից։", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["Հիմնադրվեց Լիման. իսպանական Պերուի մայրաքաղաքը տեղափոխվեց Ռիմակի հովիտ", "1f15658c"], "d": ["Քանի որ լեռներում գտնվող Կուսկոն հեռու էր Իսպանիայի հետ ծովային կապից, Ֆրանսիսկո Պիսարոն ծովափնյա Ռիմակի հովտում հիմնեց Սյուդադ դե լոս Ռեյեսը (Լիմա)։ Քաղաքը կարճ ժամանակում դարձավ Պերուի փոխարքայության մայրաքաղաքը և Հարավային Ամերիկայում իսպանական կառավարման կենտրոնը։", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["Հիմնադրվեց Պոպայանը՝ կամուրջ Կիտոյի և մուիսկաների երկրի միջև", "bf451979"], "d": ["Կիտոյից դեպի հյուսիս շարժվող Բենալկասարը Կաուկայի հովտում հիմնեց Պոպայանը։ Քաղաքը դարձավ Պերուից եկող իսպանական առաջխաղացման հյուսիսային ծայրակետը և հաջորդ տարի բացեց մուիսկաների երկրում Կեսադայի հետ հանդիպմանը տանող ճանապարհը։", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["Հունսայի գրավումը. սակե Կեմուենչատոչայի պարտությունը", "e8c1b661"], "d": ["Մագդալենա գետից սարահարթ բարձրացած Գոնսալո Խիմենես դե Կեսադան հարձակվեց մուիսկաների համադաշնության երկու գլխավոր կենտրոններից մեկի՝ սակե տիտղոսակրի իշխանության (սակասգո) կենտրոն Հունսայի վրա և գերեց սակե Կեմուենչատոչային։ Քաղաքում ձեռք գցված ոսկին դարձավ այն հիմնական ավարը, որը սնեց Էլդորադոյի մասին ասեկոսեները. այսպիսով մուիսկաների երկրի հյուսիսային կեսն անցավ իսպանական տիրապետության տակ։", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["Հիմնադրվեց Ասունսիոնը՝ իսպանական հենակետ Պարագվայ գետի վրա", "9a6dfa42"], "d": ["Երբ Ռիո դե լա Պլատայի արշավախումբը չկարողացավ ամրանալ Բուենոս Այրեսում, իսպանացիները նահանջեցին գետն ի վեր, և Խուան դե Սալասար դե Էսպինոսան, հենվելով գուարանի համայնքների հետ կնքված դաշինքի վրա, հիմնեց Նուեստրա Սենյորա դե լա Ասունսիոնը։ Ավանը մեկ դար շարունակ մնաց Ռիո դե լա Պլատայի ավազանում իսպանական կառավարման կենտրոնը։", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["Հիմնադրվեց Սանտա Ֆե դե Բոգոտան՝ իսպանական մայրաքաղաք մուիսկաների երկրում", "3ed6c301"], "d": ["Կեսադան սիպայի կենտրոն Բակատայի կողքին հիմնեց Սանտա Ֆե դե Բոգոտան։ Հիմնադրումից անմիջապես հետո երեք տարբեր ուղղություններից եկած նվաճողական ջոկատները՝ Կեսադան, Բենալկասարը և գերմանացի հրամանատար Ֆեդերմանը, հանդիպեցին նույն սարահարթում և պայմանավորվեցին իրենց իրավունքների պահանջները լուծել Իսպանիայում։ Քաղաքը դարձավ Նոր Գրանադայի թագավորության մայրաքաղաքը։", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["Հիմնադրվեց Սան Խուան դե լա Ֆրոնտերա դե Ուամանգան՝ Լիմա-Կուսկո ճանապարհի բանալին", "3f1cfdbf"], "d": ["Մանկո Ինկայի՝ Վիլկաբամբայից ղեկավարած դիմադրությունը կտրում էր Լիմայի և Կուսկոյի միջև ճանապարհը։ Ֆրանսիսկո Պիսարոն այս ճանապարհն ապահովելու համար երկու մայրաքաղաքների միջև հիմնեց Սան Խուան դե լա Ֆրոնտերա դե Ուամանգան. ավանի անվան «frontera» (սահմանագիծ) բառն ուղղակիորեն ասում է նրա հիմնադրման նպատակը։", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["Տունխան վերահիմնադրվեց որպես իսպանական քաղաք", "c3a12867"], "d": ["Կեսադայի Իսպանիա վերադառնալուց հետո Գոնսալո Սուարես Ռենդոնը սակեի կենտրոն Հունսայի տեղում իսպանական կարգով վերահիմնադրեց Տունխա քաղաքը։ Այսպիսով մուիսկաների երկրի հյուսիսային կեսը, Բոգոտայի կեսի նման, կապվեց քաղաքային մշտական ինքնակառավարման և էնկոմիենդայի կարգի հետ։", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["Հիմնվեց Սան Ֆրանցիսկո դե Կամպեչեն. Յուկատանի նվաճման երրորդ և հաստատուն փորձը", "62af9901"], "d": ["Յուկատանը վերցնելու երկու անհաջող արշավանքից հետո Ֆրանսիսկո դե Մոնտեխոն (որդին) մայաների Կան Պեչ քաղաքի տեղում հիմնեց Սան Ֆրանցիսկո դե Կամպեչե ավանը։ Այս նավահանգիստը դարձավ թերակղզու ներքուստ շարժվելիք ուժերի մատակարարման հենակետը և կազմեց այն արշավանքի ելակետը, որն ավարտվեց երկու տարի անց Մերիդայի հիմնմամբ։", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["Հիմնադրվեց Սանտյագո դել Նուևո Էքստրեմոն. սկսվեց Չիլիի նվաճումը", "04cd7c3b"], "d": ["Պերուից դեպի հարավ շարժվող Պեդրո դե Վալդիվիան Մապոչոյի հովտում հիմնեց Սանտյագո դել Նուևո Էքստրեմոն։ Ավանը նույն տարվա սեպտեմբերին Միչիմալոնկոյի գլխավորած բնիկների հարձակման հետևանքով այրվեց և վերակառուցվեց. այդուհանդերձ, Չիլիի իսպանական նվաճումը ղեկավարվեց հենց այս կետից։", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["Սոտուտայի Կոկոմ իշխանությունը անցավ իսպանական տիրապետության տակ", "db6a6487"], "d": ["Յուկատանի ներսի մայաների ամենաուժեղ իշխանություններից Սոտուտան Կոկոմ հարստության ներքո երկար ժամանակ դիմադրեց իսպանական առաջխաղացմանը։ 1542 թ. Մերիդայի հիմնումից հետո ընկած տարիներին իշխանությունը ընդունեց իսպանական տիրապետությունը. 1546-47 թթ. արևելյան մեծ ապստամբությունը ճնշելուց հետո այս ենթակայությունը կայունացավ։", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["Հիմնադրվեց Վիլյա դե Օրոպեսան՝ Պոտոսին կերակրող հացահատիկային հովտի բնակեցումը", "d6821cbf"], "d": ["Փոխարքա Ֆրանսիսկո դե Տոլեդոյի հրամանով Կոչաբամբայի հովտում հիմնադրվեց Վիլյա դե Օրոպեսան։ Հովտի բերրի հողը կազմակերպվեց որպես հացահատիկային շրջան, որը պետք է կերակրեր Պոտոսիի արծաթի հանքերի բազմամարդ աշխատուժը. ավանը դարձավ գաղութային Վերին Պերուի շտեմարանը։", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["Վիլկաբամբայի անկումը. անկախ ինկերի պետության վախճանը", "31b5a95d"], "d": ["1533 թվականին Կուսկոյի անկումից հետո Մանկո Ինկան և նրա հաջորդները Վիլկաբամբայի լեռներում քառասուն տարի պահպանեցին ինկերի անկախ պետություն։ Փոխարքա Ֆրանսիսկո դե Տոլեդոյի կազմակերպած արշավանքը գրավեց լքված մայրաքաղաքը. փախուստի դիմած վերջին տիրակալ Տուպակ Ամարուն բռնվեց, բերվեց Կուսկո և այնտեղ մահապատժի ենթարկվեց։ Այսպիսով Անդերի աշխարհում ավարտվեց ինկերի չորսդարյա հարստության քաղաքական գոյությունը։", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["Հիմնվեց Մոնտերեյը. Նուևո Լեոնի մայրաքաղաքը", "ec6e44bc"], "d": ["Դիեգո դե Մոնտեմայորը երկու անհաջող փորձից հետո Սանտա Լուսիա աղբյուրի գլխին հիմնեց Ciudad Metropolitana de Nuestra Señora de Monterrey-ը։ Հյուսիսային սահմանի այս բնակավայրը դարձավ Նոր Իսպանիայի՝ դեպի հյուսիս-արևելք (Նուևո Լեոն) մշտական ընդարձակման հենակետը։", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["Հիմնադրվեց Սան Ֆրանսիսկո դե Բորխան. իսպանական տիրապետություն Մայնասում", "7ee32d19"], "d": ["Դիեգո Վակա դե Վեգան Մարանյոն գետի Պոնգո դե Մանսերիչե կիրճից ներքև հիմնեց Սան Ֆրանսիսկո դե Բորխան և Մայնասի շրջանը կապեց իսպանական կառավարմանը։ Ավանը դարձավ ելման կետ ճիզվիտական առաքելությունների ցանցի համար, որը Վերին Ամազոնում գործելու էր ողջ հաջորդ դարը։", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["Հիմնվեց Սան Անտոնիո դե Վալերո առաքելությունը. իսպանական Տեխասի միջուկը", "ca9bd147"], "d": ["Ֆրանսիացիների՝ Լուիզիանայից դեպի արևմուտք ներթափանցման դիմաց Իսպանիան որոշեց Տեխասում մշտական կայան հիմնել։ Հայր Օլիվարեսը Սան Անտոնիո գետի ափին հիմնեց Սան Անտոնիո դե Վալերո առաքելությունը. մի քանի օր անց կուսակալ Ալարկոնը նրա կողքին տեղադրեց Սան Անտոնիո դե Բեխար պրեսիդիոն։ Առաքելության շենքը հետագայում կոչվելու է Ալամո։", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["Հիմնվեց Ռեֆուխիոն (այսօրվա Մատամորոս). Ռիո Գրանդեի գետաբերանի բնակեցումը", "f3b86da7"], "d": ["Խոսե դե Էսկանդոնի՝ 1740-ականներից վարած Նուևո Սանտանդերի բնակեցման ծրագիրը Ռիո Գրանդեի ստորին ավազանը լցրեց ագարակներով և ավաններով։ Nuestra Señora del Refugio de los Esteros-ը գետի հարավային ափին հիմնվեց որպես այս ծրագրի վերջին օղակներից մեկը. 19-րդ դարում ստացավ Մատամորոս անունը։", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["Կենտրոնական Ամերիկայի անկախության հռչակագիրը. Գվատեմալայի գլխավոր կապիտանությունը բաժանվեց Իսպանիայից", "f998089a"], "d": ["Մեքսիկայի Իգուալայի ծրագրից հետո Գվատեմալայում գումարված ժողովը հռչակեց գլխավոր կապիտանության անկախությունը Իսպանիայից. գլխավոր կապիտան Գաբինո Գաինսան մնաց անցումային վարչակարգի գլխին։ Այսպիսով այսօրվա Գվատեմալայի, Սալվադորի, Հոնդուրասի, Նիկարագուայի և Կոստա Ռիկայի տարածքներում իսպանական տիրապետությունն ավարտվեց։ Շրջանը, կարճ ժամանակ միանալով Մեքսիկական կայսրությանը, 1823 թ. հիմնեց Կենտրոնական Ամերիկայի Միացյալ Նահանգները։", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["Հիմնվեց Նուևա Հելվետիան. Մեքսիկան Սակրամենտոյի հովիտը բացեց բնակեցման համար", "067a1f2a"], "d": ["Շվեյցարացի գաղթական Ջոն Սաթերը մեքսիկական իշխանություններից ստացած թույլտվությամբ և հողային արտոնությամբ Սակրամենտո և Ամերիկան գետերի միախառնման վայրում հիմնեց Նուևա Հելվետիան։ Ամրացված ագարակը դարձավ Մեքսիկայի Ալտա Կալիֆոռնիայի ներքին շրջանների ամենաառաջավոր պահակակետը. 1848 թ. ոսկու հայտնաբերմամբ այն վերածվելու էր Կալիֆոռնիա գաղթի կենտրոնի։", "1c5eab3d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["Ռեցիան և Նորիկումը միացվեցին Հռոմին. Տիբերիոսը և Դրուզուսը գրավեցին Ալպերից անդին", "be6f2a15"], "d": ["Մ.թ.ա. 15 թ. Տիբերիոսն ու Դրուզուսը, հաղթելով ալպյան ցեղերին, ավարտեցին Ռեցիայի նվաճումը (և Նորիկումի բռնակցումը). Դանուբի վերին ափը դարձավ Հռոմի սահման։", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["Ամինտասի մահով Գաղատիան դարձավ հռոմեական նահանգ", "e4250ad7"], "d": ["Երբ Անտոնիոսի նշանակած գաղատական արքա Ամինտասը սպանվեց Կիլիկիայում (մ.թ.ա. 25), Օգոստոսը Գաղատիան վերածեց հռոմեական նահանգի և միավորեց Պիսիդիայի ու Լիկաոնիայի հետ։ Մայրաքաղաքը դարձավ Անկյուրիան (Անկարա). Օգոստոսի «Res Gestae» արձանագրությունը (Monumentum Ancyranum) գրվել է այստեղ։", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["Օկտավիանոսը ստացավ «Օգոստոս» տիտղոսը. սկսվեց պրինցիպատի (կայսրության) շրջանը", "310297b6"], "d": ["27 թ. հունվարի 16-ին Սենատը Օկտավիանոսին շնորհեց Օգոստոս տիտղոսը. Օկտավիանոսը երկար ժամանակով ստանձնեց նահանգների մեծ մասի հրամանատարությունը (imperium)։ Այս ամսաթիվը համարվում է Հռոմեական կայսրության սկիզբը։", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["Մահացավ Բոքքոս II-ը. Մավրիտանիան անցավ Օկտավիանոսի վերահսկողության տակ", "414fa36c"], "d": ["Երբ Բոքքոս II-ը 33 թ. անզավակ մահացավ, Մավրիտանիան Օկտավիանոսի՝ կտակով ժառանգմամբ անցավ հռոմեական կառավարման տակ. որոշ ժամանակ մնաց հռոմեական ուղղակի կառավարման տակ և 25 թ. տրվեց Յուբա II-ին։", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["Անտոնիոսը Արքեղայոսին դարձրեց Կապադովկիայի արքա", "1e83e691"], "d": ["Արևելքը վերակարգավորելիս Անտոնիոսը Կապադովկիայի գահը տվեց Արքեղայոսին. Արքեղայոսը իշխեց, մինչև մ.թ. 17 թ. Տիբերիոսի կողմից Հռոմ կանչվեց։ Կապադովկիան մ.թ. 17 թ. դարձավ հռոմեական նահանգ (այս իրադարձությունը ժամանակագրության մեջ առանձին հոդված է)։", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["Փիլիպպե. Օկտավիանոսն ու Անտոնիոսը հաղթեցին Բրուտոսին և Կասիոսին", "4386016f"], "d": ["42 թ. հոկտեմբերին Փիլիպպեի մոտ տեղի ունեցավ երկու առանձին ճակատամարտ. Կասիոսն ու Բրուտոսը ինքնասպան եղան, և հանրապետական ուժը վերացավ։ Եռապետերը հռոմեական աշխարհը բաժանեցին իրենց միջև։", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["Հուլիոս Կեսարը Կորնթոսը վերահիմնեց որպես հռոմեական գաղութ", "283a5daa"], "d": ["Կեսարի սպանությունից կարճ ժամանակ առաջ Կորնթոսում բնակեցվեցին հռոմեական քաղաքացի գաղութաբնակներ (մեծ մասը ազատագրյալներ). քաղաքը դարձավ Աքայա հռոմեական նահանգի կարևոր կենտրոններից մեկը։ Վերահիմնադրման որոշումը թվագրվում է մ.թ.ա. 44 թ., բնակեցումը՝ մ.թ.ա. 44/43 թթ.։", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["Բուրեբիստան զոհվեց մահափորձի հետևանքով. դակերի թագավորությունը մասնատվեց", "9b9edb14"], "d": ["Ստրաբոնը գրում է, որ Բուրեբիստան Կեսարի մահից առաջ սպանվեց ներքին հեղաշրջմամբ, իսկ թագավորությունը բաժանվեց նախ հինգ, ապա չորս մասի։ Դակիական միությունը մինչև Դեկեբալոս (մ.թ. 87) չվերականգնվեց։", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["Կեսարը սպանվեց Սենատում Մարտի իդեսին (մարտի 15)", "18649074"], "d": ["Ցմահ դիկտատոր հռչակված Կեսարը 44 թ. մարտի 15-ին Պոմպեոսի թատրոնում Սենատի նիստի ժամանակ դաշունահարվեց մի խումբ սենատորների կողմից։ Նրա մահը հիմք նախապատրաստեց նոր քաղաքացիական պատերազմների և Օգոստոսի իշխանության համար։", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["Մունդա. Կեսարը հաղթեց Պոմպեոսի որդիներին", "e1e93362"], "d": ["45 թ. մարտի 17-ին Մունդայում Կեսարը հաղթեց Գնեոս Պոմպեոսի և Սեքստոս Պոմպեոսի բանակին. Իսպանիան մնաց Կեսարի ձեռքում։ Սա քաղաքացիական պատերազմի վերջին խոշոր ճակատամարտն է։", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["Թապսոս. Կեսարը հաղթեց Յուբա I-ին. Արևելյան Նումիդիան դարձավ Africa Nova նահանգ", "77b28c50"], "d": ["Կեսարը 46 թ. գարնանը Թապսոսում ջախջախեց Սկիպիոնի և Յուբա I-ի բանակը. Յուբան ինքնասպան եղավ։ Նումիդիայի արևելյան մասը դարձավ Սալլուստիոսի կառավարած Africa Nova նահանգը, արևմտյան մասը տրվեց Բոքքոսին և Սիտտիուսին։", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["Զելա. Կեսարը հաղթեց Փառնակ II-ին («veni vidi vici»)", "11bf082a"], "d": ["Միհրդատի որդի Փառնակ II-ը, օգտվելով քաղաքացիական պատերազմից, փորձեց ետ վերցնել Պոնտոսը. Կեսարը 47 թ. Զելայում հաղթելով նրան՝ Պոնտոսը վերակարգավորեց հռոմեական վերահսկողության տակ։ Փառնակը փախավ Բոսպորոս և այնտեղ մահացավ։", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["Փարսալոս. Կեսարը հաղթեց Պոմպեոսին", "e821abe8"], "d": ["Դիռախիումի նահանջից հետո Կեսարը Փարսալոսում ջախջախեց Պոմպեոսի ավելի մեծ բանակը։ Պոմպեոսը փախավ Եգիպտոս և սպանվեց. արևելյան նահանգները բացվեցին Կեսարի առջև։", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["Ալեզիա. Կեսարը պաշարեց և հաղթեց Վերցինգետորիքսին, գալլական դիմադրությունը կոտրվեց", "d57cab9f"], "d": ["Մ.թ.ա. 52 թ. արվերն Վերցինգետորիքսի գլխավորած գալլական ապստամբությունը ճնշվեց Կեսարի՝ Ալեզիայի պաշարումով և պաշարողական գծի պաշտպանությամբ. Վերցինգետորիքսը հանձնվեց։ Գալիան հաջորդ տարում ամբողջությամբ անցավ հռոմեական վերահսկողության տակ։", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["Սկսվեց Կեսարի գալլական արշավանքը. հելվետները պարտվեցին", "1e594bb3"], "d": ["Մ.թ.ա. 58 թ. Կեսարը, որպես Ցիզալպյան և Տրանսալպյան Գալիայի կուսակալ, Բիբրակտեի մոտ կանգնեցրեց հելվետների գաղթը. ապա հաղթեց Արիովիստոսի գերմաններին։ Արշավանքը տևելու էր ութ տարի և Գալիան միացնելու Հռոմին։", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["Միհրդատ VI-ը մահացավ Պանտիկապայոնում. Բոսպորոսը մնաց Փառնակին", "0831b871"], "d": ["Պոմպեոսից փախչող Միհրդատը, իր որդի Փառնակի ապստամբության պատճառով, Պանտիկապայոնի ամրոցում ինքնասպան եղավ (63)։ Փառնակը Բոսպորոսը հանձնեց Պոմպեոսին և ճանաչվեց որպես Հռոմի բարեկամ արքա։", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["Պոմպեոսը, միավորելով Բյութանիան և Պոնտոսի արևմուտքը, ստեղծեց Bithynia et Pontus նահանգը", "b2865ea8"], "d": ["Արևելքի կարգավորման ժամանակ (65-63) Պոմպեոսը Բյութանիան միավորելով Պոնտոսի արևմտյան կեսի հետ՝ ստեղծեց Bithynia et Pontus նահանգը. իսկ արևելյան Պոնտոսի ներքին շրջանները տրվեցին տեղական իշխաններին։", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["Պոմպեոսը Կոմմագենեն ճանաչեց Հռոմի բարեկամ և դաշնակից", "a48ba55c"], "d": ["Արևելքի կարգավորման ժամանակ Պոմպեոսը, հաստատելով Անտիոքոս I-ի թագավորությունը և Սելևկիա (Զևգմա) շրջանի մի մասը, Կոմմագենեն դարձրեց հռոմեա-պարթևական դաշնակից միջնագոտի։ Թագավորությունը մ.թ. 17 թ. և վերջնականապես մ.թ. 72 թ. միացվեց հռոմեական նահանգին (այս իրադարձությունները ժամանակագրության մեջ առանձին հոդվածներ են)։", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["Պոմպեոսը հաղթեց Միհրդատին. Պոնտոսը կապվեց Հռոմին", "8f3f50a6"], "d": ["Պոմպեոսը 66 թ. Լյուկոս գետի հարթավայրում գիշերը ջախջախեց Միհրդատի բանակը. Միհրդատը Կոլխիդայից փախավ Բոսպորոս։ Պոնտոսի ծովափնյա քաղաքներն անցան հռոմեական վերահսկողության տակ, և 63 թ. ստեղծվեց Բյութանիայի հետ միավորված նահանգ։", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["Անտիոքոս I Թեոսը գահ բարձրացավ Կոմմագենեում", "b1680d3f"], "d": ["Կոմմագենեի արքա Անտիոքոս I-ը կառուցել տվեց պարսկական և մակեդոնական տոհմերը միավորող Նեմրութ լեռան դամբարան-տաճարը։ Թագավորությունը միջնագոտի էր Հռոմի և Պարթևաստանի միջև։", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["Կյուրենեն դարձավ հռոմեական նահանգ (Կյուրենայկա)", "f9993ffb"], "d": ["Պտղոմեոս Ապիոնի՝ իր թագավորությունը Հռոմին կտակելուց (96) քսան տարի անց Հռոմը Կյուրենայկան մտցրեց նահանգային կարգի մեջ. 67 թ. միավորվեց Կրետեի հետ։", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["Նիկոմեդես IV-ը իր թագավորությունը կտակեց Հռոմին", "e29d9fbc"], "d": ["Նիկոմեդես IV-ի մահով (75/74) Բյութանիան կտակով մնաց հռոմեական ժողովրդին. Միհրդատ VI-ը դա չընդունեց, և սկսվեց Երրորդ Միհրդատյան պատերազմը։ Բյութանիան վերածվեց Հռոմի ուղղակի նահանգի։", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["Բուրեբիստան միավորեց դակական և գետական ցեղերը", "3648f92e"], "d": ["Ըստ Ստրաբոնի՝ Բուրեբիստան գետերին և դակերին հավաքեց մեկ թագավորության մեջ և Դանուբից հարավ արշավանքներ ձեռնարկեց մինչև Թրակիայի և Իլլիրիայի սահմանները։ Թագավորությունը Դանուբի երկայնքով սկսեց սպառնալիք դառնալ Հռոմի համար։", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["Դարդանոսի հաշտություն. Միհրդատը ետ քաշվեց Ասիայից և Բյութանիայից", "535818ed"], "d": ["Սուլլայի հետ կնքված Դարդանոսի հաշտությամբ Միհրդատը համաձայնեց դատարկել իր բոլոր նվաճումները (Ասիա, Բյութանիա, Կապադովկիա, Պափլագոնիա), տալ 70 նավ և 2000-3000 տաղանդ։ Սակայն Հռոմում Սուլլայի թշնամիների գերակշռությունը հանգեցրեց Երկրորդ Միհրդատյան պատերազմին։", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["Միհրդատը ներխուժեց Ասիա նահանգ. Եփեսոսյան վեսպերներ (80.000 հռոմեացիների կոտորած)", "3986833b"], "d": ["Առաջին Միհրդատյան պատերազմի սկզբում (89/88) Միհրդատը ներխուժեց Բյութանիա և Ասիա նահանգ, Եփեսոսում տրված նրա հրամանով հռոմեական քաղաքացիները զանգվածաբար սպանվեցին։ Աթենքն էլ անցավ Պոնտոսի կողմը (Արիստիոն)։", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia. Հռոմը քաղաքացիություն տվեց իտալական դաշնակիցներին (Դաշնակցային պատերազմ)", "f72ba27d"], "d": ["Հռոմի իտալական դաշնակիցների ապստամբության (91-88) առիթով Lex Iulia-ն (90) և Lex Plautia Papiria-ն (89) հավատարիմ մնացած և անձնատուր եղած դաշնակիցներին շնորհեցին հռոմեական քաղաքացիություն։ Այսպիսով Իտալական թերակղզին մինչև Պո գետը դարձավ քաղաքացիական մեկ հասարակություն։", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["Սուլլան Արիոբարզանեսին գահ նստեցրեց Կապադովկիայում", "8bdd078c"], "d": ["Ի պատասխան այն բանի, որ Միհրդատ VI-ը Կապադովկիան իր ձեռքում էր պահում մանուկ արքայի միջոցով, Հռոմը Սուլլայի՝ Կիլիկիայի կուսակալության ժամանակ Արիոբարզանեսին հռչակել տվեց արքա։ Կապադովկիան հաջորդ դարում դարձավ հռոմեա-պարսկա-պոնտական պայքարի միջնագոտի։", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["Պտղոմեոս Ապիոնը Կյուրենեն կտակեց Հռոմին", "5edef477"], "d": ["Կյուրենեն կառավարող Պտղոմեոս Ապիոնը անզավակ մահանալով իր թագավորությունը թողեց հռոմեական ժողովրդին (96). Սենատը քաղաքները թողեց ազատ, իսկ նահանգի վերածելու գործը Հռոմը հետաձգեց մինչև 74 թ.։", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["Բոքքոսը Յուգուրտային հանձնեց Հռոմին. Նումիդիայի արևմուտքը միացվեց Մավրիտանիային", "7619ad15"], "d": ["Յուգուրտայի աները՝ Մավրիտանիայի արքա Բոքքոս I-ը, Յուգուրտային հանձնելով Սուլլային, հաշտվեց Հռոմի հետ. դրա դիմաց Նումիդիայի արևմտյան մասը թողնվեց իրեն։ Յուգուրտան 104 թ. մահացավ Հռոմի բանտում։", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["Պերիսադ V-ը թագավորությունը թողեց Միհրդատ VI-ին. Բոսպորոսը կապվեց Պոնտոսին", "835bbe74"], "d": ["Սկյութական ճնշման տակ գտնվող Պերիսադ V-ը Միհրդատի հրամանատար Դիոփանտոսի օգնությամբ թագավորությունը փոխանցեց Միհրդատին. այսպիսով Բոսպորոսը դարձավ Պոնտոսի հյուսիսային շարունակությունը։ Սևծովյան հացահատիկի առևտուրը, որպես Միհրդատի աղբյուր, այս ժամանակ անցավ Պոնտոսին։", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["Միհրդատի հրամանատար Դիոփանտոսը Ղրիմում հաղթեց սկյութներին", "d8d48c68"], "d": ["Դիոփանտոսը հաղթեց սկյութ արքա Սկիլուրոսի որդի Պալակոսի բանակը և Տավրիկայում վերցրեց Նեապոլիսի շրջակայքը. Բոսպորոսն ու Խերսոնեսը կապվեցին Պոնտոսին։", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["Յուգուրտան վերցրեց Ցիրտան. Հռոմը միջամտեց Նումիդիայի գործերին", "660eb34a"], "d": ["Մ.թ.ա. 112 թ. Յուգուրտան պաշարեց Ցիրտան և սպանեց Ադհերբալին. քաղաքում սպանված իտալացի վաճառականները Հռոմին մղեցին պատերազմ հայտարարել Յուգուրտային։ Պատերազմը տևեց մինչև 105 թ.։", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["Հիմնադրվեց Narbo Martius-ը. Հարավային Գալիան (Gallia Transalpina) դարձավ հռոմեական նահանգ", "20c4bdfa"], "d": ["Մասալիայի օգնության կանչով (125) Գալիա մտած Հռոմը Aquae Sextiae-ի (122) և ալոբրոգների նկատմամբ հաղթանակներով գրավեց Ռոնի հովիտը. մ.թ.ա. 118 թ. Narbo Martius-ը որպես առաջին հռոմեական գաղութ հիմնվեց Գալիայում։ Շրջանը դարձավ Gallia Transalpina նահանգը։", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["Միհրդատ VI Եվպատորը գահ բարձրացավ Պոնտոսում", "c2d5fd41"], "d": ["Միհրդատ V-ի մահով (120/119) մանուկ հասակում գահ բարձրացած Միհրդատ VI-ը մի քանի տարվա խնամակալությունից հետո Պոնտոսը Սևծովյան շրջանում հասցրեց Հռոմին մրցակից ուժի։", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["Մասալիայի կանչով Հռոմը մտավ Գալիա", "eaf7eb0a"], "d": ["Երբ սալլուվիների և լիգուրների ճնշման տակ գտնվող Մասալիան Հռոմից օգնություն խնդրեց, Հռոմը 125 թ. բանակ ուղարկեց Հարավային Գալիա։ Այս միջամտությունը հանգեցրեց Narbo Martius-ի հիմնադրմանը (118) և Gallia Transalpina-ի գրավմանը։", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["Արիստոնիկոսը պարտվեց. Պերգամոնի հողերից ստեղծվեց Ասիա նահանգը", "7ccdc59e"], "d": ["Եվմենես III անվամբ գահի հավակնող Արիստոնիկոսը պարտվեց հռոմեական բանակից և գերվեց (129). Մանիուս Ակվիլիուսի կարգավորմամբ նախկին Պերգամոնի թագավորությունը դարձավ Ասիա նահանգ։ Նահանգի հարկային համակարգը (publicani) Հռոմի եկամուտի մեծ աղբյուր էր։", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["Նումանտիան ընկավ. Կելտիբերիան միացվեց Հռոմին", "ced07244"], "d": ["Սկիպիոն Էմիլիանոսը ութամսյա պաշարումից հետո սովով ստիպեց Նումանտիային հանձնվել (133). քաղաքը ավերվեց։ Կելտիբերական պատերազմներն ավարտվեցին, և Hispania Citerior-ի ներքին շրջանը միացվեց Հռոմին։", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["Աքայական պատերազմ. Աքայական միությունը պարտվեց Հռոմին, միությունները ցրվեցին", "e434cfe0"], "d": ["Սպարտայի հետ սահմանային վեճի պատճառով Հռոմի դեմ ապստամբած Աքայական միությունը 146 թ. պարտվեց Լեվկոպետրայում. Կորնթոսը ավերվեց, միությունը փաստացի ցրվեց, և Հունաստանի մի մասը մտավ Մակեդոնիա նահանգի հսկողության տակ։", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["Երրորդ Պունիկյան պատերազմն ավարտվեց. Կարթագենը ավերվեց, ստեղծվեց Africa նահանգը", "522515b4"], "d": ["Երեք տարվա պաշարումից հետո Պ. Կոռնելիոս Սկիպիոն Էմիլիանոսը 146 թ. գարնանը վերցրեց Կարթագենը. քաղաքն այրվեց ու ավերվեց, հողերը միացվեցին Հռոմին։ Կարթագենի ներքին շրջանը դարձավ Africa նահանգ. Մասինիսայի Նումիդիան մնաց արևմտյան հարևան։", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["Մակեդոնիան դարձավ հռոմեական նահանգ", "dc6d2352"], "d": ["Անդրիսկոսի ապստամբության (148) ճնշումից հետո Մակեդոնիայի չորս շրջանները միավորվեցին մեկ հռոմեական նահանգում (146). նահանգից հարավ Հունաստանի վերահսկողությունը նույնպես թողնվեց Մակեդոնիայի կուսակալի հսկողությանը։ Հետագա տարիներին Via Egnatia-ն կառուցվեց Ադրիատիկից մինչև Սալոնիկ։", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["Անդրիսկոսի ապստամբությունը. Մակեդոնիայի թագավորությունը կարճ ժամանակով վերահիմնվեց, Մետելլոսը ճնշեց այն", "0119ff73"], "d": ["Պերսեսի որդին լինելը հավակնող Անդրիսկոսը 150/149 թթ. վերամիավորեց Մակեդոնիան և հաղթեց հռոմեական առաջին ուժերին. 148 թ. Մետելլոսը ետ վերցրեց Մակեդոնիան։ Ապստամբությունը դարձավ Մակեդոնիան Հռոմի ուղղակի կառավարմանը կապելու պատճառը։", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["Հռոմը պատերազմ հայտարարեց Կարթագենին. սկսվեց Երրորդ Պունիկյան պատերազմը", "2e34c235"], "d": ["Մասինիսայի հարձակումներից Կարթագենի ինքնապաշտպանությունը համարվեց պայմանագրի խախտում. Հռոմը 149 թ. պատերազմ հայտարարեց և իր կողմը գրավեց Ուտիկան։ Կարթագեն քաղաքը երեք տարի դիմադրեց պաշարման տակ։", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["Մասինիսան հարձակվեց Կարթագենի հողերի վրա. նումիդա-կարթագենյան պատերազմ", "b47559a5"], "d": ["Մասինիսայի՝ Կարթագենի հողերի գրավման (151/150) առիթով Կարթագենը պատերազմ սկսեց և պարտվեց Մասինիսային. Հռոմը դա համարելով պայմանագրի խախտում՝ 149 թ. պատերազմ հայտարարեց։ Մասինիսան 148 թ. իննսուն տարեկանում մահացավ։", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["Հռոմը հրամայեց Հռոդոսին ետ կանչել կուսակալներին Լիկիայից և Կարիայից. Լիկիական միությունը (Պատարա) դուրս եկավ Հռոդոսի իշխանությունից", "6bbe2b54"], "d": ["Մակեդոնական III պատերազմից հետո հռոմեական Սենատը հրամայեց Հռոդոսին մինչև որոշակի օր ետ կանչել իր կուսակալներին Լիկիայից և Կարիայից. Հռոդոսը այս կորուստները համարեց պատերազմի սպառնալիքից թեթև և ընդունեց։ Լիկիական միությունը (կենտրոնը՝ Պատարա) այսպիսով դուրս եկավ Հռոդոսի իշխանությունից և շարունակեց գոյությունը որպես հռոմեական հովանավորության տակ գտնվող Լիկիական միություն։", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["Էպիրոսը կողոպտվեց Հռոմի կողմից. ավերվեց յոթանասուն քաղաք", "456fb461"], "d": ["Մակեդոնական III պատերազմից հետո Էպիրոսի՝ Պերսեսին մոտ մնացած մոլոսական քաղաքները Էմիլիոս Պավլոսի հրամանով կողոպտվեցին, մոտ 150.000 մարդ ստրկացվեց։ Էպիրոսը հաջորդ դարում հռոմեական իշխանության տակ մնաց աղքատ։", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["Հռոմը Մակեդոնիան բաժանեց չորս ինքնավար շրջանի (մերիդեր)", "7a795ba0"], "d": ["Սենատի որոշմամբ (մ.թ.ա. 167) Մակեդոնիայի թագավորությունը բաժանվեց չորս շրջանի՝ Ամփիպոլիս, Թեսալոնիկե (Սալոնիկ), Պելլա և Պելագոնիա կենտրոններով. շրջանների միջև արգելվեցին ամուսնությունը և սեփականության ձեռքբերումը, սահմանափակվեց հանքերի շահագործումը։", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["Հռոմը Լիկիան և Կարիան վերցրեց Հռոդոսից. Դելոսը հռչակվեց ազատ նավահանգիստ", "09c8143f"], "d": ["Երրորդ Մակեդոնական պատերազմում Հռոդոսի՝ Հռոմի և Պերսեսի միջև միջնորդելու փորձը պատժվեց. Սենատը Լիկիան և Կարիան վերցրեց Հռոդոսից և հռչակեց ազատ, Դելոսը տվեց Աթենքին և դարձրեց անմաքս նավահանգիստ։ Հռոդոսի առևտրական եկամուտը խիստ անկում ապրեց։", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["Պիդնա. Էմիլիոս Պավլոսը հաղթեց Պերսեսին. Անտիգոնյան թագավորությունն ավարտվեց", "a59c5270"], "d": ["168 թ. հունիսի 22-ին Պիդնայում հռոմեական լեգեոնները, հաղթելով մակեդոնական ֆալանգին, ավարտեցին Մակեդոնական III պատերազմը. Պերսեսը հանձնվեց Սամոթրակեում և տարվեց Հռոմ՝ հաղթական թափորին։ Անտիգոնյան հարստությունն ավարտվեց։", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["Ապամեայի հաշտություն. Եվմենես II-ը Պերգամոնին ձեռք բերեց Թրակիական Խերսոնեսը, Փռյուգիայի, Լիդիայի և Միսիայի մեծ մասը", "f25ed9af"], "d": ["Մագնեզիայում պարտությունից հետո Անտիոքոս III-ը 188 թ. հաշտություն կնքեց Հռոմի հետ. թողեց Տավրոսի լեռներից հյուսիս ընկած հողերը։ Այս հողերի մեծ մասը տրվեց դաշնակից Եվմենես II-ի Պերգամոնին (Թրակիական Խերսոնես, Մեծ Փռյուգիա, Լիդիա, Միսիա, Իոնիայի մի մասը)։", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["Ապամեայի հաշտություն. Հռոդոսն ստացավ Լիկիան և Կարիայի հարավը", "aa5173c6"], "d": ["Մագնեզիայից հետո Հռոմը դաշնակից Հռոդոսին տվեց Լիկիան և Կարիայի՝ Մեանդրոսից հարավ ընկած մասը։ Հռոդոսը այս հողերը կորցրեց 167 թ.։", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["Մանլիոս Վուլսոն հաղթեց գաղատական ցեղերին. գաղատների անկախությունն անցավ հռոմեական հսկողության տակ", "30ae73d7"], "d": ["Մագնեզիայից հետո Գն. Մանլիոս Վուլսոն ներխուժեց գաղատների երկիր և Օլիմպոսում ու Մագաբայում ջախջախեց տոլիստոագներին և տեկտոսագներին. պայմանագրով գաղատները համաձայնեցին չհարձակվել հարևանների վրա։ Գաղատիան հիմնականում մնաց անկախ, բայց կապվեց հռոմեա-պերգամոնյան հավասարակշռությանը։", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["Էտոլիան հաշտություն կնքեց Հռոմի հետ. կորցրեց Ամբրակիան և Ենիադան, ճանաչեց Հռոմի գերիշխանությունը", "f332c6bf"], "d": ["Անտիոքոսյան պատերազմում Անտիոքոսի կողմն անցած Էտոլիան Ֆուլվիոս Նոբիլիորի՝ Ամբրակիայի պաշարումից հետո հաշտություն կնքեց Հռոմի հետ. ճանաչեց Հռոմի «մեծությունը», վճարեց ռազմատուգանք և թողեց Ամբրակիայի ու Ենիադայի նման քաղաքներ։", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["Magnesia ad Sipylum. Հռոմն ու Պերգամոնը հաղթեցին Անտիոքոս III-ին", "f650ef21"], "d": ["190/189 թթ. ձմռանը Մագնեզիայում Լ. Սկիպիոնը և Եվմենես II-ը ջախջախեցին Անտիոքոս III-ի բանակը։ Հաղթանակից հետո կնքված Ապամեայի հաշտությունը (188) հանգեցրեց Անտիոքոսի՝ Տավրոսից հյուսիս ընկած տարածքը թողնելուն։", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["Սպարտան միացավ Աքայական միությանը. Ֆիլոպեմենը Նաբիսից հետո Լակոնիան կապեց միությանը", "2629b6e1"], "d": ["Սպարտացի բռնակալ Նաբիսի սպանությունից (192) հետո աքայական ստրատեգոս Ֆիլոպեմենը Սպարտան բռնի միացրեց Աքայական միությանը։ Սպարտան իր անկախությունը լիովին կորցրեց 188 թ.՝ պարիսպների քանդմամբ։", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["Ֆլամինինոսը Իսթմոսյան խաղերում հռչակեց հույների ազատությունը", "3d850bf2"], "d": ["Կինոսկեֆալեից հետո հռոմեական հրամանատար Տ. Քվինկտիուս Ֆլամինինոսը մ.թ.ա. 196 թ. Իսթմոսյան խաղերում հռչակեց, որ Կորնթոսի, Քալկիդայի և Դեմետրիասի մակեդոնական կայազորները կդուրս բերվեն, և հունական քաղաքները «ազատ են, անհարկ և ենթակա սեփական օրենքներին»։ Այսպիսով Հռոմը հաստատվեց Հունաստանում որպես իրավարար։", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["Կինոսկեֆալե. Հռոմը հաղթեց Փիլիպոս V-ին. Մակեդոնիան ստիպված եղավ դուրս գալ Հունաստանից", "9cb44ca6"], "d": ["197 թ. հունիսին Ֆլամինինոսի հռոմեական լեգեոնները Կինոսկեֆալեում ջախջախեցին մակեդոնական ֆալանգը։ 196 թ. հաշտությամբ Փիլիպոսը թողեց Հունաստանում իր բոլոր դիրքերը (Դեմետրիաս, Քալկիդա, Կորնթոս), հանձնեց նավատորմը և վճարեց 1000 տաղանդ։", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["Իսպանիայում ստեղծվեց երկու հռոմեական նահանգ՝ Citerior և Ulterior", "1baa8383"], "d": ["Կարթագենից վերցրած իսպանական հողերը 197 թ. առաջին անգամ բաժանվեցին երկու առանձին նահանգի, և յուրաքանչյուրը կառավարվում էր մեկ պրետորով։ Այդ ժամանակից սկսած թերակղզու կելտիբերական և լուսիտանական պատերազմները մղվեցին հռոմեական նահանգային կարգն ընդլայնելու համար։", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["Զամայից հետո հաշտություն. Կարթագենը կորցրեց Իսպանիան, Միջերկրականի կղզիները, նավատորմը և ստանձնեց 10.000 տաղանդ ռազմատուգանք", "8654422d"], "d": ["Զամայից (202) հետո Հռոմը Կարթագենը սեղմեց Աֆրիկայի իր սեփական հողերում. ընդունվեցին Իսպանիան և Միջերկրականի կղզիները թողնելու, նավատորմը (բացի 10 նավից) հանձնելու, 50 տարի 10.000 տաղանդ վճարելու և առանց Հռոմի թույլտվության պատերազմ չսկսելու պայմանները։ Մասինիսայի Նումիդիան դարձավ անկախ հարևան։", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["Հռոմը Մասինիսային պարգևատրեց Սիֆաքսի թագավորությամբ", "54ba7a64"], "d": ["Զամայի հաշտությամբ Հռոմը Մասինիսային նշանակեց Սիֆաքսի թագավորությանը և Կարթագենից վերցրած սահմանային հողերին. Մասինիսայի՝ «Էմպորիա» շրջանի և Կարթագենի սահմանի նկատմամբ պահանջները հետագայում դարձան պատերազմի պատճառ։", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["Զամա. Սկիպիոնն ու Մասինիսան հաղթեցին Հաննիբալին", "52e188e6"], "d": ["Հաննիբալի՝ Աֆրիկա կանչվելուց հետո տեղի ունեցած Զամայի ճակատամարտում Սկիպիոնի լեգեոնները և Մասինիսայի նումիդական հեծելազորը հաղթեցին կարթագենյան բանակը։ Երկրորդ Պունիկյան պատերազմը այս ճակատամարտով վերջնականապես ավարտվեց Հռոմի օգտին։", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["Սիֆաքսը պարտվեց և գերվեց. Մասինիսան միավորեց Նումիդիան", "a42a3cb0"], "d": ["Սկիպիոնն ու Մասինիսան 203 թ. հաղթեցին Սիֆաքսի բանակը և գերեցին Սիֆաքսին. Մասինիսան Հռոմի աջակցությամբ գրավեց Ցիրտան և Սիֆաքսի թագավորությունը։ Նումիդիան արևելյան և արևմտյան մասերի միավորմամբ դարձավ հզոր թագավորություն։", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["Իլիպա և Գադես. Իսպանիան Կարթագենից անցավ Հռոմին", "31e5a50c"], "d": ["Սկիպիոնը 206 թ. Իլիպայում հաղթելով Հասդրուբալ Գիսգոյի և Մագոնի բանակը՝ վերջ դրեց Իսպանիայում կարթագենյան վերահսկողությանը. կարճ ժամանակ անց Գադեսն էլ անցավ Հռոմին։ Կարթագենը կորցրեց իսպանական արծաթի հանքերը և զինվորների աղբյուրը։", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["Ֆաբիոս Մաքսիմոսը Հաննիբալից ետ վերցրեց Տարենտը", "bd605091"], "d": ["212 թ. Հաննիբալին հանձնված Տարենտը 209 թ. դավաճանությամբ անցավ Ք. Ֆաբիոս Մաքսիմոսին։ Քաղաքի անկմամբ Հաննիբալը կորցրեց Հարավային Իտալիայում իր ամենաարժեքավոր նավահանգիստը։", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["Կապուան անցավ Հռոմին. Հաննիբալը կորցրեց Կամպանիայի հենակետը", "cfcb9c9a"], "d": ["Կաննեից հետո Հաննիբալի կողմն անցած Կապուան երկու տարի պաշարած Հռոմը, չնայած Հաննիբալի դեպի Հռոմ երթի փորձին, վերցրեց քաղաքը և խստորեն պատժեց. Կապուայի ինքնավարությունը վերացվեց։ Հաննիբալը Հարավային Իտալիայում անցավ պաշտպանության։", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["Կաննե. Հաննիբալը շրջապատելով ոչնչացրեց հռոմեական բանակը. Հարավային Իտալիան սկսեց անցնել Կարթագենին", "94f5110a"], "d": ["216 թ. Ապուլիայի Կաննեում Հաննիբալի շրջապատման մարտակարգը ոչնչացրեց մոտ յոթանասուն հազարանոց հռոմեական բանակը։ Կապուան, Տարենտը և Հարավային Իտալիայի բազմաթիվ քաղաքներ անցան Կարթագենի շարքերը։", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["Հռոմեական բանակը ափ իջավ Իսպանիայում. առաջին հռոմեական հենակետը՝ Էմպորիոնում", "8cb47853"], "d": ["Հաննիբալի՝ Իտալիա արշավելուց հետո Գն. Կոռնելիոս Սկիպիոնը մ.թ.ա. 218 թ. ափ իջնելով Էմպորիոնում՝ սկիզբ դրեց Էբրոյի երկայնքով Իսպանիայում Հռոմի ներկայությանը. թերակղզին դարձավ Երկրորդ Պունիկյան պատերազմի երկրորդ ճակատը։", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["Հաննիբալը, անցնելով Ալպերը, մտավ Իտալիա", "a1d3bf5a"], "d": ["Հաննիբալը անցավ Էբրոն, Պիրենեյները և Ռոնը, աշնանը հաղթահարեց Ալպերը և իջավ Հյուսիսային Իտալիա. Տիցինուսում և Տրեբիայում հաղթեց հռոմեական բանակներին։ Այսպիսով Կարթագենի իտալական պատերազմի կենտրոնը տեղափոխվեց Հռոմի ներս։", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["Հաննիբալը վերցրեց Սագունտը. վառվեց Երկրորդ Պունիկյան պատերազմի պատրույգը", "a497a334"], "d": ["Հաննիբալը ութամսյա պաշարումից հետո վերցրեց Հռոմի դաշնակից Սագունտը (մ.թ.ա. 219). Հռոմը դեսպան ուղարկելով պահանջեց Հաննիբալի հանձնումը և մերժվելուց հետո պատերազմ հայտարարվեց։ Պատերազմը Իտալիայում, Իսպանիայում և Աֆրիկայում տևեց տասնյոթ տարի։", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["Սելլասիա. Անտիգոնոս Դոսոնը հաղթեց Կլեոմենեսին. Սպարտան առաջին անգամ ենթարկվեց օտար օկուպացիայի", "dc64a8db"], "d": ["222 թ. ամռանը Սելլասիայում մակեդոնա-աքայական դաշինքը հաղթեց Կլեոմենեսի սպարտական բանակը. Կլեոմենեսը փախավ Եգիպտոս։ Դոսոնը մտավ Սպարտա և վերադարձրեց այն Լիկուրգոսի կարգին. սպարտացիներն իրենց պատմության մեջ առաջին անգամ ապրեցին օտար բանակի օկուպացիա։", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["Մեդիոլանումը (Միլան) անցավ Հռոմին. ինսուբրները պարտվեցին, Հյուսիսային Իտալիան բացվեց Հռոմի առջև", "d3ec639f"], "d": ["Տելամոնում (225) գալլերին հաղթած Հռոմը մ.թ.ա. 222 թ. Կլաստիդիումում Մարկելլոսի հաղթանակով և Մեդիոլանումի գրավմամբ իր վերահսկողության տակ առավ Պո գետի հարթավայրի մեծ մասը։ Շրջանը կազմակերպվեց որպես Ցիզալպյան Գալիա։", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["Աքայական միությունը Ակրոկորնթոսը տվեց Անտիգոնոս Դոսոնին. Կորնթոսը վերադարձավ Մակեդոնիային", "c8ec9d0c"], "d": ["Կլեոմենես III-ի ճնշման տակ գտնվող Աքայական միությունը Արատոսի միջոցով օգնություն խնդրեց Մակեդոնիայից և Ակրոկորնթոսն ու Կորնթոսը հանձնեց Անտիգոնոս Դոսոնին. Դոսոնը հիմնեց Հելլենական միությունը (Hellenikos symmachia)։", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["Էբրոյի պայմանագիր. Կարթագենը համաձայնեց չանցնել Էբրոյից հյուսիս", "a199de0b"], "d": ["Համիլկարի սկսած իսպանական նվաճումը շարունակող Հասդրուբալը Հռոմի հետ կնքեց Էբրոյի պայմանագիրը. Կարթագենը զինված չպետք է անցներ Էբրոն։ Հաննիբալի՝ 219 թ. Սագունտի վրա հարձակումը հիմնավորվեց այս պայմանագրի մեկնաբանությամբ։", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["Հռոմը Սարդինիան և Կորսիկան վերցրեց Կարթագենից", "4f7295ee"], "d": ["Երբ Կարթագենի՝ Սարդինիայում ապստամբած վարձկանները օգնություն խնդրեցին Հռոմից, Հռոմը գրավեց կղզին. Կարթագենը, պատերազմի սպառնալիքի տակ, ստիպված եղավ թողնել կղզիները և լրացուցիչ 1200 տաղանդ վճարել։ Հռոմը ստեղծեց իր երկրորդ նահանգը (Sardinia et Corsica)։", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["Էգատյան կղզիներ. կարթագենյան նավատորմը ոչնչացվեց. Սիցիլիան դարձավ Հռոմի առաջին նահանգը", "8bd16e8f"], "d": ["Լուտատիոս Կատուլոսը 241 թ. մարտին Էգատյան կղզիների մոտ ջախջախեց Հաննոնի կարթագենյան նավատորմը. ապա Լուտատիոսի հաշտությամբ Կարթագենը դատարկեց Սիցիլիան և համաձայնեց վճարել 3200 տաղանդ ռազմատուգանք։ Սիցիլիան (բացի Հիերոնի Սիրակուզայից) դարձավ Հռոմի առաջին նահանգը։", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["Արատոսը գրոհեց Ակրոկորնթոսը. Կորնթոսը Մակեդոնիայից անցավ Աքայական միությանը", "a88dfda6"], "d": ["Սիկիոնցի Արատոսը գիշերային հարձակմամբ չեզոքացրեց Անտիգոնոս Գոնատասի Ակրոկորնթոսի կայազորը և Կորնթոսը միացրեց Աքայական միությանը. Մեգարան, Տրոյզենը և Էպիդավրոսը նույնպես անցան միությանը։ Մակեդոնիան Պելոպոնեսում կորցրեց իր բանալի-ամրոցը։", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["Արատոսը Սիկիոնը միացրեց Աքայական միությանը", "6f413f9c"], "d": ["Երիտասարդ Արատոսը տապալելով Սիկիոնի բռնակալին՝ քաղաքը կապեց Աքայական միությանը. այս քայլը միությունը տարածեց Կորնթոսյան ծոցի հյուսիսային և հարավային ափերին և Արատոսին հասցրեց ստրատեգոսի ընտրությանը։", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["Հիերոն II-ը դաշինք կնքեց Հռոմի հետ. Արևելյան Սիցիլիան դարձավ Հռոմի դաշնակից", "5e95a134"], "d": ["Առաջին Պունիկյան պատերազմի սկզբում Հիերոնը Մեսսանայի հարցի պատճառով դաշինք էր կնքել Կարթագենի հետ Հռոմի դեմ. 263 թ. նա հաշտություն և դաշինք հաստատեց Հռոմի հետ և մինչև կյանքի վերջը (մինչև 215) մնաց Հռոմի հավատարիմ դաշնակիցը։ Սիրակուզան դարձավ հռոմեական Սիցիլիայի նահանգից դուրս մնացած դաշնակից պետությունը։", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["Նիկոմեդես I-ը հիմնեց Նիկոմեդիան (Իզմիթ)", "a89ed42a"], "d": ["Նիկոմեդեսը Աստակոսի կործանումից հետո ծոցի արևելյան ծայրում հիմնեց Նիկոմեդիան. քաղաքը հետագա դարերում դարձավ Բյութանիայի և Դիոկղետիանոսի ժամանակ Հռոմի արևելյան մայրաքաղաքի կենտրոնը։", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["Սկսվեց Առաջին Պունիկյան պատերազմը. Ապիոս Կլավդիոսը անցավ Մեսսանա", "636e1533"], "d": ["Երբ մամերտինները Սիրակուզայի արքա Հիերոնի դեմ Մեսսանայի համար Կարթագենից հետո օգնություն խնդրեցին նաև Հռոմից, հռոմեական հյուպատոս Ապիոս Կլավդիոս Կաուդեքսը 264 թ. անցավ Սիցիլիա և Մեսսանան վերցրեց կարթագենյան կայազորից։ Այսպիսով Հռոմն առաջին անգամ պատերազմի մեջ մտավ Իտալիայից դուրս։", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["Վոլսինիան ընկավ. Էտրուրիայի վերջին անկախ մեծ քաղաքն անցավ Հռոմին", "b6aed092"], "d": ["Ստրուկների ապստամբության պատճառով Հռոմի օգնությանը դիմած Վոլսինիան Հռոմը 264 թ. գրավեց և նրա բնակիչներին տեղափոխեց նոր վայր։ Դրանից հետո Էտրուրիան փաստացի անցավ հռոմեական իշխանության տակ։", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["Պյուռոսը մահացավ Արգոսում", "2b4996fa"], "d": ["Պելոպոնեսյան արշավանքի ժամանակ Արգոսի փողոցային մարտում Պյուռոսը կղմինդրից վիրավորվելով մահացավ (272)։ Էպիրոսը կորցրեց իր կշիռը Մակեդոնիայի դեմ և վերականգնեց հարաբերությունները Հռոմի հետ։", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["Տարենտը հանձնվեց Հռոմին. Հարավային Իտալիան միացվեց Հռոմին", "6e87c924"], "d": ["Պյուռոսի մեկնումից հետո Տարենտի էպիրյան կայազորը ետ քաշվեց, և քաղաքը հանձնվեց Հռոմին (272)։ Բրուտտիումի և Լուկանիայի հետ Հարավային Իտալիայի հունական քաղաքները դարձան Հռոմի դաշնակիցները. այսպիսով Հռոմը դարձավ Իտալական թերակղզու տիրակալը մինչև Պո գետի հարթավայրը։", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["Մալեվենտում (Բենեվենտում). Պյուռոսը ետ քաշվեց Իտալիայից", "ab67e9f5"], "d": ["Սիցիլիական արշավանքից վերադարձած Պյուռոսի՝ Հռոմի վրա կրկին հարձակումը Մալեվենտումում Մանիուս Կուրիոս Դենտատոսի առջև ձախողվեց. Պյուռոսը 275 թ. վերադարձավ Էպիրոս։ Տարենտում թողեց փոքր կայազոր. Հռոմը Իտալիայում մնաց առանց մրցակցի։", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["Անտիոքոս I-ը «փղերի պատերազմում» հաղթեց գաղատներին", "1e88c2d0"], "d": ["Անտիոքոս I-ը, իր փղերով հաղթելով գաղատներին, ստացավ Սոտեր («փրկիչ») մականունը. գաղատները վերադարձան Կենտրոնական Անատոլիայում հաստատված խարաջի և արշավանքների կարգին։ Հետագա դարերում շարունակվեցին բախումները Պերգամոնի և Բյութանիայի հետ։", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["Անտիգոնոս Գոնատասը դարձավ Մակեդոնիայի արքա. Անտիգոնյան հարստությունը կայունացավ", "4b907dd6"], "d": ["Գոնատասը, 277 թ. Լիսիմաքիայում հաղթելով գաղատներին, փառք ձեռք բերեց և 276 թ. հաստատվեց Մակեդոնիայի գահին։ Հարստությունը մինչև 168 թ. կառավարեց Մակեդոնիան. Հունաստանում իր ձեռքում պահեց Կորնթոսի, Քալկիդայի և Պիրեոսի ամրոցները։", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["Նիկոմեդես I-ը գաղատներին անցկացրեց Անատոլիա", "9e5ab10b"], "d": ["Բյութանիայի արքա Նիկոմեդես I-ը իր եղբայր Զիպոյտեսի և Սելևկյան ճնշման դեմ գաղատական (կելտ) ցեղերին Բոսֆորով անցկացրեց և վերցրեց իր ծառայության մեջ. գաղատները հետագայում հաստատվեցին Կենտրոնական Անատոլիայում. տեկտոսագների ճյուղը Անկարան (Անկյուրիա) դարձրեց մայրաքաղաք (TDV «Ankara». «մ.թ.ա. 278-189 թվականների միջև դարձավ Թրակիայից եկած գաղատների տեկտոսագների ճյուղի մայրաքաղաքը»)։ Անցման տարեթիվը 278/277 է։", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["Էտոլիական միությունը պաշտպանեց Դելֆին գաղատական արշավանքից", "5488966a"], "d": ["Բրեննոսի գաղատական բանակը, անցնելով Թերմոպիլեն, առաջացավ դեպի Դելֆի. էտոլիացիների և փոկիսցիների դիմադրությունը ցրեց արշավանքը։ Այս հաղթանակով Դելֆյան ամփիկտիոնիայում Էտոլիայի կշիռը մեծացավ։", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["Պյուռոսը Տարենտին օգնելու անցավ Իտալիա. Հերակլեայում հաղթեց հռոմեացիներին", "55f18e85"], "d": ["Հռոմի դեմ Տարենտի կանչով 280 թ. Իտալիա ափ իջած Պյուռոսը Հերակլեայում փղերով և հեծելազորով հաղթեց Վալերիոս Լևինոսի բանակը, բայց ծանր կորուստներ կրեց։ 279 թ. Ասկուլումում դարձյալ հաղթեց, 278-276 թթ. անցավ Սիցիլիա։", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["Աքայական միությունը վերահիմնվեց. Պատրաս, Դիմե, Տրիտեա, Ֆարե", "81bba071"], "d": ["Անտիգոնյան վերահսկողության տակ գտնվող Աքայայում չորս քաղաք (Դիմե, Պատրաս, Տրիտեա, Ֆարե) մ.թ.ա. 280 թ. վերահիմնեցին դաշնային միությունը. հաջորդ տարիներին միացան Այգիոնը և մյուս քաղաքները։ Միությունը Արատոսի առաջնորդությամբ վերածվեց Պելոպոնեսի մեծ ուժի։", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["Ֆիլետայրոսը Կուրուպեդիոնից հետո անցավ Սելևկոսի կողմը. Պերգամոնը հիմնեց փաստացի անկախ հարստություն", "ac6b3e31"], "d": ["Լիսիմաքոսի անկումից հետո Ֆիլետայրոսը գանձարանի հետ ենթարկվեց Սելևկոսին և պահպանելով ու հարստացնելով Պերգամոնը՝ Սելևկոսի մահով (281) փաստացի անկախացավ։ Լիվիոսը տալիս է, որ Ատտալյան հարստությունը կառավարել է Պերգամոնը 283-ից մինչև 129 թ.։", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["Լիսիմաքոսը Պյուռոսին վտարեց Մակեդոնիայից և դարձավ Մակեդոնիայի միակ արքան", "a83e6c64"], "d": ["285 թ. ձմռանից հետո, երբ Դեմետրիոսը հանձնվեց Սելևկոսին, Լիսիմաքոսը Պյուռոսին դուրս վռնդեց Մակեդոնիայից և երկիրը միայնակ կառավարեց։ Նրա պետությունը հասավ Թրակիան, Մակեդոնիան և Արևմտյան Անատոլիան ընդգրկող ընդարձակ տարածքի։", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["Պյուռոսն ու Լիսիմաքոսը բաժանեցին Մակեդոնիան. Դեմետրիոս Պոլիորկետեսը տապալվեց", "63371ab8"], "d": ["287 թ. ամռանը, երբ Դեմետրիոսն անցավ Ասիա, Պյուռոսն ու Լիսիմաքոսը ընդհանուր Մակեդոնիան բաժանեցին երկու շրջանի. Դեմետրիոսը տապալվեց։ Այս բաժանումը տևեց միայն երկու տարի։", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["Սամնիոնը միացվեց Հռոմին. ավարտվեց Երրորդ Սամնիտական պատերազմը", "bede9942"], "d": ["Մանիուս Կուրիոս Դենտատոսը վճռական պարտության մատնեց սամնիտներին և սաբիններին. Սամնիոնը դարձավ Հռոմի դաշնակից։ Հռոմը դարձավ Կենտրոնական Իտալիայի տիրակալը և դեմ առ դեմ հայտնվեց Հարավային Իտալիայի հունական քաղաքների (Տարենտ) հետ։", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["Դեմետրիոս Պոլիորկետեսը հռչակվեց Մակեդոնիայի արքա", "a2b1eba3"], "d": ["Օգտվելով Կասանդրոսի հարստության գահակալական կռվից՝ Դեմետրիոսը 294 թ. աշնանը բանակի կողմից հռչակվեց Մակեդոնիայի արքա։ Սա Անտիգոնոսի տոհմի առաջին թագավորությունն է Մակեդոնիայում. 288 թ. փլուզվեց, Գոնատասը 276 թ. կայունացրեց այն։", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["Սենտինում. էտրուսկների, ումբրների, սամնիտների և գալլերի դաշինքը պարտվեց Հռոմին", "b5affc1b"], "d": ["Երրորդ Սամնիտական պատերազմում Սենտինումի այս ճակատամարտը ոչնչացրեց Իտալիայում Հռոմի դեմ վերջին մեծ դաշինքը. էտրուսկյան քաղաքները մեկը մյուսի հետևից ստիպված եղան դառնալ Հռոմի դաշնակիցներ։", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["Պյուռոսը Պտղոմեոսի աջակցությամբ վերադարձավ Էպիրոսի գահին", "6288bf69"], "d": ["Իպսոսից հետո Եգիպտոսում պատանդ մնացած Պյուռոսը Պտղոմեոսի օգնությամբ վերադարձավ Էպիրոս և ետ ստացավ գահը։ Դրանից հետո Էպիրոսը ձայն ունեցավ մակեդոնական և իտալական գործերում։", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["Լիսիմաքոսը իր գանձարանը դրեց Պերգամոնում. Ֆիլետայրոսը դարձավ ամրոցի պահապանը", "e1b4ab77"], "d": ["Իպսոսից հետո Լիսիմաքոսը իր գանձարանը պահել տվեց բլրի վրայի Պերգամոնի ամրոցում և պահակությունը վստահեց ներքինի Ֆիլետայրոսին։ Ֆիլետայրոսը 281 թ. անցնելով Սելևկոսի կողմը՝ դրեց հարստության հիմքը։", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["Միհրդատ I Կտիստեսը հիմնեց Պոնտոսի հարստությունը", "490c338c"], "d": ["Անտիգոնոս Մոնոֆթալմոսին մերձեցող Միհրդատը 302 թ. սպանվելու վտանգից փախչելով ապաստանեց Կապադովկյան Պոնտոսի լեռնային շրջանում՝ Կիմիատայում, և այնտեղ ստեղծեց Պոնտոսի թագավորության կորիզը։ Հարստությունը տևեց մինչև 63 թ.։", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["Դեմետրիոս Պոլիորկետեսի՝ Հռոդոսի պաշարումն ավարտվեց ձախողմամբ", "dae6f4d6"], "d": ["Անտիգոնոսի դեմ Պտղոմեոսի կողմը մնացած Հռոդոսը Դեմետրիոսը 305 թ. պաշարեց հսկա պաշարողական մեքենաներով. հռոդոսցիները մեկ տարի դիմադրեցին, և 304 թ. ամռանը հաշտություն կնքվեց։ Այս հաղթանակի փողով քաղաքում կանգնեցվեց արևի աստված Հելիոսի կոլոսը։", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["Կիպրոսի Սալամինում Դեմետրիոսը հաղթեց Պտղոմեոսին. Անտիգոնոսն ու Դեմետրիոսը ընդունեցին արքայի տիտղոս", "cc308941"], "d": ["306 թ. գարնանը Դեմետրիոս Պոլիորկետեսը Կիպրոսի մոտ հաղթեց Պտղոմեոսի նավատորմը և Կիպրոսը փոխանցեց Անտիգոնոսի ձեռքը. ամռանը Անտիգոնոսն ու Դեմետրիոսը ընդունեցին արքայի տիտղոս, մյուս դիադոքոսները նույնպես կարճ ժամանակում ստանձնեցին նույն տիտղոսը։ Պտղոմեոսը Կիպրոսը ետ վերցրեց 294 թ.։", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["Լիսիմաքոսը հիմնեց Լիսիմաքիան. մայրաքաղաք Թրակիական Խերսոնեսում", "83b83160"], "d": ["Լիսիմաքոսը Գալիպոլիի թերակղզու վզիկում իր հիմնած Լիսիմաքիան դարձրեց Թրակիական թագավորության մայրաքաղաքը. Բոսֆորի և Դարդանելի անցումները կենտրոնացան նրա ձեռքում։ Քաղաքը մ.թ.ա. III դարում ավերվեց երկրաշարժից։", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["Դիադոքոսների հաշտություն. ճանաչվեցին Ասիայում Անտիգոնոսի, Եվրոպայում Կասանդրոսի, Եգիպտոսում Պտղոմեոսի կառավարումը", "811c80f0"], "d": ["311 թ. դեկտեմբերին ստորագրված հաշտությամբ Անտիգոնոսը ճանաչվեց Ասիայի հրամանատար, Կասանդրոսը՝ Եվրոպայի ստրատեգոս, Լիսիմաքոսը՝ Թրակիայի, Պտղոմեոսը՝ Եգիպտոսի և շրջակայքի կառավարիչ. ընդունվեց հունական քաղաքների ազատության սկզբունքը։ Սելևկոսի Բաբելոնը մնաց այս հաշտությունից դուրս։", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["Տյուրոսն անցավ Անտիգոնոսին. Փյունիկիան վերցվեց Պտղոմեոսից", "30f78257"], "d": ["Անտիգոնոսը 315 թ. մտնելով Սիրիա՝ գրավեց Փյունիկիան և պաշարեց Տյուրոսը. քաղաքն ընկավ 314 թ.։ Փյունիկիայի ափը և ծովափը մինչև Գազա անցան նրա ձեռքը (312 թ. Գազայի ճակատամարտում վերադարձվեցին Պտղոմեոսին)։", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["Կասանդրոսը հիմնեց Սալոնիկը", "7043bd8a"], "d": ["Կասանդրոսը, Թերմայիկոս ծոցից հյուսիս ընկած ավելի քան քսան բնակավայր միավորելով, իր կնոջ (Փիլիպոս II-ի դուստր) Թեսալոնիկեի անունով քաղաք հիմնեց։ Սալոնիկը հաջորդ հազար տարում Մակեդոնիայի ամենակարևոր նավահանգիստն էր։", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["Կասանդրոսը վերահիմնել տվեց Թեբեն", "0167e784"], "d": ["Ալեքսանդրի կործանած Թեբեն Կասանդրոսի աջակցությամբ և Աթենքից ու Եվբեայից եկած օգնությամբ վերահիմնվեց՝ պարիսպները վերանորոգելով։ Բեովտիական միությունը վերստին կենտրոն ստացավ։", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["Գաբիենե. Անտիգոնոսը հաղթեց Եվմենեսին և դարձավ Իրան ձգվող Ասիայի տիրակալը", "d2990dfd"], "d": ["316/5 թթ. ձմռանը Գաբիենեում Եվմենեսի բանակը ջախջախվեց, նրա հրամանատարը իր իսկ զինվորների կողմից հանձնվեց Անտիգոնոսին և մահապատժի ենթարկվեց։ Անտիգոնոսը դարձավ Պարսկական սարահարթից մինչև Անատոլիա ձգվող ընդարձակ տարածքի միակ տիրակալը. Սելևկոսը փախավ Եգիպտոս։", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["Տրիպարադեիսոսի կարգավորում. Անտիգոնոս Մոնոֆթալմոսը դարձավ Ասիայի ստրատեգոս", "69f6fafb"], "d": ["Եգիպտոսում Պերդիկասի սպանությունից (320 թ. մայիս) հետո Անտիպատրոսը Տրիպարադեիսոսում վերաբաշխեց սատրապությունները. Անտիգոնոսը դրվեց Ասիայի ուժերի գլուխ, Սելևկոսը ստացավ Բաբելոնը։ Անտիգոնոսը այս դիրքից ձեռնամուխ եղավ իր սեփական կայսրությունը ստեղծելուն։", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["Կրաննոն. Լամիական պատերազմը պարտվեց. Աթենք մտավ մակեդոնական կայազոր, ժողովրդավարությունը կասեցվեց", "6931c4f6"], "d": ["322 թ. սեպտեմբերի 5-ին Կրաննոնում հունական դաշինքը պարտվեց Անտիպատրոսին և Կրատերոսին. Աթենքը համաձայնեց ընդունել մակեդոնական կայազոր Մունիխիայում և քաղաքացիության չափանիշը սահմանափակել սեփականատերերով։ Դեմոսթենեսը ինքնասպան եղավ. դասական Աթենքի ժողովրդավարությունը փաստացի ավարտվեց։", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["Լամիական պատերազմ. Ալեքսանդրի մահից հետո հունական քաղաքները ապստամբեցին մակեդոնական հեգեմոնիայի դեմ", "c31c7da4"], "d": ["Ալեքսանդրի մահվան լուրով (323 թ. հունիս) Աթենքն ու Էտոլիական միությունը ապստամբեցին Անտիպատրոսի դեմ. Անտիպատրոսը պաշարվեց Լամիայում։ Պատերազմը ավարտվեց Կրաննոնում (322 թ. սեպտեմբեր) Մակեդոնիայի հաղթանակով, և վերականգնվեց Կորնթոսյան միության շրջանակում մակեդոնական գերակայությունը։", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["Հիդասպես. Պորոսը պարտվեց. Փենջաբը կապվեց Ալեքսանդրին", "abab206b"], "d": ["326 թ. մայիսին Տաքսիլայի ռաջա Ամբհիի աջակցությամբ Ալեքսանդրը անցավ Ջելամը և հաղթեց Պորոսին. Պորոսի թագավորությունը թողնվեց Ալեքսանդրին որպես վասալ։ Ալեքսանդրը այս կետից առաջացավ դեպի արևելք, բայց Հիփասիսում կանգ առավ բանակի առարկության պատճառով։", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["Հիփասիսի (Բեաս) ափին բանակը հրաժարվեց առաջանալ. Ալեքսանդրի արևելյան սահմանը", "17b23afc"], "d": ["Մուսոնային անձրևների և հոգնածության պատճառով մակեդոնական բանակը հրաժարվեց անցնել Հիփասիսից այն կողմ. Ալեքսանդրը ստիպված էր կանգնեցնել տասներկու զոհասեղան և ետ դառնալ։ Հիփասիսը դարձավ մակեդոնական նվաճումների արևելյան ծայրը Հնդկաստանում։", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["Բակտրիան և Սողդիանան հնազանդվեցին Ալեքսանդրին. Ալեքսանդրը ամուսնացավ Ռոքսանայի հետ", "a050508d"], "d": ["329-327 թթ. Օքսոսից անդին շրջանը վերցվեց ուժեղ պարտիզանական պայքարով. Սպիտամենեսը սպանվեց, Սողդիանայի ժայռը և Խորիենեսի ամրոցը հանձնվեցին։ Ալեքսանդրը, ամուսնանալով բակտրիական արքայադուստր Ռոքսանայի հետ, տեղական ազնվականությանը կապեց կառավարմանը։", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["Արևմտյան Անատոլիայի ափն անցավ Ալեքսանդրին. Եփեսոս, Միլեթ և Հալիկառնաս", "f67084a4"], "d": ["Եփեսոսը ժողովրդավարական վարչակարգով բացեց դարպասները, Միլեթը պաշարման վերջում (334 թ. ամառ) վերցվեց. Հալիկառնասի պաշարումը աշնանն ավարտվեց քաղաքի անկմամբ, և Կարիայի սատրապությունը տրվեց Ադային։ Ալեքսանդրը այսպիսով իրագործեց պարսկական նավատորմի նավահանգիստները ցամաքից գրավելու ռազմավարությունը։", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["Թեբեն կործանվեց Ալեքսանդրի հրամանով", "26c4193c"], "d": ["Փիլիպոսի մահով ապստամբած Թեբեն Ալեքսանդրը աշնանը գրավեց. Կադմեայում դրեց մակեդոնական կայազոր, քաղաքը քանդել տվեց և բնակիչներին ստրկացրեց (բացի Պինդարոսի տնից)։ Բեովտիական միությունը այս ավերումով փաստացի ավարտվեց (316 թ. Կասանդրոսը վերահիմնեց)։", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["Փիլիպոս II-ը սպանվեց Այգեում. գահ բարձրացավ Ալեքսանդրը", "417d909e"], "d": ["Իր դուստր Կլեոպատրայի հարսանյաց տոնախմբության ժամանակ թատրոնում իր թիկնապահ Պաուսանիասի ձեռքով սպանված Փիլիպոսի փոխարեն բանակը արքա հռչակեց նրա որդի Ալեքսանդրին։ Պարսկական արշավանքը և Հունաստանի վերահսկողությունը մնացին Ալեքսանդրին։", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["Հիմնվեց Կորնթոսյան միությունը. հունական քաղաքները միավորվեցին Փիլիպոս II-ի հեգեմոնիայի ներքո", "c38074dc"], "d": ["Քերոնեայից հետո Փիլիպոսը հունական քաղաքներին հավաքեց Կորնթոսում ընդհանուր խաղաղության (koine eirene) և ընդհանուր պաշտպանության ուխտով. որոշվեցին պարսիցների դեմ արշավանքի համար զինվորները և հեգեմոնի հրամանատարությունը։ Միայն Սպարտան չմիացավ։", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["Քերոնեա. Փիլիպոսը, հաղթելով Աթենքի և Թեբեի բանակին, ստանձնեց Հունաստանի վերահսկողությունը", "5e5d77e7"], "d": ["338 թ. օգոստոսին Քերոնեայի հարթավայրում երիտասարդ Ալեքսանդրի հրամանատարությամբ հեծելազորի գրոհով ջախջախվեց աթենա-թեբեական բանակը. Թեբեում դրվեց մակեդոնական կայազոր, Աթենքը ներողամտությամբ ներվեց։ Հաղթանակը վերջ դրեց հունական քաղաքների անկախությանը և ճանապարհ բացեց դեպի Կորնթոսյան միություն։", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["Լատինական միությունը ցրվեց. Լացիումը կապվեց Հռոմին", "58849f84"], "d": ["Լատինական պատերազմի (340-338) վերջում Հռոմը լուծարեց Լատինական միությունը. քաղաքները ստացան հռոմեական քաղաքացիություն կամ առանձին-առանձին կապվեցին Հռոմին, նրանց միջև դաշինքն արգելվեց։ Սա Հռոմի՝ Իտալիայում ընդլայնման մոդելի հիմքն է։", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["Փիլիպոս II-ը հաղթեց սկյութ արքա Ատեասին", "e4dee658"], "d": ["Ատեաս արքայի պատերազմը Իստրոսի (Դանուբ) ափերին Փիլիպոսի հետ ավարտվեց Ատեասի սպանությամբ. վերադարձի ճանապարհին Փիլիպոսը հարձակման ենթարկվեց տրիբալլների կողմից։ Սկյութական ուժը արևմուտքում տեղաշարժվեց Դանուբից այն կողմ։", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["Փիլիպոսը լծի տակ դրեց Թրակիան՝ Օդրիսյան հարստության հետ միասին", "b543427a"], "d": ["Մ.թ.ա. 342-341 թթ. արշավանքներում Փիլիպոսը խորացավ Թրակիա, խարաջի կապեց Օդրիսյան արքա Կերսոբլեպտեսին և հիմնեց Ֆիլիպոպոլիսի (Պլովդիվ) նման քաղաքներ։ Թրակիան դարձավ Մակեդոնիայի արևելյան շարունակությունը։", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["Օլինթոսի կործանումը. Քալկիդիկեի միությունն անցավ Մակեդոնիային", "89d77301"], "d": ["Չնայած Օլինթոսի՝ Աթենքից օգնության խնդրանքին՝ Փիլիպոսը քաղաքը դավաճանությամբ գրավեց և ավերեց. Քալկիդիկեի թերակղզին միացվեց Մակեդոնիային։ Դեմոսթենեսի «Օլինթոսյան» ճառերը հիմնվում են այս կանչի վրա։", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["Դաշնակցային պատերազմն ավարտվեց. Բյուզանդիոնը, Քիոսը, Հռոդոսը և Կոսը դուրս եկան Աթենական II միությունից", "856a9763"], "d": ["Մ.թ.ա. 357 թ. սկսված ապստամբությունը, Քիոսում աթենական հրամանատարների պարտությամբ և Պարսկաստանի աջակցության՝ Աթենքի դեմ դուրս գալով, ավարտվեց Աթենքի՝ հաշտությունն ընդունելով. չորս կարևոր անդամ ձեռք բերեց անկախություն։ Միությունը թուլացավ և անպաշտպան մնաց Մակեդոնիայի առջև։", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["Փիլիպոսը Ամփիպոլիսը վերցրեց Աթենքից", "2c793bc6"], "d": ["Ստրիմոնի գետաբերանում Աթենքի Ամփիպոլիսը պաշարելով և գրավելով՝ Փիլիպոսը հասավ քաղաքի ոսկու ու արծաթի հանքերին և շինափայտի պաշարներին և դուրս եկավ Թրակիայի ափ։ Այս նվաճումը սկիզբ դրեց աթենա-մակեդոնական հակամարտությանը։", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["Փիլիպոս II-ը դարձավ Մակեդոնիայի արքա", "d557268d"], "d": ["Պերդիկաս III-ի՝ իլլիրիացիների դեմ պատերազմում զոհվելուց (մ.թ.ա. 360/359) հետո Փիլիպոսը նախ խնամակալ, ապա արքա դարձավ. ետ մղեց իլլիրիական, պեոնյան և թրակիական սպառնալիքները և իրականացրեց բանակային բարեփոխումը (սարիսայի ֆալանգ)։ Մակեդոնիայի վերելքը սկսվում է այս թագավորությամբ։", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["Մանտինեա. Էպամինոնդասը զոհվեց, բեովտական հեգեմոնիան ավարտվեց", "94be8d5c"], "d": ["Թեբեի բանակը հաղթեց ճակատամարտում, բայց Էպամինոնդասը վիրավորվեց ու մահացավ. Քսենոփոնը ավարտում է «Հունաստանում անորոշությունն ու խառնաշփոթը առաջվանից ավելին էին» խոսքով։ Թեբեի կարճատև հեգեմոնիան ավարտվեց նույն տարում, պահպանվեց Աթենք–Սպարտա–Թեբե հավասարակշռությունը։", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["Հիմնվեց Արկադիական միությունը. Պելոպոնեսյան միության այս մասը ցրվեց", "42fdc676"], "d": ["Լևկտրայից հետո Արկադիայի քաղաքները Թեբեի աջակցությամբ ստեղծեցին դաշնային միություն և կառուցեցին նոր մայրաքաղաք Մեգալոպոլիսը։ Այսպիսով Սպարտայի Պելոպոնեսյան միությունը փաստացի ցրվեց. Սպարտան ետ քաշվեց միայն Լակոնիա։", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["Մեսենիան անջատվեց Սպարտայից. հիմնվեց Մեսսենեն", "e4ef9302"], "d": ["Լևկտրայից հետո Էպամինոնդասի պելոպոնեսյան արշավանքի ժամանակ (370/69 թթ. ձմեռ) Մեսենիայի հելոտները ազատագրվեցին, և Իթոմե լեռան ստորոտում հիմնվեց ամուր պարիսպներով Մեսսենե քաղաքը։ Սպարտան դարեր անց առաջին անգամ կորցրեց իր տնտեսական հիմքը կազմող մեսենյան հողերը։", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["Լևկտրա. թեբեական բանակը հաղթեց սպարտացիներին. Սպարտան կորցրեց ցամաքային գերակայությունը", "e7829597"], "d": ["Էպամինոնդասի խորացրած աջ թևի կուտակման մարտակարգը Լևկտրայում ջախջախեց Կլեոմբրոտոս արքայի սպարտական ուժը. մոտ 400 սպարտիատի զոհվելով Սպարտան այլևս չկարողացավ լրացնել բնակչության կորուստը։ Սկսվեց Թեբեի առաջնորդությամբ հեգեմոնիայի շրջան։", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["Հիմնվեց Աթենական II միությունը (Արիստոտելեսի հրամանագիր)", "0e5dcaf2"], "d": ["Աթենքը Սպարտայի դեմ ինքնավարության և խարաջ չվերցնելու սկզբունքով Էգեյան քաղաքներին հրավիրեց միության. հրամանագիրն ընդունվեց Արիստոտելեսի առաջարկով, և անդամ քաղաքների ցանկը փորագրվեց քարի վրա։ Միության հիմնադրումը Աթենքը դարձյալ դարձրեց ծովային ուժ։", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["Պելոպիդասը ազատագրեց Թեբեն. սպարտական կայազորը վտարվեց Կադմեայից", "eb15a9d7"], "d": ["Սպարտայի մ.թ.ա. 382 թ. գրաված և կայազոր թողած Թեբեի Կադմեան ետ վերցվեց աքսորյալների գիշերային հարձակմամբ. Թեբեն դարձյալ դարձավ Բեովտական միության կենտրոն։ Իրադարձությունը Սպարտայի հեգեմոնիայի կազմալուծման սկիզբն է։", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["Ալլիա. գալլերը, հաղթելով հռոմեական բանակին, կողոպտեցին քաղաքը", "db864bc9"], "d": ["Տիբերի վտակ Ալլիայի ափին սենոն գալլերը ջախջախեցին հռոմեական բանակը. Հռոմը, բացի Կապիտոլիումից, գրավվեց ու կողոպտվեց։ Լիվիոսը գրում է, որ «Ալլիայի օրը» (հուլիսի 18) հռոմեացիների համար համարվում էր չարագուշակ։", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["Կորնթոսը միավորվեց Արգոսի հետ (Արգոս–Կորնթոս իսոպոլիտեա)", "135a3d3a"], "d": ["Կորնթոսյան պատերազմի ժամանակ (մ.թ.ա. 395-387) Կորնթոսը Արգոսի հետ ստեղծեց ընդհանուր քաղաքացիության միություն. արգոսյան կայազորը մնաց Կորնթոսում։ Սպարտան Արքայական հաշտությամբ (386) խզել տվեց այս միավորումը։", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["Վեյին անցավ Հռոմին. կորսվեց Էտրուրիայի հարավի առաջին մեծ քաղաքը", "0d1c4fe4"], "d": ["Տասնամյա պաշարումից հետո Կամիլոսը վերցրեց Վեյին (ավանդությամբ մ.թ.ա. 396). ժողովուրդը ստրկացվեց, հողերը միացվեցին Հռոմին, և Հռոմի ager Romanus-ը գրեթե կրկնապատկվեց։ Էտրուսկյան քաղաքների ուժը Տիբերից հարավ կոտրվեց։", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["Աթենքը հանձնվեց Սպարտային. աթենական ծովային կայսրությունն ու Դելոսյան միությունն ավարտվեցին", "43f2ddf9"], "d": ["Էգոսպոտամիում նավատորմը կորցրած Աթենքը սովի պատճառով հանձնվեց. Երկար պատերը քանդվեցին, ծովային կայսրությունը ցրվեց, քաղաքում հաստատվեց սպարտացիների ստեղծած Երեսունի իշխանությունը։ Միության նախկին անդամ կղզիներում և Թրակիայի ափերին տեղակայվեցին Լիսանդրոսի հիմնած դեկարխիա վարչակարգերը և սպարտական կայազորները։", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["Դիոնիսիոս I-ը դարձավ Սիրակուզայի բռնակալ", "1ad10305"], "d": ["Այն տարիներին, երբ Կարթագենը գրավեց Ակրագասը և Գելան, Դիոնիսիոսը 405 թ. դարձավ Սիրակուզայի ստրատեգոս և ապա բռնակալ. հաշտություն կնքելով Կարթագենի հետ (405)՝ Սիցիլիայի հունական քաղաքները կապեց իրեն։ 38 տարի տևելիք Դիոնիսիոսի իշխանությունը Սիցիլիան դարձրեց Միջերկրականի մեծ ուժերից մեկը։", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["Էգոսպոտամի. աթենական նավատորմը ոչնչացվեց. Դելոսյան միությունը հասավ փլուզման եզրին", "ce62187c"], "d": ["405 թ. սեպտեմբերին Լիսանդրոսը հանկարծակի հարձակմամբ գրավեց Էգոսպոտամիում խարիսխ գցած աթենական նավատորմը. կորսվեցին նավատորմի գրեթե ամբողջը և հազարավոր գերիներ։ Հելլեսպոնտոսի ճանապարհը փակվեց, և Աթենքի հացահատիկի մատակարարումը կտրվեց. մի քանի ամիս անց Աթենքը հանձնվեց։", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["Հիմնվեց Հռոդոս քաղաքը. միավորվեցին Լինդոսը, Իալիսոսը և Կամիրոսը", "2de55901"], "d": ["Մ.թ.ա. 408 թ. Հռոդոս կղզու երեք քաղաքները ստեղծելով ընդհանուր պետություն՝ միավորվեցին նոր Հռոդոս քաղաքում. Հիպոդամոսի հատակագծով կառուցված քաղաքը դարձավ հելլենիստական աշխարհի ամենակարևոր ծովային հենակետերից և առևտրական կենտրոններից մեկը։", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["Հաննիբալ Մագոնը ավերեց Սելինուսը և Հիմերան. Կարթագենը հաստատվեց Սիցիլիայի արևմուտքում", "358f4417"], "d": ["Սեգեստայի օգնության կանչով Սիցիլիա ափ իջած Հաննիբալ Մագոնը մ.թ.ա. 409 թ. վերցրեց Սելինուսը և Հիմերան. շրջանը դարձավ Կարթագենի էպիկրատիա։ Կարթագեն–Սիրակուզա հակամարտությունը տևեց երկու դար։", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["Սիցիլիական արշավանքն ավարտվեց աղետով. աթենական բանակը ոչնչացավ Սիրակուզայի մոտ", "b363df0d"], "d": ["Մ.թ.ա. 415 թ. Աթենքի սկսած սիցիլիական արշավանքը, Սիրակուզան չպաշարվելուց հետո, Նիկիասի և Դեմոսթենեսի նահանջի ժամանակ Ասինարոս գետի ափին անձնատվությամբ (մ.թ.ա. 413 թ. աշուն) ավարտվեց։ Աթենքը կորցրեց իր բանակը և նավատորմի մեծ մասը։", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["Սիտալկեսը դաշինք կնքեց Աթենքի հետ. Օդրիսյան թագավորությունը մասնակցեց Պելոպոնեսյան պատերազմին", "4562f13d"], "d": ["Աթենքը Սիտալկեսի որդուն դարձրեց Աթենքի քաղաքացի և դաշինք կնքեց նրա հետ. Սիտալկեսը 429 թ. հարձակվեց Մակեդոնիայի վրա։ Օդրիսյան ուժը այդ շրջանում հասավ իր գագաթնակետին։", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["Սկսվեց Պելոպոնեսյան պատերազմը. Պելոպոնեսյան միությունը զորահավաք անցկացրեց Աթենքի դեմ", "2adee4a1"], "d": ["Թեբեի՝ Պլատեայի վրա գիշերային հարձակմամբ (431 թ. գարուն) հաշտությունը փաստացի խախտվեց. ամռան սկզբին Արքիդամոս արքայի հրամանատարությամբ Պելոպոնեսյան միության բանակը ներխուժեց Ատտիկա։ Պատերազմը Աթենքի ծովային կայսրության և Սպարտայի ցամաքային միության միջև տևեց 27 տարի։", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["Սիբոտա. Կորնթոս–Կորկիրա պատերազմը ներքաշեց Աթենքին միջամտության", "dc07b0ac"], "d": ["Կորնթոսի՝ իր գաղութ Կորկիրայի հետ Էպիդամնոսի պատճառով սկսած ծովային պատերազմում Աթենքը աջակցեց Կորկիրային։ Կորնթոսի զայրույթը Աթենքի դեմ դարձավ Պելոպոնեսյան պատերազմի անմիջական պատճառներից մեկը։", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["Սպարտոկոսը դարձավ արքոնտ Բոսպորոսում. Սպարտոկյան հարստությունը", "ddc76f79"], "d": ["Պանտիկապայոնի Արքեանակտյան հարստության տեղը զբաղեցրեց թրակիական ծագումով Սպարտոկոսը (438/7). Սպարտոկյան հարստությունը հիմնեց Բոսպորոսի թագավորությունը և ղեկավարեց հացահատիկի արտահանումը Աթենք։ Հարստությունը տևեց մինչև մ.թ.ա. 109 թ.։", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["Երեսնամյա հաշտություն. Աթենքը կորցրեց ցամաքային կայսրությունը (Բեովտիա, Մեգարա, Աքայա)", "4f33ff13"], "d": ["Կորոնեայում բեովտացիների՝ աթենական բանակին հաղթելուց (447), ապա Եվբեայի և Մեգարայի ապստամբություններից և Սպարտայի՝ Ատտիկա ներխուժումից հետո Աթենքը ստորագրեց Երեսնամյա հաշտությունը։ Աթենքը թողեց Մեգարան, Նիսեան, Պեգեն և Պելոպոնեսում Տրոյզենն ու Աքայան. պահեց միայն ծովային կայսրությունը։", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["Տերեսը հիմնեց Օդրիսյան թագավորությունը. Թրակիայի առաջին մեծ պետությունը", "83caf189"], "d": ["Թուկիդիդեսը գրում է, որ Տերեսը Թրակիայում հիմնել է առաջին մեծ թագավորությունը. նրա որդի Սիտալկեսը թագավորությունը Դանուբից հասցրեց Էգեյան ծով։ Օդրիսյան թագավորությունը Աթենքի, Մակեդոնիայի և Պարսկաստանի միջև վարեց հավասարակշռության քաղաքականություն։", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["Միության գանձարանը Դելոսից տեղափոխվեց Աթենք", "173f2e5b"], "d": ["Եգիպտոսի արշավանքի պարտության և պարսկական նավատորմի վախի պատրվակով ընդհանուր գանձարանը Դելոսից տարվեց Աթենք. Աթենքի աստվածուհուն տրվող «վաթսունից մեկ» բաժնի ցանկերը սկսվում են այդ տարվանից։ Այս քայլը մեկնաբանվում է որպես նշան, որ միությունը գործնականում վերածվեց աթենական կայսրության։", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["Թասոսի ապստամբությունը ճնշվեց. Դելոսյան միությունը դարձավ կայսրություն, որից անդամները չէին կարող դուրս գալ", "d24bd124"], "d": ["Թասոսը հանքերի պատճառով բախվելով Աթենքի հետ՝ փորձեց դուրս գալ միությունից. երկամյա պաշարումից հետո (մ.թ.ա. 463) քանդեց պարիսպները, հանձնեց նավատորմը և կորցրեց Թրակիայի ափի հանքային շրջանը։ Իրադարձությունը առաջին նախադեպն է, որը ցույց է տալիս, որ միության անդամակցությունը չի կարելի թողնել։", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["Կիմեի (Կումե) ծովամարտ. Սիրակուզան հաղթեց էտրուսկյան նավատորմը, էտրուսկյան ծովային ուժը կոտրվեց", "2e81670b"], "d": ["Կիմեի օգնության կանչով Սիրակուզայի բռնակալ Հիերոն I-ը ջախջախեց էտրուսկյան նավատորմը Կիմեի մոտ. Հիերոնը հաղթանակը տոնեց՝ Դելֆիին սաղավարտ նվիրելով (Լիվիոսի նշած էտրուսկյան սաղավարտը)։ Էտրուսկների իշխանությունը Կամպանիայում ցնցվեց։", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["Հիմնվեց Դելոսյան միությունը. Էգեյան դաշինք Աթենքի նախագահությամբ", "f0de153a"], "d": ["Պաուսանիասի կառավարման ոճից հետո իոնական քաղաքները Աթենքից առաջնորդություն խնդրեցին. Արիստիդեսի սահմանած խարաջով (460 տաղանդ) Դելոսում ստեղծվեց ընդհանուր գանձարան։ Միությունը Աթենքին ապահովեց Էգեյանի վրա մշտական նավատորմ և հարկային բազա։", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["Սալամին (480 թ. սեպտեմբերի 29) և Պլատեա. պարսկական ներխուժումը ետ մղվեց", "479b17e6"], "d": ["Քսերքսեսը Աթենքը գրավելով և այրելով հետո, Թեմիստոկլեսի ծուղակով, պարսկական նավատորմը ջախջախվեց Սալամինի նեղուցում (480 թ. սեպտեմբերի 29). հաջորդ տարի Պլատեայում Պաուսանիասի հրամանատարությամբ հունական ցամաքային բանակը հաղթելով Մարդոնիոսին՝ վերջ դրեց ներխուժմանը։ Այսպիսով Էգեյան Հունաստանը ազատվեց պարսկական իշխանությունից։", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["Հիմերա. Սիցիլիայի հույները հաղթեցին կարթագենյան բանակը", "ece09580"], "d": ["Գելոնի և Թերոնի դաշինքը Հիմերայի մոտ ջախջախեց Համիլկարի կարթագենյան բանակը. Կարթագենը կես դար չկարողացավ կրկին մեծ արշավանք կատարել Սիցիլիա։ Ըստ Հերոդոտոսի և Դիոդորոսի՝ նույն օրը տարվեց Սալամինի հաղթանակը (ավանդություն)։", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["Մարաթոն. Աթենքը կանգնեցրեց պարսկական արշավանքը", "0967ce7c"], "d": ["Միլտիադեսի հրամանատարությամբ աթենացի և պլատեացի հոպլիտները Մարաթոնի հարթավայրում հաղթելով պարսկական ուժին՝ կանխեցին նրա առաջխաղացումը դեպի Ատտիկա։ Հաղթանակը սնեց աթենական ժողովրդավարության ինքնավստահությունը և ապա Դելոսյան միությանը տանող ծովային քաղաքականությունը։", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["Մարդոնիոսը Մակեդոնիան ենթարկեց Պարսկաստանին", "7bde569c"], "d": ["Դարեհի փեսա Մարդոնիոսը, անցնելով Թրակիան, Մակեդոնիան մտցրեց պարսկական իշխանության տակ. մակեդոնական արքան Պարսկաստանին հող ու ջուր տվեց։ Մակեդոնիան այս կախվածությունը թոթափեց Պլատեայից հետո (479)։", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum. Հռոմը դաշինք կնքեց Լատինական միության հետ", "56db407d"], "d": ["Սպուրիոս Կասիոսի անունը կրող պայմանագրով Հռոմը և Լատինական միությունը դաշինք ստեղծեցին փոխադարձ պաշտպանության, ավարի բաժանման և ընդհանուր բանակի հիմքով։ Այս պայմանագիրը մինչև Լատինական պատերազմը (340-338) հռոմեա-լացիումյան հարաբերությունների շրջանակն է։", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["Կորնթոսի դուրս գալով ցրվեց Պելոպոնեսյան միության արշավանքը Աթենքի դեմ", "b44adf6b"], "d": ["Սպարտան Կլեիսթենեսի ժողովրդավարական Աթենքի դեմ Պելոպոնեսյան միության բանակը մղեց Ատտիկա. Էլևսիսում կորնթոսյան բանակի ետ քաշվելը և սպարտական երկու արքաների տարաձայնությունը ձախողեցին արշավանքը։ Իրադարձությունը համարվում է առաջին հայտնի օրինակը, երբ միության ժողովում սկսեց գործել դաշնակիցների ձայնի իրավունքը։", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["Կլեիսթենեսի բարեփոխումը. դրվեց աթենական ժողովրդավարության ինստիտուցիոնալ հիմքը", "b2421c86"], "d": ["Հիպիասի անկումից հետո Կլեիսթենեսը քաղաքացիներին կազմակերպեց բնակավայրային միավորների՝ դեմոսների և տասը նոր ցեղերի հիման վրա. Հինգհարյուրի խորհուրդը դարձավ այս կարգի կենտրոնը։ Սա այն կարգավորումն է, որտեղից ծնվեցին isonomia/demokratia հասկացությունները։", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["Վերջին արքա Տարկվինիոս Սուպերբոսը վտարվեց. թագավորությունն ավարտվեց, սկսվեց Հանրապետությունը", "5a4a9061"], "d": ["Ըստ Լիվիոսի՝ Տարկվինիոս Սուպերբոսն ու նրա ընտանիքը մ.թ.ա. 509 թ. վտարվեցին քաղաքից, և ընտրվեցին առաջին հյուպատոսները (Բրուտոս, Կոլլատինոս)։ Պոլիբիոսը հռոմեա-կարթագենյան առաջին պայմանագիրը կապում է առաջին հյուպատոսների տարվա հետ. թեև այս տարեթիվը ժամանակակից պատմագրության մեջ համարվում է «ավանդություն», այն տեղավորվում է մ.թ.ա. VI դարի վերջում։", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["Առաջին պայմանագիրը Հռոմի և Կարթագենի միջև (Պոլիբիոս 3.22)", "cdef940f"], "d": ["Պոլիբիոսը բնագրով փոխանցում է առաջին հյուպատոսների տարում Հռոմի և Կարթագենի միջև կնքված պայմանագիրը, որը Լացիումի ափերը հատկացնում էր Հռոմին, իսկ Սիցիլիայի արևմուտքը և Լիբիան՝ Կարթագենին։ Հռոմը հիշատակվում է որպես Լացիումի տեր։", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["Ալալիայի ծովամարտ. էտրուսկներն ու կարթագենցիները փոկեացիներին դուրս վռնդեցին Կորսիկայից", "25efbea8"], "d": ["Ալալիայում փոկեացի հույները թղթի վրա հաղթանակ տարան, բայց կորցրին իրենց նավատորմի մեծ մասը. թողնելով Կորսիկան՝ քաշվեցին Հարավային Իտալիայի Էլեա։ Կղզում հաստատվեց էտրուսկյան (Ցերե) իշխանություն։", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["Սպարտա–Տեգեա պայմանագիր. ձևավորվեց Պելոպոնեսյան միության կորիզը", "57098e47"], "d": ["Սպարտան հաղթելով Արկադիայի Տեգեային՝ նրա հողերը չխաթարելու դիմաց ստիպեց ընդունել հավերժական դաշինք (symmachia). նույն կաղապարը տարածվեց Պելոպոնեսի քաղաքների վրա, և Սպարտայի նախագահությամբ ծնվեց Պելոպոնեսյան միությունը։ Միությունը ներսում գործում էր Սպարտայի և դաշնակիցների ժողովի ձևով (Սպարտայի հրամանատարությամբ)։", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["Փոկեացիները հիմնեցին Մասալիան (Մարսել)", "5d46bdf2"], "d": ["Փոկեացի գաղութաբնակները մ.թ.ա. մոտ 600 թ. Ռոնի գետաբերանում հիմնեցին Մասալիան. քաղաքը Արևմտյան Միջերկրականում դարձավ հունական առևտրի և կելտական աշխարհի հետ շփման կենտրոն։", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["Թերացի Բատտոսը հիմնեց Կյուրենեն", "67fd477f"], "d": ["Թերայից եկած գաղութաբնակները Դելֆյան պատգամախոսության համաձայն Բատտոսի առաջնորդությամբ հիմնեցին Կյուրենեն. Բատտիադների հարստությունը կառավարեց մինչև 440 թ.։ Լիվիոսը հիմնադրման ամսաթիվը տալիս է «մոտ 630»։", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["Սպարտան հաղթեց Առաջին Մեսենյան պատերազմում. Մեսենիան միացվեց Սպարտային", "74ad461c"], "d": ["Պաուսանիասի փոխանցած ավանդությամբ Առաջին Մեսենյան պատերազմը տևեց քսան տարի, և Իթոմեի անկմամբ Մեսենիայի հարթավայրն անցավ Սպարտային. ժողովուրդը իջեցվեց հելոտի կարգավիճակի։ Այս նվաճումը համարվեց Սպարտայի գյուղատնտեսական ուժը և ռազմական հասարակությունը որոշող հիմնարար իրադարձությունը։", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["Սիրակուզան հիմնվեց կորնթացի Արքիասի կողմից", "10217104"], "d": ["Ըստ Թուկիդիդեսի՝ Նաքսոսից մեկ տարի անց կորնթացի Արքիասը հիմնեց Սիրակուզան։ Քաղաքը դարձավ Սիցիլիայի ամենամեծ հունական քաղաքը։", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["Կարթագենի ավանդական հիմնադրումը (Տիմեոս. մ.թ.ա. 814/813)", "908099b5"], "d": ["Ըստ Տիմեոսի՝ Կարթագենը մ.թ.ա. 814/813 թ. հիմնվել է Տյուրոսցի գաղութաբնակների կողմից. Հուստինոսը տալիս է 825 թ.։ Հնագիտական շերտերը մատնանշում են մ.թ.ա. VIII դարի վերջը։", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["Միկենյան պալատական կենտրոնները կործանվեցին. Պելոպոնեսում պալատական կարգը փլուզվեց", "d2c79152"], "d": ["Ուշ հելլադյան IIIB-ի վերջում / IIIC-ի սկզբում Պիլոսի, Տիրինսի և Միկենքի պալատական կենտրոնները ցույց են տալիս կործանման կամ լքման շերտ. Linear B գրի վրա հիմնված պալատական տնտեսությունն ավարտվում է։ Կործանման պատճառը (երկրաշարժ, ներքին կռիվներ, ծովի ժողովուրդներ, երաշտ) վիճելի է. կործանման շերտերը տարածվում են ոչ թե մեկ տարվա, այլ մի քանի տասնամյակի վրա։", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["Կրետեում մինոսյան պալատների ավերումը. Կնոսոսում սկսվեց միկենյան վերահսկողությունը", "1a7f7f2b"], "d": ["Ուշ մինոսյան IB-ի վերջում (մ.թ.ա. XV դարի կեսեր) Կրետեի պալատական կենտրոններն ու վիլլաները ավերվում են. հաջորդ փուլում Կնոսոսի Linear B տախտակները ցույց են տալիս հունարեն գրված պալատական կառավարում, այսինքն՝ միկենյան վերահսկողություն։ Այսպիսով Կրետեում ավարտվում է մինոսյան իշխանությունը։", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["Տևտոբուրգյան անտառ. Վարուսի երեք լեգեոնը ոչնչացվեց. Հռոմը հրաժարվեց Էլբայի գծից", "1684ae43"], "d": ["Մ.թ. 9 թ. Արմինիոսի գլխավորած գերմանական դաշինքը Տևտոբուրգյան անտառում ոչնչացրեց Պ. Քվինկտիլիոս Վարուսի XVII, XVIII և XIX լեգեոնները։ Օգոստոսը հրաժարվեց Ռենոսից այն կողմ նվաճումներից, և Ռենոսի սահմանը կայունացավ։", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["Մահացավ Օգոստոսը. Տիբերիոսը դարձավ կայսր", "0221344d"], "d": ["Օգոստոսը 14 թ. օգոստոսի 19-ին մահացավ Նոլայում. նրա տեղը զբաղեցրեց Տիբերիոսը։ Այսպիսով պրինցիպատում կայունացավ ժառանգորդության սկզբունքը (ընտանիքից որդեգրում)։", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["Պտղոմեոս արքան սպանվեց Կալիգուլայի կողմից. Մավրիտանիայի անկախությունն ավարտվեց", "11337627"], "d": ["Յուբա II-ի որդի Պտղոմեոսը մ.թ. 40 թ. Լուգդունումում սպանվեց Կալիգուլայի հրամանով. ապա Մավրիտանիայում բռնկվեց Էդեմոնի ապստամբությունը, և Կլավդիոսը 44 թ. երկիրը բաժանեց երկու նահանգի՝ Tingitana և Caesariensis։", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["Կլավդիոսը ներխուժեց Բրիտանիա", "f42ba7f7"], "d": ["Մ.թ. 43 թ. Ավլոս Պլավտիոսի հրամանատարությամբ չորս լեգեոն ափ իջավ Քենթի ծովափին. վերցվեց Կամուլոդունումը (Կոլչեստեր), և Կլավդիոսը կարճ ժամանակ մնաց քաղաքում։ Բրիտանիայի հարավը դարձավ հռոմեական նոր նահանգ։", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["Հռոմը Թրակիան դարձրեց նահանգ. Օդրիսյան հարստությունն ավարտվեց", "af2ba1b2"], "d": ["Թրակիայի արքա Ռոյմետալկես III-ի՝ իր կնոջ ձեռքով սպանության և դրան հաջորդած խառնաշփոթի պատճառով Կլավդիոսը 46 թ. Թրակիան վերածեց հռոմեական նահանգի։ Սա Բալկաններում Հռոմի արևելյան նահանգային կարգը լրացնող վերջին քայլերից է։", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["Տրայանոսը նվաճեց Դակիան. Սարմիզեգետուսան ընկավ, Դեկեբալոսը մահացավ, ստեղծվեց Dacia նահանգը", "a9277172"], "d": ["Երկրորդ դակիական պատերազմում (105-106) Տրայանոսը վերցրեց Սարմիզեգետուսան. Դեկեբալոսը ինքնասպան եղավ՝ գերեվարումից խուսափելու համար։ Դակիան դարձավ հռոմեական նահանգ, և ոսկու հանքերը կապվեցին հռոմեական տնտեսությանը։ Պատերազմի նախորդ փուլերը (101-105) ժամանակագրության մեջ առանձին հոդվածներ են։", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["Ադրիանոսը Բրիտանիայում սկսեց Պատի կառուցումը հյուսիսային սահմանին", "f4a886ec"], "d": ["Ադրիանոսը մ.թ. 122 թ. Բրիտանիա այցելելուց հետո Թայն-Սոլուեյ գծով սահմանային պատ կառուցել տվեց։ Պատը խորհրդանշում է Հռոմի պաշտպանական սահմանային քաղաքականությունը. առաջխաղացումը փորձվեց Անտոնինոսի պատով (142), բայց մշտական չդարձավ։", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["Սեպտիմիոս Սևերոսը Միջագետքը դարձրեց նահանգ. Տիզբոնը կողոպտվեց", "df466924"], "d": ["Սևերոսը պարթևական պատերազմում (195-198) վերցրեց Մծբինը, կողոպտեց Տիզբոնը և Վերին Միջագետքը կազմակերպեց որպես հռոմեական նահանգ։ Նահանգը Հռոմի ամենաարևելյան առաջխաղացումը տարավ III դար։", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana. կայսրության բոլոր ազատ բնակիչներին շնորհվեց հռոմեական քաղաքացիություն", "dd4e4024"], "d": ["Կարակալլան մ.թ. 212 թ. նահանգների ազատ բնակիչներին դարձրեց հռոմեական քաղաքացի. կայսրությունում վերացավ քաղաքացի-օտարական տարբերությունը։ Կարգավորումը ընդլայնեց նաև հարկային բազան։", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["Պոստումոսը Գալիայում հիմնեց անջատողական Գալլական կայսրությունը", "4dcda41d"], "d": ["Վալերիանոսի՝ պարթևական գերության մեջ ընկնելուց (260) հետո Պոստումոսը Ռենոսի բանակներով Գալիայում կայսր հռչակվեց. Գալիան, Բրիտանիան և Իսպանիայի մեծ մասը մինչև 274 թ. պոկվեցին Հռոմից։ Գալիենոսը չկարողացավ վերացնել անջատումը։", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["Ավրելիանոսը դատարկեց Դակիան. Դանուբից հյուսիս ընկած տարածքը թողնվեց", "db2ca714"], "d": ["Գոթերի ճնշման պատճառով Ավրելիանոսը դատարկեց Dacia նահանգը և լեգեոններն ու քաղաքացիական բնակչությունը ետ քաշեց Դանուբից հարավ (Dacia Ripensis)։ Հռոմը 165 տարի անց թողեց Դանուբից հյուսիս իր առաջին մեծ հողը։", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["Ավրելիանոսը հաղթեց Պալմիրայի կայսրությանը. Զենոբիայի արևելյան հողերը վերադարձան Հռոմին", "0a358790"], "d": ["Ավրելիանոսը 272 թ. Անտիոքում և Էմեսայում հաղթեց Զենոբիայի բանակը և պաշարեց Պալմիրան. Զենոբիան գերվեց։ Սիրիան, Եգիպտոսը և Անատոլիայի հարավը կրկին կապվեցին Հռոմին։", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["Ավրելիանոսը հաղթեց Գալլական կայսրությանը. Հռոմը վերամիավորվեց", "c1a6a642"], "d": ["Ավրելիանոսը 274 թ. Կատալաունումում հաղթեց Տետրիկոսին. Գալիան, Բրիտանիան և Իսպանիան վերադարձան Հռոմին։ Կայսրությունը 14-ամյա բաժանումից հետո ամբողջացավ, և Ավրելիանոսը ստացավ «Restitutor Orbis» («աշխարհի վերականգնող») տիտղոսը։", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["Հուլիանոսը սալիական ֆրանկերին որպես հռոմեական ֆեդերատներ բնակեցրեց Տոքսանդրիայում", "0fb618fe"], "d": ["Կեսար Հուլիանոսը 358 թ. հաղթելով սալիական ֆրանկերին՝ թույլ տվեց բնակվել հռոմեական հողերում՝ Տոքսանդրիայում (այսօրվա Նիդեռլանդներ-Բելգիա սահման)։ Սա այն տարածքում, ուր պիտի ծնվեր Ֆրանկական թագավորությունը, հռոմեական հովանու տակ բնակեցման սկիզբն է։", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["Հոները, անցնելով Դոնը, հարձակվեցին ալանների և օստրոգոթերի վրա. Մեծ գաղթի սկիզբը", "659eb875"], "d": ["Ըստ Ամմիանոսի՝ հոները 375 թ. անցնելով Դոնը՝ հաղթեցին ալաններին, ապա կործանեցին օստրոգոթ արքա Էրմանարիկի թագավորությունը. այդ պատճառով վեստգոթ (տերվինգ) ժողովուրդը հենվեց Դանուբին։ Այսպիսով Եվրոպայում սկսվեց հոների տիրապետության դարաշրջանը։", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["Տերվինգ գոթերը, անցնելով Դանուբը, բնակվեցին հռոմեական հողերում", "3e9de0e6"], "d": ["Հոների ճնշման տակ Ֆրիտիգերնի տերվինգ գոթերը 376 թ. Վալենտից թույլտվություն ստացան անցնել Դանուբը և բնակվել հռոմեական հողերում. մատակարարման և կառավարման խնդիրները վերածվեցին ապստամբության։ Արդյունքը 378 թ. Ադրիանապոլսի (Էդիրնե) պարտությունն էր։", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["Վանդալները, ալանները և սվևները, անցնելով Ռենոսը, մտան Գալիա", "2b3354ba"], "d": ["Ավանդական 406 թ. դեկտեմբերի 31-ին (սառած Ռենոսի վրայով) վանդալները, ալանները և սվևները մտան հռոմեական Գալիա. Ռենոսի պաշտպանությունը փլուզվեց։ Ապա նրանց անցումը Իսպանիա (409) Արևմտյան Հռոմից պոկեց հիմնական նահանգները։", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["Վանդալները, ալանները և սվևները անցան Իսպանիա. Իսպանիան բաժանվեց", "b7036608"], "d": ["409 թ. աշնանը Գալիայից Պիրենեյներն անցած վանդալական, ալանական և սվևական խմբերը 411 թ. թերակղզին բաժանեցին իրար միջև. հասդինգներն ու սվևները ստացան Գալեցիան, սիլինգները՝ Բետիկան, ալանները՝ Լուսիտանիան և Կարթագինյան նահանգը։ Վեստգոթերը (416-418), ջախջախելով սիլինգներին և ալաններին, նախապատրաստեցին վանդալների անցումը Աֆրիկա։", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["Հռոմը վեստգոթերին բնակեցրեց Aquitania Secunda-ում. Թուլուզ կենտրոնով վեստգոթական թագավորությունը", "38a7699e"], "d": ["Կոնստանցիոսի ղեկավարությամբ Հռոմը Վալլիայի վեստգոթերին Իսպանիայում վանդալ-ալանների դեմ օգտագործելուց հետո 418 թ. որպես ֆեդերատներ բնակեցրեց Գարոնի հովտի Aquitania Secunda-ում։ Թուլուզ կենտրոնով վեստգոթական թագավորությունը համարվում է հռոմեական հողում առաջին գերմանական թագավորությունը։", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["Մարգուսի պայմանագիր. հոները Հռոմից ստացան տարեկան 700 լիբրա ոսկի", "833d8854"], "d": ["Հոն արքա Ռուայի մահից (433/4) հետո Աթթիլան և Բլեդան Մարգուսում պայմանագիր կնքեցին Արևելյան Հռոմի հետ. տարեկան խարաջը 350-ից հասցվեց 700 լիբրա ոսկու, հոն ապաստանյալները ետ տրվեցին։ Հոները Դանուբի սահմանին ձեռք բերեցին առևտրի իրավունք։", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["Հիպոնի պայմանագիր. Հռոմը վանդալներին ճանաչեց ֆեդերատներ Նումիդիայի և Մավրիտանիայի մի մասում", "f7dba59f"], "d": ["Վանդալական արքա Գեյզերիկը 429 թ. Աֆրիկա անցնելուց հետո 435 թ. Հռոմի հետ կնքեց Հիպոնի պայմանագիրը. վանդալները ֆեդերատների կարգավիճակով պահեցին Նումիդիայի և Մավրիտանիայի մի մասը։ Պայմանագիրը խախտվեց 439 թ. Կարթագենի գրավմամբ։", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["Աթթիլան վերցրեց Դանուբի ամրոցները. Վիմինացիումը և Սինգիդունումը (Բելգրադ) անցան հոներին", "0abb2c54"], "d": ["Արևելյան Հռոմի բանակի՝ Սիցիլիայի և վանդալական արշավանքում լինելու առիթով Աթթիլան 441 թ. անցավ Դանուբը. վերցվեցին Մարգուսը, Վիմինացիումը և Սինգիդունումը։ Սիրմիումը նույնպես ընկավ այս արշավանքներում, և հոները հասան Բալկանների խորքը։", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["Հռոմն ու վանդալները նոր պայմանագիր կնքեցին. Africa Proconsularis-ը, Byzacena-ն և Նումիդիայի մի մասը մնացին վանդալներին", "e5700ddc"], "d": ["Կարթագենը գրաված (439) Գեյզերիկը 442 թ. Վալենտինիանոս III-ի հետ կնքած պայմանագրով Africa Proconsularis-ը, Byzacena-ն, Abaritana-ն և Նումիդիայի մի մասը իրավականորեն դարձրեց վանդալական հող. Հռոմն իր ձեռքում պահեց միայն Մավրիտանիան և Նումիդիայի արևմուտքը։", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["Անատոլիոսի հաշտություն. Դանուբից հարավ լայն գոտի թողնվեց հոներին", "ee8ad838"], "d": ["Ուտուսի մոտ Արևելյան Հռոմի պարտությունից հետո Անատոլիոսը 447 թ. հաշտություն կնքեց Աթթիլայի հետ. Հռոմը հոներին թողեց Դանուբից հարավ՝ Սինգիդունումից մինչև Նովե ձգվող հինգ օրվա ճանապարհի լայնությամբ գոտի, տարեկան խարաջը հասցվեց 2100 լիբրա ոսկու։", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["Կատալաունյան (Շալոն) ճակատամարտ. Աեցիուսն ու Թեոդորիկ I-ը Աթթիլային դուրս մղեցին Գալիայից", "80f10e32"], "d": ["451 թ. Աթթիլան, մտնելով Գալիա, պաշարեց Օռլեանը. Աեցիուսի և վեստգոթ արքա Թեոդորիկ I-ի դաշինքը նրան ետ մղեց Կատալաունյան դաշտում (Թեոդորիկը զոհվեց)։ Այսպիսով հոների առաջխաղացումը Արևմտյան Եվրոպայում կանգ առավ։", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["Աթթիլան մտավ Իտալիա. Ակվիլեյան ավերվեց", "1349c67a"], "d": ["452 թ. Աթթիլան Ալպերի վրայով մտավ Հյուսիսային Իտալիա, հիմնահատակ ավերեց Ակվիլեյան և կողոպտեց Պո գետի հարթավայրը. հիվանդության և Արևելյան Հռոմի հակահարձակման պատճառով ետ քաշվեց։ Ակվիլեյայի փախստական բնակչությունը ծովալճակներում կազմեց Վենետիկի կորիզը։", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["Մահացավ Աթթիլան. հոնական պետությունը կազմալուծվեց", "47009384"], "d": ["Աթթիլան 453 թ. մահացավ հարսանիքի գիշերը. որդիների միջև բաժանումը և գերմանական հպատակների ապստամբությունը մեկ տարի անց Նեդաոյի մոտ (454) վերջ դրեցին հոնական գերակայությանը։ Հոները քաշվեցին Արևելյան Եվրոպա։", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["Էյրիխի վեստգոթական թագավորությունը փաստացի անջատվեց Հռոմից. Օվերնը թողնվեց վեստգոթերին", "4bbe7b0c"], "d": ["Էյրիխը 466-ից սկսած Իսպանիայում և Գալիայում նվաճումներով ընդլայնեց իր թագավորությունը. 475 թ. Հուլիոս Նեպոսը, թողնելով Օվերնը, փաստացի ճանաչեց նրա անկախ իշխանությունը։ Վեստգոթական թագավորությունը վերահսկում էր Արևմտյան Հռոմի հողերը Լուարից մինչև Միջերկրական ծով։", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["Հուլիոս Նեպոսը սպանվեց Դալմաթիայում. Արևմտյան Հռոմի վերջին օրինական կայսրը", "3b965f33"], "d": ["Ռոմուլոսի տապալումից հետո Դալմաթիա քաշված Նեպոսը սպանվեց 480 թ.. նրա մահից հետո Արևմտյան Հռոմի գահը պահանջող չմնաց, և Օդոակրը Իտալիայում իր փաստացի իշխանությունը շարունակեց Զենոնի անունով։", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["Թեոդորիկը օստրոգոթերին մտցրեց Իտալիա. Իզոնցոյում և Վերոնայում Օդոակրը պարտվեց", "6a998bf8"], "d": ["Արևելյան Հռոմի կայսր Զենոնի հավանությամբ Թեոդորիկը 489 թ. մտավ Իտալիա, Իզոնցոյում և Վերոնայում հաղթեց Օդոակրին. Օդոակրը փակվեց Ռավեննայում։ Երեք տարվա պաշարումն ավարտվեց 493 թ. Ռավեննայի հանձնմամբ։", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["Թեոդորիկը սպանել տվեց Օդոակրին Ռավեննայում. Իտալիան անցավ Օստրոգոթական թագավորությանը", "5a2db0ed"], "d": ["Օդոակրի Իտալիայի թագավորության վերջը. ամբողջ Իտալիան (ներառյալ Ջենովա, Բրինդիզի, Արիչիա քաղաքները) անցավ Արևելագոթական (օստրոգոթական) թագավորությանը։ Ռավեննայի եռամյա պաշարումից հետո 493 թ. մարտին Օդոակրն ու Թեոդորիկը համաձայնեցին համատեղ կառավարման շուրջ. ապա Թեոդորիկը խնջույքի ժամանակ սպանեց Օդոակրին։ Իտալիան Արևելյան Հռոմի հավանությամբ դարձավ Օստրոգոթական թագավորություն, որի մայրաքաղաքը Ռավեննան է։", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["Սամոսի հաշտությունը. Քուշի դեսպանները հաշտություն ստացան Օգոստոսից. Հռոմը վերացրեց Քուշին դրած հարկը, սահմանը գծվեց Ստորին Նուբիայում (Հիերա Սյուկամինոս)", "c3c4c20d"], "d": ["Կանդակեի դեսպանները Պետրոնիուսի ուղղորդմամբ գնացին Սամոս, որտեղ գտան Օգոստոսին. Օգոստոսը ընդունեց նրանց բոլոր խնդրանքները և վերացրեց նաև Պետրոնիուսի՝ Քուշին դրած հարկերը։ Հաշտության արդյունքում հռոմեա-քուշական սահմանը հաստատվեց Ֆիլեից հարավ՝ Հիերա Սյուկամինոսի (Մահառակա) գծով, և մոտ երեք հարյուր տարի լուրջ բախում չեղավ։", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["Պետրոնիուսը արշավեց Քուշի դեմ և գրավեց Պսելկիսը, Պրեմնիսը և Նապատան. Իբրիմում կայազոր տեղակայեց", "4884ed51"], "d": ["Պրեֆեկտ Պետրոնիուսը մոտ տասը հազար հետևակով և ութ հարյուր ձիավորով հաղթեց Քուշի երեսուն հազար զինվորին, վերցրեց Պսելկիսը, առաջին գրոհով գրավեց Պրեմնիսի (Քասր Իբրիմ) բերդը և հիմնահատակ ավերեց Նապատան, որտեղ գտնվում էր Կանդակեի պալատը։ Ավելի առաջ գնալը դժվար համարելով՝ վերադառնալիս Պրեմնիսում թողեց չորս հարյուր հոգուց բաղկացած կայազոր՝ երկու տարվա պարենով։ Երբ Կանդակեն փորձեց հետ վերցնել Պրեմնիսը, Պետրոնիուսը հասավ և պաշտպանեց բերդը։", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["Կանդակեի առաջնորդությամբ Քուշը գրավեց Էլեֆանտինեն, Սիենեն և Ֆիլեն. կործանեց Օգոստոսի արձանները", "aa665fad"], "d": ["Էլիուս Գալլուսի արաբական արշավանքի համար Եգիպտոսում գտնվող հռոմեական ուժերի մի մասը հետ քաշվելուց հետո քուշերը մտան Թեբայիս. հաղթելով Սիենեի երեք կոհորտից բաղկացած կայազորին՝ գրավեցին Սիենեն, Էլեֆանտինեն և Ֆիլեն, բնակչությունը գերեցին և տապալեցին Կեսարի արձանները։ Ստրաբոնը գրում է, որ այդ ժամանակ Քուշը կառավարող թագուհին «Կանդակե» տիտղոսով միաչք կին էր։", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["Կորնելիուս Գալլուսը դարձավ Եգիպտոսի առաջին պրեֆեկտը. ճնշեց Հերոոնպոլիսի և Թեբեի ապստամբությունները, Քուշի հետ սահմանը ապահովվեց", "9f688855"], "d": ["Օկտավիանոսը Եգիպտոսը դարձրեց հարկատու հատուկ նահանգ և նրա կառավարումը հանձնեց ոչ թե սենատորի, այլ ձիավորների դասի պրեֆեկտի. առաջին պրեֆեկտը դարձավ Կորնելիուս Գալլուսը։ Ստրաբոնը գրում է, որ Գալլուսը փոքրաթիվ զինվորներով վերցրեց Հերոոնպոլիսում ապստամբած մի ավան և կարճ ժամանակում ճնշեց Թեբեում հարկերի պատճառով բռնկված ապստամբությունը։ Ֆիլեի Գալլուսի կոթողը հայտնում է, որ այստեղ ընդունվել են Քուշի տիրակալի դեսպանները, և Տրիակոնտասխոյնոս մարզը վերցվել է պաշտպանության տակ։", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["Օկտավիանոսը մտավ Ալեքսանդրիա. վերացավ Պտղոմեոսյան պետությունը, Եգիպտոսն անցավ Հռոմին", "553804ca"], "d": ["Այն բանից հետո, երբ Անտոնիոսի նավատորմը և հեծելազորը անցան Օկտավիանոսի կողմը, Օկտավիանոսը մտավ Ալեքսանդրիա. Անտոնիոսը ինքնասպան եղավ, իսկ Կլեոպատրան էլ շուտով մահացավ։ Օկտավիանոսը ներեց Ալեքսանդրիայի բնակիչներին, ասելով՝ «ես ուզում էի թագավոր տեսնել, ոչ թե մեռյալներ», չայցելեց Պտղոմեոսյանների դամբարանները և Եգիպտոսը որպես հարկատու երկիր հանձնեց Կորնելիուս Գալլուսին։ Այս թվականով վերացավ երեք հարյուրամյա Պտղոմեոսյան թագավորությունը։", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["Ակցիումի ծովամարտ. Օկտավիանոսը հաղթեց Անտոնիոսին և Կլեոպատրային", "7e46cc73"], "d": ["Օկտավիանոսի նավատորմը Ակցիումում հաղթեց Անտոնիոսի և Կլեոպատրայի նավատորմին. զույգը քաշվեց Եգիպտոս։ Դիոնը, որպես ամսաթիվ տալուց խուսափող հեղինակ, հատուկ նշում է այս օրը, քանի որ դրանից հետո Օկտավիանոսը կայսրությունը մենակ պահեց իր ձեռքում, և իշխանության տարիները հաշվվեցին այս օրից։", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["Ալեքսանդրյան պարգևները. Անտոնիոսը Կլեոպատրային և նրա երեխաներին հռչակեց արևելյան թագավորությունների տիրակալներ", "24e24981"], "d": ["Գիմնասիոնում հավաքված բազմության առջև ոսկե գահեր դնել տված Անտոնիոսը Կլեոպատրային հռչակեց Եգիպտոսի, Կիպրոսի, Լիբիայի և Կոյլե-Սիրիայի թագուհի, Կեսարիոնին՝ նրա համաիշխան, իսկ երեխաներին՝ Հայաստանի, Մարաստանի, Պարթևաստանի և Փյունիկիա-Սիրիա-Կիլիկիայի թագավորներ։ Հռոմում այս արարողությունը վերածվեց Անտոնիոսի դեմ քարոզչության և արագացրեց քաղաքացիական պատերազմը։", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["Անտոնիոսը Կլեոպատրային նվիրեց Կիպրոսը, Փյունիկիան, Կոյլե-Սիրիան և Կիլիկիայի մի մասը", "cf19a357"], "d": ["Ըստ Պլուտարքոսի՝ Անտոնիոսը, գալով Սիրիա, Կլեոպատրային տվեց Փյունիկիան, Կոյլե-Սիրիան, Կիպրոսը, Կիլիկիայի մեծ մասը, Հրեաստանի բալասան տվող հատվածը և Նաբաթեայի դեպի ծով ձգվող մասը։ Այդպիսով Պտղոմեոսյան պետությունը Պտղոմեոս III-ից ի վեր առաջին անգամ (չնայած Հռոմի զայրույթին) վերահսկեց Արևելյան Միջերկրականի ընդարձակ տարածք։", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["Ալեքսանդրյան պատերազմ. Կեսարը հաղթեց Պտղոմեոս XIII-ին, Եգիպտոսը թողեց Կլեոպատրային", "96c9b516"], "d": ["Երբ Կեսարը, գալով Ալեքսանդրիա, ցանկացավ միջնորդ լինել Կլեոպատրայի և Պտղոմեոս XIII-ի միջև, պալատական ուժերը պաշարեցին նրան. ամբողջ ձմեռը տևած փողոցային մարտերի ժամանակ Կեսարին օգնություն եկավ, և Նեղոսի ճակատամարտում Պտղոմեոս XIII-ը խեղդվեց։ Կեսարը Եգիպտոսը տվեց Կլեոպատրային և նրա կրտսեր եղբայր Պտղոմեոս XIV-ին. հռոմեական լեգեոնները մնացին Ալեքսանդրիայում։", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["Գաբինիուսը հռոմեական բանակով Պտղոմեոս XII-ին վերադարձրեց Եգիպտոսի գահին. Ալեքսանդրիայում մնաց հռոմեական կայազոր", "41d8f47d"], "d": ["Վտարված Պտղոմեոս XII-ը (Ավլետես), մեծ կաշառք տալով Սիրիայի կուսակալ Գաբինիուսին, գնեց մուտքը Եգիպտոս. Գաբինիուսը, թողնելով պարթևական արշավանքը, Պելուսիումից մտավ Եգիպտոս և Ավլետեսին վերադարձրեց գահին։ Դա այն պահն է, երբ Եգիպտոսի անկախությունը փաստացի կապվեց Հռոմի երաշխիքին։ Գաբինիուսը հետագայում դատվեց Հռոմում։", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["Հռոմը Կիպրոսը վերցնելով Պտղոմեոսյաններից՝ բռնակցեց. Կատոնը ուղարկվեց կղզի", "678b2115"], "d": ["Պտղոմեոս XII-ի եղբայր Կիպրոսի թագավորը չդիմադրեց, որ Հռոմը Կլոդիուսի առաջարկով վերցնի կղզին. Կատոնը ուղարկվեց ստանձնելու կղզին։ Պտղոմեոսյան պետությունը կորցրեց Կիպրոսը և ափին մնացած իր վերջին ծովային հենակայանը։ Պլուտարքոսը Կատոնի՝ «Կիպրոս ուղարկվելը» հիշատակում է Պոմպեոսի կենսագրության մեջ։", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["«Էլևսիսի օրը». հռոմեական դեսպան Պոպիլիուս Լենասը Անտիոքոս IV-ին ստիպեց հետ քաշվել Եգիպտոսից", "e6883e6a"], "d": ["Պիդնայի ճակատամարտից (մ.թ.ա. 168 թվականի հունիսի 22) անմիջապես հետո հռոմեական դեսպան Գայոս Պոպիլիուս Լենասը Ալեքսանդրիան պաշարող Անտիոքոսին փոխանցեց սենատի՝ պատերազմը դադարեցնելու հրամանը. որպեսզի թագավորը մտածի պատասխանի մասին, նրա շուրջ շրջան գծեց։ Անտիոքոսը հետ քաշվեց։ Եգիպտոսը շարունակեց պահպանել անկախությունը՝ Հռոմի պաշտպանությամբ առանց այն կորցնելու։", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["Անտիոքոս IV-ը հարձակվեց Եգիպտոսի վրա. Սիրիական վեցերորդ պատերազմում առաջացավ մինչև Մեմֆիս և Նաուկրատիս", "b85e6712"], "d": ["Անտիոքոս IV-ը, ի պատասխան Պտղոմեոս VI-ի՝ Կոյլե-Սիրիան հետ վերցնելու նախապատրաստության, մտավ Եգիպտոս և Պելուսիումից իջավ Նեղոս. պաշտպանեց Կոյլե-Սիրիայի նկատմամբ իր իրավունքը և Նաուկրատիսում լավ վերաբերվեց բնակչությանը։ Պատերազմը, առանց Եգիպտոսը կործանելու, բայց պետությունը թուլացնելով, Հռոմի միջամտությամբ ավարտվեց մեկ տարի անց։", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["Թեբեի ապստամբությունը ճնշվեց. Կոմանոսը Վերին Եգիպտոսը վերադարձրեց Պտղոմեոսյան տիրապետությանը", "4c0e4f10"], "d": ["Մոտ քսան տարվա անջատողական կառավարումից հետո պտղոմեոսյան զորավար Կոմանոսը Թեբեն հետ վերցրեց տեղական փարավոն Անխվեննեֆերից, և Վերին Եգիպտոսը վերստին կապվեց Պտղոմեոսյան պետությանը։", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["Մեմֆիսի սինոդը հրապարակեց Ռոզետտայի հրովարտակը. Պտղոմեոս V-ը տաճարներին հարկային պարգևներ շնորհեց", "5643b91f"], "d": ["Եգիպտացի քրմերի՝ Մեմֆիսում հրավիրած սինոդը հաստատեց Պտղոմեոս V-ի գահակալումը և հռչակեց թագավորի՝ տաճարներին արած հարկային պարգևները, ապստամբությունների ճնշումը և թագավորի պաշտամունքի հիմնումը։ Հրովարտակը գրվեց հունարեն, դեմոտիկ և հիերոգլիֆներով. Ռոզետտայի քարը այս եռալեզու տեքստն է։ Տեքստը միաժամանակ ակնարկում է Դելտայի ապստամբների (Լիկոպոլիս) ճնշումը։", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["Պանիոնի ճակատամարտ. Անտիոքոս III-ը հաղթեց Սկոպասին. Կոյլե-Սիրիան Պտղոմեոսյաններից անցավ Սելևկյաններին", "97e30e58"], "d": ["Սիրիական հինգերորդ պատերազմում Անտիոքոս III-ը Պանեիոնում ջախջախեց պտղոմեոսյան զորավար Սկոպաս Էտոլացուն. ըստ Հովսեպոսի՝ Անտիոքոսը հետ վերցրեց Սկոպասի գրաված Կոյլե-Սիրիայի քաղաքները, վերցրեց նաև Սամարիան, իսկ հրեաները իրենց կամքով միացան Անտիոքոսին։ Կոյլե-Սիրիան (Սիրիա-Պաղեստին) դրանից հետո անցավ սելևկյան կառավարման, Պտղոմեոսյան պետությունը հեռացավ մարզից։", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["Թեբեում հայտնվեցին անջատողական տեղական փարավոններ. Վերին Եգիպտոսը պոկվեց պտղոմեոսյան տիրապետությունից", "d10abb36"], "d": ["Ռաֆիայի հաղթանակից հետո զինված բնիկ եգիպտացիները, Պոլիբիոսի խոսքով, հաղթանակից ուռչելով՝ այլևս չէին ենթարկվում թագավորի հրամանին. Դելտայում և Վերին Եգիպտոսում ապստամբություններ բռնկվեցին։ Թեբեում տեղական փարավոնները (Հորվեննեֆեր, ապա Անխվեննեֆեր) մոտ քսան տարի Վերին Եգիպտոսը պահեցին իրենց ձեռքում ընդդեմ Պտղոմեոսի։", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["Ռաֆիայի ճակատամարտ. Պտղոմեոս IV-ը հաղթեց Անտիոքոս III-ին. Կոյլե-Սիրիան մնաց Պտղոմեոսին", "34362178"], "d": ["Ռաֆիայում Պտղոմեոս IV-ի բանակը, որի կազմում կար մեծաթիվ բնիկ եգիպտացի ֆալանգա (հոպլիտ), հաղթեց Անտիոքոս III-ի բանակին. Անտիոքոսը հեռացավ Կոյլե-Սիրիայից, և մարզը մինչև 200 թվականը մնաց Պտղոմեոսի ձեռքում։ Բնիկ եգիպտացիների զինումը հետագայում սնեց Վերին Եգիպտոսի անջատողական ապստամբությունները։", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["Անտիոքոս III-ը Սելևկիա Պիերիան հետ վերցրեց Պտղոմեոսյաններից", "39ee3a52"], "d": ["Անտիոքոս III-ը պաշարեց Պտղոմեոսի ձեռքում գտնվող Սելևկիա Պիերիան և, կաշառելով սպաներին, վերցրեց այն. Պոլիբիոսը գրում է, որ քաղաքը Պտղոմեոս III-ի ժամանակներից պահվում էր Եգիպտոսի թագավորներին պատկանող կայազորի կողմից։ Այս հաղթանակով Սելևկյանները ձեռք բերեցին Անտիոքի նավահանգիստը և պատրաստվեցին արշավել Կոյլե-Սիրիա (Սիրիական չորրորդ պատերազմ)։", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["Պտղոմեոս III-ը Լաոդիկեի պատերազմում զբաղեցրեց Սիրիան և Միջագետքը. Սելևկիա Պիերիան անցավ Պտղոմեոսի ձեռքը", "04472253"], "d": ["Պտղոմեոս II-ը մահացավ մ.թ.ա. 246 թվականի հունվարի 28-ին. Պտղոմեոս III-ը, իր քույր Բերենիկեին պաշտպանելու նպատակով, հարձակվեց Սելևկյան պետության վրա։ Սելևկիա Պիերիայում և Անտիոքում նրան դիմավորեցին. Բաբելոնյան տարեգրությունը (BCHP 11) հայտնում է, որ նրա բանակը մ.թ.ա. 246 թվականի դեկտեմբերից մոտեցել էր Բաբելոնին։ Ադուլիսի արձանագրությունը պնդում է, որ նա նվաճել է Եփրատից արևմուտք ընկած հողերը, Կիլիկիան, Պամֆիլիան և Թրակիան։ Սելևկիա Պիերիան երկար տարիներ մնաց Պտղոմեոսի ձեռքում։", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["Իպսոսից հետո Պտղոմեոսը զբաղեցրեց Կոյլե-Սիրիան. Սելևկոսը բողոքեց (Սիրիական պատերազմների արմատը)", "a109388f"], "d": ["Իպսոսի ճակատամարտից (մ.թ.ա. 301) հետո Սելևկոսը, Լիսիմաքոսը և Կասանդրոսը, համաձայնության գալով, ամբողջ Սիրիան տվեցին Սելևկոսին. իսկ Պտղոմեոսը իր զորքով զբաղեցրեց և պահեց Կոյլե-Սիրիան։ Այս տարաձայնությունը հաջորդ երկու հարյուր տարում ծնեց Սիրիական վեց պատերազմ։ Անտիոքոս III-ը հետագայում պաշտպանեց այս պնդումը, ինչպես փոխանցում է Պոլիբիոսը։", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["Պտղոմեոսը իրեն հռչակեց թագավոր. պաշտոնապես հիմնվեց Պտղոմեոսյան հարստությունը", "008c723a"], "d": ["Անտիգոնոսի և Դեմետրիոսի՝ թագավորի տիտղոս ընդունելուց (մ.թ.ա. 306) հետո Պտղոմեոսը նույնպես ընդունեց թագավորի տիտղոսը. Եգիպտոսը սկսեց հիշատակվել որպես անկախ հելլենիստական թագավորություն։ Հարստության ներկայացումը որպես Եգիպտոսի փարավոն արագացրեց նաև փոխզիջումը տեղական քրմական դասի հետ։", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["Գազայի ճակատամարտ. Պտղոմեոսը և Սելևկոսը հաղթեցին Դեմետրիոսին (Սիրիան կարճ ժամանակով Պտղոմեոսի ձեռքում)", "ea0d264f"], "d": ["Անտիգոնոսի որդի Դեմետրիոսը Գազայի առջև պարտվեց Պտղոմեոսի և Սելևկոսի միացյալ բանակին. Պտղոմեոսը մտավ Կոյլե-Սիրիա։ Անտիգոնոսի հակաքայլով մարզը կարճ ժամանակ անց վերստին կորսվեց, և հաշտությունը (մ.թ.ա. 311) ամրագրեց դա։", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["Պերդիկասի եգիպտական արշավանքը ձախողվեց Նեղոսի անցման ժամանակ. Պերդիկասը սպանվեց իր բանակի ձեռքով", "c1792117"], "d": ["Դիադոքոսների պատերազմում Ալեքսանդր Մակեդոնացու ռեգենտ Պերդիկասը մտավ Եգիպտոս Պտղոմեոսի դեմ, որը առևանգել էր Ալեքսանդրի թաղման թափորը, սակայն չկարողացավ անցնել Նեղոսը, բազմաթիվ մարդ կորցրեց և սպանվեց իր սպաների ձեռքով։ Պտղոմեոսը պահեց Եգիպտոսը իր ձեռքում։", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["Պտղոմեոսը Կյուրենեն (Կիրենայիկան) միացրեց Եգիպտոսին", "65316c50"], "d": ["Պտղոմեոսը, միջամտելով Կյուրենեի ներքին գժտությանը, Օֆելասի հրամանատարությամբ Լիբիայի Կիրենայիկա մարզը կապեց Եգիպտոսին։ Այդպիսով Պտղոմեոսյան Եգիպտոսը ընդարձակվեց նաև դեպի արևմուտք. Կիրենայիկան հետագա դարերում մնաց Պտղոմեոսյան հարստության մի ճյուղի ձեռքում։", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["Ալեքսանդրը Սիվա օազիսում դիմեց Ամմոնի պատգամախոսին", "c437ced0"], "d": ["Ալեքսանդրը, ափից անապատ անցնելով, գնաց Սիվա օազիս, որտեղ գտնվում էր Ամմոնի տաճարը, և դիմեց պատգամախոսին. Արրիանոսը գրում է, որ նա ստացավ իր սիրտը հաճոյացնող պատասխան։ Այս այցը սնեց Ալեքսանդրի լեգիտիմությունը Եգիպտոսում և հետագայում նրան աստծու որդի համարելու պատումները։", "40603afa"]}
});
